select 'nsca-cscs-5', 'NSCA CSCS Exam Description', 'https://www.nsca.com/cscs-exam-description/', 'official', 4, now(), '{"source_key":"nsca-cscs-dco"}'::jsonb
where not exists (select 1 from public.sources where certification_id = 'nsca-cscs-5' and metadata->>'source_key' = 'nsca-cscs-dco');

insert into public.lessons (
  certification_id, task_id, language, title, summary, content,
  source_refs, version, status, published_at
)
values
  ('nsca-cscs-5', 'w1-0', 'en', 'w1-0', 'A diagnostic is a map, not a grade. Sample every exam domain under light time pressure, record confidence as well as correctness, and use the result to set study priorities.', '{"minutes":25,"source":"Ch. 1-2 · Diagnostic protocol","summary":{"en":"A diagnostic is a map, not a grade. Sample every exam domain under light time pressure, record confidence as well as correctness, and use the result to set study priorities.","zh":"诊断测试不是成绩，而是一张地图。用轻度计时覆盖所有考试领域，同时记录正确率和信心，再据此安排学习优先级。"},"points":[{"en":"Answer before reviewing: retrieval reveals the real baseline.","zh":"先作答再复习，主动提取才能暴露真实基线。"},{"en":"Tag every miss as knowledge, application, reading, or calculation error.","zh":"把错题标记为知识、应用、审题或计算错误。"},{"en":"Compare domain accuracy with official weighting; a high-weight weak domain comes first.","zh":"结合官方权重看领域正确率，高权重薄弱领域优先。"}],"application":{"en":"After a 30-item set, calculate accuracy by domain and select the two weakest high-weight domains for the next seven days.","zh":"完成 30 题后按领域计算正确率，选出两个权重高且最薄弱的领域作为未来七天重点。"},"recall":{"en":"Why is a single overall percentage insufficient for planning?","zh":"为什么仅看总正确率不足以制定计划？"},"answer":{"en":"It hides domain imbalance and error type. Planning needs domain-weighted accuracy plus an error classification.","zh":"总分会掩盖领域差异和错误类型；计划需要领域加权正确率与错误分类。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w1-1', 'en', 'w1-1', 'Force begins with neural activation and ends with cross-bridge cycling. Understand the chain from motor neuron to muscle fiber instead of memorizing isolated anatomy labels.', '{"minutes":30,"source":"Ch. 1 · Musculoskeletal and neuromuscular systems","summary":{"en":"Force begins with neural activation and ends with cross-bridge cycling. Understand the chain from motor neuron to muscle fiber instead of memorizing isolated anatomy labels.","zh":"力量从神经激活开始，以横桥循环产生张力结束。应理解运动神经元到肌纤维的完整链条，而不是孤立背解剖名词。"},"points":[{"en":"A motor unit is one alpha motor neuron and all fibers it innervates; recruitment generally follows the size principle.","zh":"运动单位由一个 α 运动神经元及其支配的全部肌纤维组成；募集通常遵循大小原则。"},{"en":"Calcium binds troponin, shifts tropomyosin, and exposes actin sites for myosin cross-bridges.","zh":"钙与肌钙蛋白结合，使原肌球蛋白移位，暴露肌动蛋白位点供肌球蛋白形成横桥。"},{"en":"Type I fibers resist fatigue; type II fibers develop force and power faster but fatigue sooner.","zh":"I 型纤维抗疲劳；II 型纤维产生力量和功率更快，但更易疲劳。"}],"application":{"en":"Early strength gains in a novice are primarily neural: better recruitment, rate coding, coordination, and reduced inhibitory constraints precede large hypertrophy.","zh":"初学者早期力量增长主要来自神经适应：募集、放电频率、协调以及抑制降低通常先于明显肥大。"},"recall":{"en":"Trace excitation-contraction coupling from the motor neuron to sarcomere shortening.","zh":"从运动神经元开始，口述兴奋-收缩耦联直到肌节缩短。"},"answer":{"en":"Action potential → acetylcholine at the neuromuscular junction → muscle membrane/T-tubule depolarization → sarcoplasmic reticulum releases calcium → troponin-tropomyosin shift → ATP-driven cross-bridge cycling.","zh":"动作电位 → 神经肌肉接头释放乙酰胆碱 → 肌膜/T 管去极化 → 肌浆网释放钙 → 肌钙蛋白-原肌球蛋白移位 → ATP 驱动横桥循环。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w1-2', 'en', 'w1-2', 'Biomechanics questions become easier when every movement is reduced to plane, axis, force, moment arm, torque, work, and power.', '{"minutes":30,"source":"Ch. 2 · Biomechanics","summary":{"en":"Biomechanics questions become easier when every movement is reduced to plane, axis, force, moment arm, torque, work, and power.","zh":"把动作拆成平面、轴、力、力臂、力矩、功和功率，生物力学题会更容易。"},"points":[{"en":"Sagittal-plane flexion/extension occurs around a mediolateral axis; frontal abduction/adduction around an anteroposterior axis; transverse rotation around a longitudinal axis.","zh":"矢状面屈伸绕左右轴；额状面外展内收绕前后轴；水平面旋转绕纵轴。"},{"en":"Torque equals force times the perpendicular moment arm. Changing joint position changes torque even when load stays constant.","zh":"力矩等于力乘垂直力臂。即使负荷不变，关节位置变化也会改变力矩。"},{"en":"Work is force through displacement; power is work per time and can also be expressed as force times velocity.","zh":"功是力作用于位移；功率是单位时间的功，也可表示为力乘速度。"}],"application":{"en":"A dumbbell feels hardest near the position where its perpendicular moment arm about the joint is greatest, not simply where the hand is highest.","zh":"哑铃最难的位置通常是相对关节的垂直力臂最大处，而不只是手最高的位置。"},"recall":{"en":"If external force stays constant and the moment arm doubles, what happens to external torque?","zh":"外力不变、力臂加倍时，外部力矩如何变化？"},"answer":{"en":"Torque doubles because torque = force × perpendicular moment arm.","zh":"力矩加倍，因为力矩 = 力 × 垂直力臂。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w1-3', 'en', 'w1-3', 'Flashcards work only when they force retrieval. Build cards around decisions, contrasts, and relationships rather than copying definitions.', '{"minutes":20,"source":"Ch. 1-2 · Retrieval practice","summary":{"en":"Flashcards work only when they force retrieval. Build cards around decisions, contrasts, and relationships rather than copying definitions.","zh":"闪卡只有在迫使你主动提取时才有效。卡片应围绕决策、对比和关系，而不是照抄定义。"},"points":[{"en":"One card, one testable idea; keep the prompt precise.","zh":"一卡一知识点，问题必须明确。"},{"en":"Use bidirectional cards for terminology: structure → function and function → structure.","zh":"术语使用双向卡：结构→功能、功能→结构。"},{"en":"Add an example or common distractor to the answer side.","zh":"答案面加入例子或常见干扰项。"}],"application":{"en":"Create cards for motor unit, sarcomere, type I vs II fibers, planes and axes, torque, work, and power. Review missed cards again tomorrow and in three days.","zh":"为运动单位、肌节、I/II 型纤维、平面与轴、力矩、功和功率制作卡片；错卡在明天和三天后再次复习。"},"recall":{"en":"What makes a recall card better than a copied paragraph?","zh":"为什么主动回忆卡比复制段落更有效？"},"answer":{"en":"A focused prompt requires reconstruction from memory and gives a clear right-or-wrong check; copied text mainly encourages recognition.","zh":"聚焦的问题要求从记忆中重建答案，并能明确判断对错；复制文字主要训练熟悉感。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w2-0', 'en', 'w2-0', 'All three energy systems operate at once; intensity, duration, substrate availability, and recovery determine which contributes most.', '{"minutes":30,"source":"Ch. 3 · Bioenergetics","summary":{"en":"All three energy systems operate at once; intensity, duration, substrate availability, and recovery determine which contributes most.","zh":"三大供能系统始终同时工作；强度、持续时间、底物和恢复决定哪一个占主导。"},"points":[{"en":"The phosphagen system supplies the fastest ATP for very short maximal work but has limited capacity.","zh":"磷酸原系统供 ATP 最快，适合极短最大强度工作，但容量有限。"},{"en":"Fast glycolysis supports high-intensity work lasting beyond the immediate phosphagen window and produces metabolites associated with fatigue.","zh":"快速糖酵解支持超过磷酸原即时窗口的高强度工作，并产生与疲劳相关的代谢物。"},{"en":"Oxidative metabolism is slower but high-capacity and becomes increasingly important as duration and recovery increase.","zh":"氧化代谢速度较慢但容量高，随着持续时间和恢复增加而更重要。"}],"application":{"en":"A six-second maximal sprint is phosphagen-dominant; repeated sprints progressively increase glycolytic and oxidative contribution when recovery is incomplete.","zh":"6 秒最大冲刺以磷酸原为主；恢复不完全时，重复冲刺会逐渐增加糖酵解和氧化供能贡献。"},"recall":{"en":"Why is it inaccurate to say an activity uses only one energy system?","zh":"为什么说某项运动只使用一种供能系统是不准确的？"},"answer":{"en":"ATP demand is shared continuously; the relative contribution changes with task intensity, duration, and recovery.","zh":"ATP 需求由三套系统持续共同承担，只是相对贡献随强度、时间和恢复变化。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w2-1', 'en', 'w2-1', 'Work-to-rest ratios are a starting framework. The real target is preserving the output and energy-system stress required by the sport.', '{"minutes":25,"source":"Ch. 3 · Work-to-rest specificity","summary":{"en":"Work-to-rest ratios are a starting framework. The real target is preserving the output and energy-system stress required by the sport.","zh":"做功-休息比只是起点，真正目标是维持专项需要的输出质量和供能系统压力。"},"points":[{"en":"Very short maximal power bouts require long recovery to restore phosphocreatine and preserve peak output.","zh":"极短最大功率训练需要较长恢复，以恢复磷酸肌酸并维持峰值输出。"},{"en":"Glycolytic intervals use moderate recovery and accept a controlled decline in output.","zh":"糖酵解间歇采用中等恢复，并允许输出受控下降。"},{"en":"Aerobic intervals usually use shorter relative recovery because oxidative metabolism supports repeated work.","zh":"有氧间歇相对恢复较短，因为氧化代谢支持重复工作。"}],"application":{"en":"If sprint times deteriorate beyond the session goal, increase rest or end the set; accumulating slow repetitions no longer trains maximal speed.","zh":"若冲刺成绩下降超过训练目标，应增加休息或结束该组；堆积慢速重复已不再训练最大速度。"},"recall":{"en":"For maximal six-second sprints, why is 1:1 recovery usually too short?","zh":"最大 6 秒冲刺为何通常不适合 1:1 恢复？"},"answer":{"en":"Phosphocreatine restoration and neural recovery are incomplete, so later repetitions lose the intended maximal-power quality.","zh":"磷酸肌酸和神经恢复不足，后续重复无法保持目标最大功率质量。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w2-2', 'en', 'w2-2', 'Adaptation is specific to the imposed demand. Link each training variable to neural, muscular, endocrine, cardiovascular, and metabolic changes.', '{"minutes":35,"source":"Ch. 4-6 · Training adaptations","summary":{"en":"Adaptation is specific to the imposed demand. Link each training variable to neural, muscular, endocrine, cardiovascular, and metabolic changes.","zh":"适应具有专项性。要把每个训练变量与神经、肌肉、内分泌、心血管和代谢变化联系起来。"},"points":[{"en":"Anaerobic training improves neural drive, rate of force development, hypertrophy, connective-tissue tolerance, and high-rate ATP production.","zh":"无氧训练可改善神经驱动、力量发展率、肌肥大、结缔组织耐受和高速度 ATP 生成。"},{"en":"Aerobic training increases mitochondrial and capillary density, stroke volume, oxidative enzymes, and substrate efficiency.","zh":"有氧训练增加线粒体与毛细血管密度、每搏输出量、氧化酶和底物利用效率。"},{"en":"Concurrent training interference depends on volume, intensity, mode, sequencing, recovery, and athlete status—not merely the presence of cardio.","zh":"并行训练干扰取决于量、强度、方式、顺序、恢复和训练水平，并非只要有有氧就一定干扰。"}],"application":{"en":"Separate high-priority strength/power work from demanding endurance work when possible, and monitor whether performance in the priority quality is declining.","zh":"尽可能把高优先级力量/功率训练与高负荷耐力训练分开，并监控优先能力是否下降。"},"recall":{"en":"Name two central and two peripheral aerobic adaptations.","zh":"说出两项中枢和两项外周有氧适应。"},"answer":{"en":"Central examples: increased stroke volume and maximal cardiac output. Peripheral examples: greater capillary/mitochondrial density and oxidative enzyme activity.","zh":"中枢示例：每搏输出量和最大心输出量增加；外周示例：毛细血管/线粒体密度及氧化酶活性增加。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w2-3', 'en', 'w2-3', 'Use questions to connect mechanisms to programming decisions. The exam commonly asks what changes, why it changes, and which training choice best targets it.', '{"minutes":25,"source":"Ch. 3-6 · Exercise science integration","summary":{"en":"Use questions to connect mechanisms to programming decisions. The exam commonly asks what changes, why it changes, and which training choice best targets it.","zh":"用题目把机制与计划决策连接起来。考试常问变化是什么、为何变化、哪种训练选择最匹配。"},"points":[{"en":"Predict the dominant demand before looking at options.","zh":"看选项前先判断主要需求。"},{"en":"Eliminate answers that confuse acute responses with chronic adaptations.","zh":"排除把急性反应与长期适应混淆的选项。"},{"en":"Check whether the proposed rest interval preserves quality or deliberately creates fatigue.","zh":"判断休息时间是在保持质量，还是有意制造疲劳。"}],"application":{"en":"For every missed item, write one programming rule such as: maximal power requires high intent and sufficient recovery.","zh":"每道错题写出一条计划规则，例如：最大功率训练需要高意图和充分恢复。"},"recall":{"en":"What distinction prevents many adaptation errors?","zh":"哪一个区分能避免大量适应类错误？"},"answer":{"en":"Separate an immediate response during/after exercise from a chronic adaptation produced by repeated exposure.","zh":"区分一次运动期间/之后的即时反应，与重复刺激产生的长期适应。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w3-0', 'en', 'w3-0', 'Training principles remain consistent across populations, but readiness, supervision, recovery, medical context, and loading progression must be individualized.', '{"minutes":35,"source":"Ch. 7-8 · Age and sex considerations","summary":{"en":"Training principles remain consistent across populations, but readiness, supervision, recovery, medical context, and loading progression must be individualized.","zh":"不同人群仍遵循相同训练原则，但准备度、监督、恢复、医疗背景和负荷进阶必须个体化。"},"points":[{"en":"Youth resistance training is appropriate with qualified supervision, technique mastery, and age-appropriate progression; chronological age alone is not readiness.","zh":"青少年在合格监督、技术掌握和合适进阶下可以进行抗阻训练；生理准备度不能只看年龄。"},{"en":"Older adults benefit from strength, power, balance, and aerobic work, with attention to comorbidities, medications, and recovery.","zh":"老年人可从力量、功率、平衡和有氧训练获益，同时需关注共病、药物和恢复。"},{"en":"Use individual performance and training history rather than stereotypes when programming for female athletes.","zh":"为女性运动员设计计划时应依据个体表现和训练史，而非刻板印象。"}],"application":{"en":"The best modification is often a change in starting load, complexity, supervision, or recovery—not removal of resistance training.","zh":"最佳调整通常是改变起始负荷、动作复杂度、监督或恢复，而不是取消抗阻训练。"},"recall":{"en":"List four readiness factors more useful than chronological age alone.","zh":"列出四个比单纯年龄更有用的准备度因素。"},"answer":{"en":"Training age, movement competency, maturity/health status, ability to follow instructions, supervision, and recovery capacity are valid examples.","zh":"训练年限、动作能力、成熟/健康状况、遵循指令能力、监督条件和恢复能力均可。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w3-1', 'en', 'w3-1', 'Psychological skills influence attention, effort, confidence, and execution. The coaching goal is to regulate—not eliminate—arousal and direct attention to controllable actions.', '{"minutes":30,"source":"Ch. 9 · Performance psychology","summary":{"en":"Psychological skills influence attention, effort, confidence, and execution. The coaching goal is to regulate—not eliminate—arousal and direct attention to controllable actions.","zh":"心理技能影响注意、努力、信心和执行。教练目标不是消除唤醒，而是调节唤醒并把注意导向可控行动。"},"points":[{"en":"Optimal arousal is task- and athlete-specific; fine motor tasks usually tolerate less arousal than gross power tasks.","zh":"最佳唤醒因任务和个体而异；精细动作通常比大肌群爆发任务更不耐受高唤醒。"},{"en":"Process goals and external-focus cues direct attention to execution rather than outcome anxiety.","zh":"过程目标和外部注意提示把注意导向执行，而非结果焦虑。"},{"en":"Autonomy, competence, and relatedness support self-determined motivation.","zh":"自主、胜任和关系感支持自我决定动机。"}],"application":{"en":"For an over-aroused athlete, use slow breathing, a brief routine, and one external cue. For under-arousal, use energizing movement, music, and assertive cueing when appropriate.","zh":"运动员唤醒过高时使用慢呼吸、简短流程和一个外部提示；唤醒不足时可根据情境使用激活动作、音乐和有力提示。"},"recall":{"en":"Convert an outcome goal into one controllable process goal.","zh":"把一个结果目标改写成可控的过程目标。"},"answer":{"en":"Instead of “win the race,” use a controllable execution target such as “hold the planned first-200 m rhythm and relaxed shoulders.”","zh":"不要只写“赢得比赛”，可改为“前 200 米保持计划节奏并放松肩部”等可控执行目标。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w3-2', 'en', 'w3-2', 'A strength coach observes, listens, supports, documents according to policy, and refers. The coach does not diagnose or provide psychotherapy.', '{"minutes":25,"source":"Ch. 9 · Mental-health scope and referral","summary":{"en":"A strength coach observes, listens, supports, documents according to policy, and refers. The coach does not diagnose or provide psychotherapy.","zh":"体能教练负责观察、倾听、支持、按政策记录和转介，不做诊断或心理治疗。"},"points":[{"en":"Use the ABC lens: changes in affect, behavior, and cognition.","zh":"使用 ABC 框架：情感、行为和认知变化。"},{"en":"Immediate safety concerns require the emergency or crisis procedure, not routine follow-up.","zh":"若存在即时安全风险，应启动紧急/危机流程，而不是普通随访。"},{"en":"Persistent changes that impair functioning warrant referral to a qualified professional.","zh":"持续且影响功能的变化需要转介合格专业人员。"}],"application":{"en":"Use a private, nonjudgmental statement: describe what you observed, express concern, listen, and connect the athlete with the designated resource.","zh":"私下、无评判地沟通：描述观察、表达关切、倾听，并帮助运动员联系指定资源。"},"recall":{"en":"What is the coach''s first responsibility when an athlete expresses imminent self-harm intent?","zh":"运动员表达即刻自伤意图时，教练的首要责任是什么？"},"answer":{"en":"Protect immediate safety and activate the organization''s emergency/crisis protocol; do not leave the person unsupported or attempt independent treatment.","zh":"保障即时安全并启动组织的紧急/危机流程；不要让其处于无人支持状态，也不要自行治疗。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w3-3', 'en', 'w3-3', 'An integrated checkpoint should test whether you can choose an appropriate coaching action, not just recall population facts.', '{"minutes":25,"source":"Ch. 7-9 · Foundations checkpoint","summary":{"en":"An integrated checkpoint should test whether you can choose an appropriate coaching action, not just recall population facts.","zh":"整合小测应检验你能否选择合适的教练行动，而不只是背人群事实。"},"points":[{"en":"Identify the population or psychological constraint in the stem.","zh":"识别题干中的人群或心理限制。"},{"en":"Keep universal training principles, then modify dose, complexity, supervision, or communication.","zh":"保留普适训练原则，再调整剂量、复杂度、监督或沟通。"},{"en":"Refer when the issue exceeds scope or creates a safety concern.","zh":"超出职责范围或存在安全风险时进行转介。"}],"application":{"en":"Create a one-page comparison grid for youth, older adults, female athletes, arousal regulation, motivation, and referral decisions.","zh":"制作一页对比表，覆盖青少年、老年人、女性运动员、唤醒调节、动机和转介决策。"},"recall":{"en":"What is the common logic across special-population questions?","zh":"特殊人群题目的共同逻辑是什么？"},"answer":{"en":"Individualize from a safe baseline using readiness and context; avoid automatic exclusion and unsupported assumptions.","zh":"依据准备度和情境从安全起点个体化；避免自动排除和无依据假设。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w4-0', 'en', 'w4-0', 'Nutrition questions require both calculations and scope awareness. Convert body mass to intake targets, then evaluate whether the recommendation fits training demands and professional boundaries.', '{"minutes":35,"source":"Ch. 10 · Nutrition foundations","summary":{"en":"Nutrition questions require both calculations and scope awareness. Convert body mass to intake targets, then evaluate whether the recommendation fits training demands and professional boundaries.","zh":"营养题同时考计算与职责边界。先把体重换算为摄入目标，再判断建议是否符合训练需求和专业范围。"},"points":[{"en":"Protein and carbohydrate targets are commonly expressed per kilogram of body mass; always show units.","zh":"蛋白质和碳水目标常按每公斤体重表示，计算时必须写单位。"},{"en":"Body-mass change around exercise helps estimate fluid loss; include fluid consumed and urine produced when available.","zh":"运动前后体重变化可估算液体损失；如有数据还应计入饮水和尿量。"},{"en":"Coaches may provide general education but should refer individualized medical nutrition therapy.","zh":"教练可提供一般营养教育，但个体化医学营养治疗应转介。"}],"application":{"en":"For a 75 kg athlete at 1.6 g/kg protein, multiply 75 × 1.6 = 120 g/day, then distribute across meals according to the athlete''s schedule.","zh":"75 kg 运动员按 1.6 g/kg 蛋白质计算：75 × 1.6 = 120 g/天，再结合日程分配到各餐。"},"recall":{"en":"What three unit checks should you make in a nutrition calculation?","zh":"营养计算中应检查哪三类单位？"},"answer":{"en":"Body mass unit, prescription unit such as g/kg/day, and final unit such as grams per day or liters lost.","zh":"体重单位、处方单位（如 g/kg/天）和最终单位（如克/天或损失升数）。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w4-1', 'en', 'w4-1', 'Event nutrition is a logistics problem: match carbohydrate, fluid, sodium, protein, fat, and fiber to event duration, intensity, environment, and gastrointestinal tolerance.', '{"minutes":30,"source":"Ch. 11 · Performance nutrition timing","summary":{"en":"Event nutrition is a logistics problem: match carbohydrate, fluid, sodium, protein, fat, and fiber to event duration, intensity, environment, and gastrointestinal tolerance.","zh":"比赛营养是一个后勤决策问题：让碳水、液体、钠、蛋白质、脂肪和纤维匹配比赛时长、强度、环境与胃肠耐受。"},"points":[{"en":"Pre-event intake prioritizes familiar, digestible carbohydrate and adequate hydration; reduce fat/fiber close to competition when GI risk is high.","zh":"赛前优先熟悉、易消化的碳水和充分补水；临近比赛且胃肠风险高时减少脂肪和纤维。"},{"en":"During prolonged or high-intensity events, carbohydrate and fluid strategy depends on duration, sweat rate, and tolerance.","zh":"长时间或高强度比赛中的碳水与补液策略取决于时长、出汗率和耐受。"},{"en":"Post-event recovery restores fluid, carbohydrate, and protein according to the time before the next demanding session.","zh":"赛后恢复根据下一次高负荷训练的间隔补充液体、碳水和蛋白质。"}],"application":{"en":"Test competition nutrition in training. A theoretically ideal strategy that repeatedly causes GI distress is not practically effective.","zh":"比赛营养必须在训练中演练；理论最优但反复引起胃肠不适的策略并不实用。"},"recall":{"en":"Why does the time until the next session change recovery priorities?","zh":"为什么距离下一次训练的时间会改变恢复优先级？"},"answer":{"en":"A short turnaround increases the urgency of carbohydrate, fluid, sodium, and protein replacement; a long turnaround allows normal meals to accomplish more of the recovery.","zh":"间隔短时需要更快速地补充碳水、液体、钠和蛋白质；间隔长时可更多依靠正常膳食恢复。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w4-2', 'en', 'w4-2', 'Low energy availability can impair health and performance across sexes. Recognize patterns, avoid diagnosing, and use the multidisciplinary referral pathway.', '{"minutes":30,"source":"Ch. 11 · RED-S and eating disorders","summary":{"en":"Low energy availability can impair health and performance across sexes. Recognize patterns, avoid diagnosing, and use the multidisciplinary referral pathway.","zh":"低能量可用性会损害不同性别运动员的健康与表现。应识别模式、避免自行诊断，并使用多学科转介路径。"},"points":[{"en":"Possible signs include recurrent injuries, menstrual or hormonal disruption, fatigue, performance decline, mood change, and restrictive behavior.","zh":"可能信号包括反复受伤、月经或激素异常、疲劳、表现下降、情绪变化和限制性饮食。"},{"en":"Body composition pressure and moralized food language can increase risk.","zh":"体成分压力和对食物进行道德化评价会增加风险。"},{"en":"Referral may involve sports medicine, a sports dietitian, and a qualified mental-health professional.","zh":"转介可能涉及运动医学、运动营养师和合格心理专业人员。"}],"application":{"en":"Discuss observed health/performance changes and connect the athlete to the established support team rather than prescribing a restrictive corrective diet.","zh":"讨论观察到的健康/表现变化，并连接既定支持团队，而不是自行开具限制性纠正饮食。"},"recall":{"en":"Name three observations that would strengthen concern about low energy availability.","zh":"列出三个会增强低能量可用性担忧的观察。"},"answer":{"en":"Examples include recurrent bone-stress injury, persistent fatigue/performance decline, menstrual or hormonal disruption, frequent illness, mood change, and restrictive eating.","zh":"例如反复骨应力损伤、持续疲劳/表现下降、月经或激素异常、频繁生病、情绪变化和限制性饮食。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w4-3', 'en', 'w4-3', 'Nutrition item success depends on separating evidence, marketing, calculation, safety, and scope of practice.', '{"minutes":25,"source":"Ch. 10-12 · Nutrition checkpoint","summary":{"en":"Nutrition item success depends on separating evidence, marketing, calculation, safety, and scope of practice.","zh":"营养题的关键是区分证据、营销、计算、安全性和职责边界。"},"points":[{"en":"Calculate before selecting an option; distractors often reflect unit errors.","zh":"先计算再选答案，干扰项常来自单位错误。"},{"en":"A supplement claim is not evidence; inspect study design, dose, population, and independent testing.","zh":"补剂宣传不是证据，应检查研究设计、剂量、人群和独立检测。"},{"en":"When red flags appear, referral is often the best answer.","zh":"出现危险信号时，转介通常是最佳答案。"}],"application":{"en":"Build an error sheet with five columns: rule, calculation, units, red flag, and referral destination.","zh":"建立五栏错题表：规则、计算、单位、危险信号、转介对象。"},"recall":{"en":"What makes a supplement recommendation defensible?","zh":"什么条件使补剂建议更有依据？"},"answer":{"en":"Relevant high-quality evidence, an effective and safe dose, legal/ethical review, independent contamination testing, and compatibility with the athlete''s health context and governing-body rules.","zh":"相关高质量证据、有效且安全的剂量、合法与伦理审查、独立污染检测，以及符合运动员健康背景和管理机构规则。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w5-0', 'en', 'w5-0', 'Testing should maximize validity and safety. Standardize the environment and place tests in an order that minimizes fatigue-related interference.', '{"minutes":35,"source":"Ch. 13-14 · Test order and administration","summary":{"en":"Testing should maximize validity and safety. Standardize the environment and place tests in an order that minimizes fatigue-related interference.","zh":"测试应最大化效度与安全。标准化环境，并按减少疲劳干扰的顺序安排测试。"},"points":[{"en":"Collect nonfatiguing measures first, followed by agility, maximal power/strength, sprint, local muscular endurance, anaerobic capacity, then aerobic capacity when combined in one battery.","zh":"同一测试组通常先做非疲劳指标，随后敏捷、最大功率/力量、冲刺、局部肌耐力、无氧能力，最后有氧能力。"},{"en":"Standardize warm-up, equipment, instructions, time of day when practical, and recovery intervals.","zh":"尽可能标准化热身、设备、指令、测试时间和恢复间隔。"},{"en":"Do not test an injured or medically unstable athlete outside clearance and scope.","zh":"未获许可或医学状况不稳定的运动员不得超职责进行测试。"}],"application":{"en":"If both a vertical jump and a fatigue-producing shuttle test are required, perform the jump first so fatigue does not invalidate the power measure.","zh":"若同时安排纵跳和高疲劳折返跑，应先做纵跳，避免疲劳使功率测试失真。"},"recall":{"en":"Why should an aerobic capacity test usually be last in a mixed battery?","zh":"为什么混合测试组中的有氧能力测试通常放最后？"},"answer":{"en":"It creates substantial systemic fatigue that would distort speed, agility, power, strength, and anaerobic results.","zh":"它会产生较大的全身疲劳，从而扭曲速度、敏捷、功率、力量和无氧测试结果。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w5-1', 'en', 'w5-1', 'A useful test is valid, reliable, feasible, specific, and sensitive enough to detect meaningful change.', '{"minutes":30,"source":"Ch. 13 · Measurement quality","summary":{"en":"A useful test is valid, reliable, feasible, specific, and sensitive enough to detect meaningful change.","zh":"有用的测试应具有效度、信度、可行性、专项性，并足够敏感以检测有意义变化。"},"points":[{"en":"Reliability is consistency; validity is whether the test measures the intended quality.","zh":"信度是一致性；效度是是否测到了目标能力。"},{"en":"Measurement error determines whether a score change is likely real rather than noise.","zh":"测量误差决定分数变化更可能是真实变化还是噪声。"},{"en":"A reliable test can still be invalid; consistency alone does not prove relevance.","zh":"高信度测试仍可能无效；一致并不等于相关。"}],"application":{"en":"Interpret a small improvement only after comparing it with typical error or the smallest worthwhile/meaningful change used by the program.","zh":"只有把小幅提升与典型误差或项目采用的最小有意义变化比较后，才能解释。"},"recall":{"en":"Can a test be valid if it is not sufficiently reliable?","zh":"测试若信度不足，还能有良好效度吗？"},"answer":{"en":"Poor consistency limits confidence that the score represents the intended construct, so reliability is a prerequisite for useful validity in practice.","zh":"一致性差会降低分数代表目标构念的可信度，因此在实践中信度是有效度的前提。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w5-2', 'en', 'w5-2', 'Interpretation turns raw scores into decisions. Keep units, descriptive statistics, percentile context, and measurement error visible.', '{"minutes":30,"source":"Ch. 14 · Scoring and interpretation","summary":{"en":"Interpretation turns raw scores into decisions. Keep units, descriptive statistics, percentile context, and measurement error visible.","zh":"解读是把原始分数转化为决策。必须明确单位、描述统计、百分位背景和测量误差。"},"points":[{"en":"Mean describes the arithmetic average; median is more resistant to extreme values.","zh":"均值是算术平均数；中位数更不易受极端值影响。"},{"en":"Standard deviation describes spread around the mean, not the athlete''s improvement.","zh":"标准差描述围绕均值的离散程度，不代表运动员自身进步。"},{"en":"Percentile rank is relative to the chosen reference group and does not equal percent correct.","zh":"百分位取决于参照群体，不等于答对百分比。"}],"application":{"en":"Before comparing two testing dates, confirm the same protocol, units, equipment setup, and scoring method were used.","zh":"比较两个测试日期前，应确认使用相同流程、单位、设备设置和评分方法。"},"recall":{"en":"What happens to the mean and median when one extremely high value is added to a small group?","zh":"小样本中加入一个极高值时，均值和中位数通常如何变化？"},"answer":{"en":"The mean usually rises more; the median is less affected because it depends on rank order rather than magnitude of the extreme value.","zh":"均值通常上升更多；中位数依赖排序而非极端值大小，因此受影响较小。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w5-3', 'en', 'w5-3', 'Testing questions are decision sequences: identify the quality, select a suitable test, standardize it, order it correctly, then interpret change cautiously.', '{"minutes":25,"source":"Ch. 13-14 · Testing case review","summary":{"en":"Testing questions are decision sequences: identify the quality, select a suitable test, standardize it, order it correctly, then interpret change cautiously.","zh":"测试题是决策链：识别目标能力、选择合适测试、标准化、正确排序，再谨慎解释变化。"},"points":[{"en":"Specificity includes movement, energy system, skill, population, and available equipment.","zh":"专项性包括动作、供能系统、技能、人群和可用设备。"},{"en":"Safety and technical competence override convenience.","zh":"安全和技术能力优先于便利。"},{"en":"Results should change programming or monitoring; do not test without a decision purpose.","zh":"测试结果应能改变计划或监控；没有决策目的就不应测试。"}],"application":{"en":"Write a battery for one sport and justify every test, its order, and the rest interval in one sentence each.","zh":"为一个项目编写测试组，并用一句话说明每项测试、顺序和休息时间的理由。"},"recall":{"en":"What is the first question before choosing any test?","zh":"选择任何测试前首先要问什么？"},"answer":{"en":"What performance quality or program decision must this test measure or inform?","zh":"这项测试必须测量哪种表现能力，或支持哪项计划决策？"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w6-0', 'en', 'w6-0', 'Preparation should raise readiness without creating fatigue. Use general heat, movement rehearsal, dynamic range, and progressive task-specific intensity.', '{"minutes":30,"source":"Ch. 15 · Warm-up, mobility, and flexibility","summary":{"en":"Preparation should raise readiness without creating fatigue. Use general heat, movement rehearsal, dynamic range, and progressive task-specific intensity.","zh":"准备活动应提高准备度而不制造疲劳。使用一般升温、动作预演、动态活动范围和逐步增加的专项强度。"},"points":[{"en":"Dynamic warm-up is generally suited to pre-performance preparation because it rehearses movement and temperature/activation demands.","zh":"动态热身通常适合赛前准备，因为它同时完成动作预演、升温和激活。"},{"en":"Static stretching can improve range of motion; long intense bouts immediately before maximal force/power may transiently reduce performance.","zh":"静态拉伸可改善活动范围；最大力量/功率前立即进行长时间高强度静态拉伸可能短暂降低表现。"},{"en":"PNF methods combine stretching and contraction and require appropriate partner control and contraindication awareness.","zh":"PNF 结合拉伸与收缩，需要合适的伙伴控制和禁忌意识。"}],"application":{"en":"Build a RAMP-style sequence: raise, activate/mobilize, then potentiate with movements that increasingly resemble the session''s first priority task.","zh":"构建 RAMP 顺序：升温、激活/活动，再用逐渐接近首要训练任务的动作进行增强。"},"recall":{"en":"Why should the last warm-up phase resemble the main task?","zh":"为什么热身最后阶段应接近主要任务？"},"answer":{"en":"It rehearses the specific coordination, velocity, force, and attentional demands while confirming readiness.","zh":"它预演专项协调、速度、力量和注意需求，同时确认准备状态。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w6-1', 'en', 'w6-1', 'Technique is a repeatable solution that controls the load while matching the exercise goal. Evaluate setup, bracing, path, joint positions, tempo, and finish.', '{"minutes":40,"source":"Ch. 16 · Free-weight technique","summary":{"en":"Technique is a repeatable solution that controls the load while matching the exercise goal. Evaluate setup, bracing, path, joint positions, tempo, and finish.","zh":"技术是控制负荷并匹配动作目标的可重复方案。应检查起始、核心稳定、运动轨迹、关节位置、节奏和结束。"},"points":[{"en":"Squat: stable foot pressure, braced trunk, knees tracking with the feet, controlled depth, and balanced ascent.","zh":"深蹲：足底压力稳定、躯干固定、膝盖与脚方向一致、深度受控、起身平衡。"},{"en":"Bench press: secure five-point contact, controlled touch point, stable shoulder position, and appropriate spotter communication.","zh":"卧推：稳定五点接触、受控触胸点、肩部稳定，并与保护者明确沟通。"},{"en":"Deadlift: load over the midfoot, tension before lift-off, coordinated knee/hip extension, neutral controlled trunk, and no backward overextension at lockout.","zh":"硬拉：负荷位于足中、离地前建立张力、髋膝协同伸展、躯干中立受控，锁定时不过度后仰。"}],"application":{"en":"Use one correction at a time, reduce load or complexity if the athlete cannot maintain the target position, then retest the cue.","zh":"每次只给一个纠错提示；若无法保持目标位置，降低负荷或复杂度，再检验提示效果。"},"recall":{"en":"Describe the setup and three checkpoints for one squat, bench press, and deadlift repetition.","zh":"分别口述一次深蹲、卧推和硬拉的起始设置与三个检查点。"},"answer":{"en":"A complete answer covers base of support/grip, bracing and starting alignment, controlled bar path with joint tracking, and a balanced finish appropriate to the lift.","zh":"完整答案应覆盖支撑面/握距、核心稳定与起始排列、受控杠铃轨迹与关节跟踪，以及符合动作要求的平衡结束。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w6-2', 'en', 'w6-2', 'Spotting reduces foreseeable risk but cannot rescue poor exercise selection, excessive loading, or an unsafe environment.', '{"minutes":25,"source":"Ch. 16 · Spotting and safety","summary":{"en":"Spotting reduces foreseeable risk but cannot rescue poor exercise selection, excessive loading, or an unsafe environment.","zh":"保护可降低可预见风险，但不能弥补错误动作选择、过大负荷或不安全环境。"},"points":[{"en":"Agree on lift-off, repetition target, and help signal before the set.","zh":"组前确认起杠、目标次数和求助信号。"},{"en":"Spotters position to control the implement''s likely failure path without obstructing normal technique.","zh":"保护者应能控制器械最可能的失误路径，同时不干扰正常动作。"},{"en":"Use collars, safeties, racks, and enough spotters appropriate to the exercise and load.","zh":"根据动作和负荷使用卡箍、安全杆、深蹲架及足够数量的保护者。"}],"application":{"en":"If the athlete loses position repeatedly, end the set and adjust load or exercise; repeated emergency assistance is not a programming strategy.","zh":"若运动员反复失去姿势，应结束该组并调整负荷或动作；反复紧急救援不是训练策略。"},"recall":{"en":"What should be agreed before a heavy bench press begins?","zh":"大重量卧推开始前应确认什么？"},"answer":{"en":"Lift-off plan, expected repetitions, command/help signal, hand placement, and how the bar will be returned safely.","zh":"起杠方案、预计次数、指令/求助信号、手部位置，以及安全回架方式。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w6-3', 'en', 'w6-3', 'Effective feedback identifies the highest-priority error, gives a short actionable cue, and checks whether performance changes.', '{"minutes":30,"source":"Ch. 16-17 · Coaching and correction","summary":{"en":"Effective feedback identifies the highest-priority error, gives a short actionable cue, and checks whether performance changes.","zh":"有效反馈先识别最高优先级错误，给出简短可执行提示，并检查动作是否改变。"},"points":[{"en":"Prioritize safety-critical errors before performance refinements.","zh":"先纠正安全关键错误，再优化表现细节。"},{"en":"External-focus cues often improve automatic movement control; internal cues remain useful when a specific body action must be clarified.","zh":"外部注意提示常有助于自动控制；需要明确特定身体动作时，内部提示仍有价值。"},{"en":"Avoid cue overload: one athlete cannot act on five corrections at once.","zh":"避免提示过载：运动员无法同时执行五个纠正。"}],"application":{"en":"Use the loop observe → identify cause → cue or regress → repeat → verify. Record whether the cue worked, not just what you said.","zh":"使用“观察→判断原因→提示或降阶→重复→验证”的循环；记录提示是否有效，而不只是说了什么。"},"recall":{"en":"Turn “your knees are wrong” into a specific actionable cue.","zh":"把“你的膝盖不对”改成具体可执行提示。"},"answer":{"en":"For an appropriate case, use a directional cue such as “drive the knees in line with the second toe” and then observe the next repetition.","zh":"在合适情境中，可提示“膝盖沿第二脚趾方向推出”，并观察下一次重复。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w7-0', 'en', 'w7-0', 'Program design begins with a needs analysis of the sport and the athlete. Training variables come later.', '{"minutes":35,"source":"Ch. 18 · Needs analysis","summary":{"en":"Program design begins with a needs analysis of the sport and the athlete. Training variables come later.","zh":"计划设计始于项目需求分析与运动员分析，具体训练变量在其后。"},"points":[{"en":"Sport analysis covers movement patterns, physiological demands, injury patterns, and performance calendar.","zh":"项目分析包括动作模式、生理需求、常见损伤和竞赛日历。"},{"en":"Athlete analysis covers training status, testing results, injury/medical context, technical skill, and constraints.","zh":"运动员分析包括训练水平、测试结果、伤病/医疗背景、技术能力和现实限制。"},{"en":"Gap analysis compares sport demand with athlete capacity and ranks priorities.","zh":"差距分析比较项目需求与运动员能力，并排序优先级。"}],"application":{"en":"A program for a rotational power athlete should not be copied from an endurance athlete even if both want to become ''fitter.'' Define the performance gap precisely.","zh":"即使两人都想“更强健”，旋转爆发项目和耐力项目也不能照搬同一计划；必须准确界定表现差距。"},"recall":{"en":"What four categories belong in the sport portion of a needs analysis?","zh":"需求分析中的项目分析应包含哪四类？"},"answer":{"en":"Movement/biomechanical patterns, physiological/energy-system demands, common injury risks, and the calendar or season structure.","zh":"动作/生物力学模式、生理/供能需求、常见损伤风险，以及赛历或赛季结构。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w7-1', 'en', 'w7-1', 'Sets, repetitions, load, rest, frequency, and exercise order must express the goal as one coherent dose.', '{"minutes":40,"source":"Ch. 18 · Load, repetitions, volume, and rest","summary":{"en":"Sets, repetitions, load, rest, frequency, and exercise order must express the goal as one coherent dose.","zh":"组数、次数、负荷、休息、频率和动作顺序必须共同表达一个一致的训练剂量。"},"points":[{"en":"Strength and power emphasize high force/intent, lower repetitions, and longer recovery; power also requires velocity and quality.","zh":"力量与功率强调高力量/意图、较低次数和较长恢复；功率还要求速度与质量。"},{"en":"Hypertrophy requires sufficient challenging volume across a practical range of loads, with recovery that supports total work.","zh":"肌肥大需要足够的高挑战训练量，可使用较广负荷范围，并以支持总做功的恢复为准。"},{"en":"Muscular endurance uses higher repetitions and shorter rest relative to maximal strength work.","zh":"肌耐力相对最大力量训练使用更高次数和更短休息。"}],"application":{"en":"Do not select a repetition range in isolation. Verify that load, rest, order, weekly frequency, and total volume preserve the intended adaptation.","zh":"不要孤立选择次数范围；应确认负荷、休息、顺序、周频率和总量共同支持目标适应。"},"recall":{"en":"Why can a five-repetition set fail to train maximal strength effectively?","zh":"为什么五次一组也可能无法有效训练最大力量？"},"answer":{"en":"If the load is too light, intent is low, rest is inadequate, technique limits force, or fatigue dominates, the dose does not match the intended strength stimulus.","zh":"若负荷过轻、意图不足、休息不够、技术限制力量或疲劳占主导，该剂量就不匹配力量刺激。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w7-2', 'en', 'w7-2', 'Progression should be earned by performance quality. The 2-for-2 rule is one practical trigger, not a universal law.', '{"minutes":20,"source":"Ch. 18 · Progression","summary":{"en":"Progression should be earned by performance quality. The 2-for-2 rule is one practical trigger, not a universal law.","zh":"进阶应由表现质量获得。2-for-2 法则是实用触发条件之一，不是普遍定律。"},"points":[{"en":"If the athlete exceeds the target by two repetitions in the final set for two consecutive sessions, a modest load increase may be appropriate.","zh":"若运动员连续两次训练在最后一组都超过目标两次，可考虑小幅加重。"},{"en":"Progress only one or a few variables at a time so the response remains interpretable.","zh":"每次只进阶一个或少数变量，才能解释训练反应。"},{"en":"Technique, pain, recovery, and the program phase can override a numerical progression trigger.","zh":"技术、疼痛、恢复和计划阶段可优先于数字进阶触发。"}],"application":{"en":"After meeting the trigger, use a conservative load increase appropriate to the exercise and athlete, then confirm repetitions and technique remain inside the target.","zh":"满足触发条件后，根据动作和个体采用保守加重，并确认次数与技术仍处于目标范围。"},"recall":{"en":"State the 2-for-2 rule and one reason not to apply it automatically.","zh":"说出 2-for-2 法则，并给出一个不应自动执行的原因。"},"answer":{"en":"Exceed the repetition target by two in the last set on two consecutive sessions; do not auto-progress when technique, pain, recovery, equipment increments, or the phase makes loading inappropriate.","zh":"连续两次训练最后一组超过目标两次；若技术、疼痛、恢复、器械加重幅度或周期阶段不合适，则不应自动加重。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w7-3', 'en', 'w7-3', 'A microcycle distributes stress so priority qualities receive high-quality work and the athlete can recover between similar demands.', '{"minutes":40,"source":"Ch. 18 · Microcycle design","summary":{"en":"A microcycle distributes stress so priority qualities receive high-quality work and the athlete can recover between similar demands.","zh":"微周期分配训练压力，使优先能力获得高质量刺激，并让相似需求之间有恢复时间。"},"points":[{"en":"Place the highest-priority or most speed-sensitive work when the athlete is freshest.","zh":"把最高优先级或最依赖速度的训练放在运动员最清醒时。"},{"en":"Account for sport practice, competition, travel, and other conditioning—not only lifting sessions.","zh":"必须计入专项训练、比赛、旅行和其他体能训练，而不能只看力量房。"},{"en":"Hard/easy organization can preserve weekly volume while reducing repeated high stress.","zh":"高低负荷交替可在保留周训练量的同时减少连续高压力。"}],"application":{"en":"Build the week from immovable competition/practice demands backward, then place priority strength/power exposures and recovery.","zh":"先固定比赛和专项训练，再反向安排优先力量/功率刺激与恢复。"},"recall":{"en":"Why is a perfect gym plan sometimes a poor total program?","zh":"为什么完美的力量房计划有时仍是糟糕的整体计划？"},"answer":{"en":"It may ignore sport practice, games, travel, rehabilitation, and total recovery demand, causing conflicting or excessive stress.","zh":"它可能忽略专项训练、比赛、旅行、康复和总体恢复需求，造成冲突或过量压力。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w8-0', 'en', 'w8-0', 'Plyometrics train rapid force through the stretch-shortening cycle. Progress landing control, force, speed, direction, and complexity before chasing box height.', '{"minutes":35,"source":"Ch. 19 · Plyometric progression","summary":{"en":"Plyometrics train rapid force through the stretch-shortening cycle. Progress landing control, force, speed, direction, and complexity before chasing box height.","zh":"增强式训练通过拉伸-缩短循环发展快速力量。应先推进落地控制、力量、速度、方向和复杂度，而不是只追求箱高。"},"points":[{"en":"The stretch-shortening cycle includes eccentric loading, amortization, and concentric action; a brief controlled transition preserves elastic and reflex contribution.","zh":"拉伸-缩短循环包括离心加载、转换期和向心动作；短而受控的转换有助于保留弹性与反射贡献。"},{"en":"Landing quality requires stable trunk, aligned lower extremity, appropriate joint flexion, and controlled force absorption.","zh":"高质量落地需要躯干稳定、下肢对齐、适当关节屈曲和受控吸收力量。"},{"en":"Intensity rises with speed, height, unilateral demand, external load, and multidirectional complexity.","zh":"速度、高度、单侧要求、外部负荷和多方向复杂度都会提高强度。"}],"application":{"en":"Regress a depth jump to landing drills or lower-intensity jumps when the athlete cannot maintain alignment or minimize excessive ground-contact strategy.","zh":"若运动员无法保持对齐或合适触地策略，应把跳深降阶为落地练习或更低强度跳跃。"},"recall":{"en":"What should be mastered before high-intensity depth jumps?","zh":"进行高强度跳深前应掌握什么？"},"answer":{"en":"Consistent landing mechanics, adequate strength and training readiness, control at lower intensities, and the ability to follow coaching instructions.","zh":"稳定落地技术、足够力量与训练准备度、低强度下的控制能力，以及遵循教练指令的能力。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w8-1', 'en', 'w8-1', 'Speed is phase-specific. Acceleration, maximal velocity, deceleration, and change of direction require different positions, force directions, and technical priorities.', '{"minutes":35,"source":"Ch. 20 · Speed and agility mechanics","summary":{"en":"Speed is phase-specific. Acceleration, maximal velocity, deceleration, and change of direction require different positions, force directions, and technical priorities.","zh":"速度具有阶段专项性。加速、最大速度、减速和变向需要不同身体姿势、力量方向和技术重点。"},"points":[{"en":"Acceleration emphasizes horizontal projection, positive shin angles, and forceful steps that gradually rise.","zh":"加速强调水平投射、正向胫骨角和有力步伐，并逐渐抬高身体。"},{"en":"Maximal velocity emphasizes upright posture, front-side mechanics, stiffness at contact, and minimal braking.","zh":"最大速度强调直立姿势、前侧摆动、触地刚度和最小制动。"},{"en":"Deceleration requires earlier braking, lowering the center of mass, and distributing force before changing direction.","zh":"减速需要提前制动、降低重心，并在变向前分配力量。"}],"application":{"en":"If an athlete enters a cut too fast to control posture, train approach-speed control and deceleration capacity before adding reactive complexity.","zh":"若运动员进入变向速度过快而失去姿势，应先训练接近速度控制和减速能力，再加入反应复杂度。"},"recall":{"en":"How do acceleration and maximal-velocity posture differ?","zh":"加速与最大速度阶段的姿势有何不同？"},"answer":{"en":"Acceleration uses a forward projection with progressive rise; maximal velocity is more upright with rapid vertical force and limited braking at ground contact.","zh":"加速使用前倾投射并逐渐抬高；最大速度更直立，触地快速产生垂直力并减少制动。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w8-2', 'en', 'w8-2', 'A power or speed session is governed by quality. Sequence high-skill and high-velocity work early, limit contacts/repetitions, and use enough recovery.', '{"minutes":35,"source":"Ch. 19-20 · Session design","summary":{"en":"A power or speed session is governed by quality. Sequence high-skill and high-velocity work early, limit contacts/repetitions, and use enough recovery.","zh":"功率或速度课由质量主导。高技能、高速度内容应靠前，控制触地/重复次数，并给予充分恢复。"},"points":[{"en":"Warm up from general movement to specific jumps, sprints, or cuts.","zh":"热身从一般动作逐步过渡到专项跳跃、冲刺或变向。"},{"en":"Choose drills that match the athlete''s current deficit and sport demand.","zh":"选择匹配运动员当前缺陷和项目需求的练习。"},{"en":"Stop or regress when times, distances, contact quality, or technique deteriorate beyond the session target.","zh":"当成绩、距离、触地质量或技术下降超过目标时，应停止或降阶。"}],"application":{"en":"Design one session with a clear primary quality, 2-4 related drills, exact repetitions/contacts, rest, and a stop rule.","zh":"设计一节课：明确主要能力，安排 2-4 个相关练习，写清次数/触地数、休息和停止规则。"},"recall":{"en":"Why are short rests often a poor choice for maximal speed practice?","zh":"为什么短休息通常不适合最大速度训练？"},"answer":{"en":"Fatigue reduces velocity and changes mechanics, turning a speed session into conditioning and weakening the intended stimulus.","zh":"疲劳会降低速度并改变技术，使速度训练变成体能消耗，削弱目标刺激。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w8-3', 'en', 'w8-3', 'Applied questions present an athlete, goal, movement error, and constraint. Choose the safest option that most specifically solves the stated problem.', '{"minutes":25,"source":"Ch. 15-20 · Applied checkpoint","summary":{"en":"Applied questions present an athlete, goal, movement error, and constraint. Choose the safest option that most specifically solves the stated problem.","zh":"实践题通常给出运动员、目标、动作错误和限制条件。应选择最安全且最专项地解决题目问题的选项。"},"points":[{"en":"Identify the primary quality before selecting an exercise.","zh":"选动作前先识别主要能力。"},{"en":"Match exercise complexity to demonstrated competence.","zh":"让动作复杂度匹配已展示的能力。"},{"en":"Protect quality with appropriate ordering and recovery.","zh":"用正确顺序和恢复保护训练质量。"}],"application":{"en":"For every item, state why the winning option is better than the two distractors in this athlete''s context.","zh":"每道题都说明为什么最佳选项在该运动员情境下优于另外两个干扰项。"},"recall":{"en":"What three filters should be applied to every applied-training answer?","zh":"每个实践训练答案都应通过哪三层筛选？"},"answer":{"en":"Safety/readiness, specificity to the stated goal, and compatibility with the program''s dose and sequence.","zh":"安全/准备度、对目标的专项性，以及与计划剂量和顺序的兼容性。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w9-0', 'en', 'w9-0', 'Aerobic prescription combines mode, frequency, duration, and intensity. Heart-rate reserve is one tool, not a substitute for athlete context.', '{"minutes":30,"source":"Ch. 21 · Aerobic prescription","summary":{"en":"Aerobic prescription combines mode, frequency, duration, and intensity. Heart-rate reserve is one tool, not a substitute for athlete context.","zh":"有氧处方结合方式、频率、时长和强度。心率储备法是一种工具，不能替代运动员情境。"},"points":[{"en":"Heart-rate reserve = HRmax − HRrest.","zh":"心率储备 = 最大心率 − 静息心率。"},{"en":"Target HR = HRrest + intensity fraction × HR reserve.","zh":"目标心率 = 静息心率 + 强度比例 × 心率储备。"},{"en":"Use workload, pace, power, RPE, talk test, and sport-specific markers when heart rate is distorted or insufficient.","zh":"当心率受干扰或信息不足时，可使用工作负荷、配速、功率、RPE、谈话测试和专项指标。"}],"application":{"en":"For HRmax 200, HRrest 60, and 70% HRR: 60 + .70 × (200 − 60) = 158 beats/min.","zh":"最大心率 200、静息心率 60、70% HRR：60 + 0.70 × (200 − 60) = 158 次/分。"},"recall":{"en":"Calculate 65% HRR for HRmax 190 and HRrest 50.","zh":"计算最大心率 190、静息心率 50 时的 65% HRR 目标心率。"},"answer":{"en":"HRR = 140; target = 50 + .65 × 140 = 141 beats/min.","zh":"HRR = 140；目标 = 50 + 0.65 × 140 = 141 次/分。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w9-1', 'en', 'w9-1', 'Periodization organizes variation and progression toward performance dates. Models are tools; the athlete''s calendar and response determine the choice.', '{"minutes":35,"source":"Ch. 22 · Periodization models","summary":{"en":"Periodization organizes variation and progression toward performance dates. Models are tools; the athlete''s calendar and response determine the choice.","zh":"周期化把变化与进阶组织到目标比赛。模型只是工具，选择应由赛历和运动员反应决定。"},"points":[{"en":"Traditional/linear plans often move from higher volume/lower intensity toward lower volume/higher intensity across phases.","zh":"传统/线性计划常从高容量低强度逐步转向低容量高强度。"},{"en":"Undulating plans vary volume and intensity more frequently within a week or short block.","zh":"波动计划在一周或短区块内更频繁改变容量与强度。"},{"en":"Preparatory, competitive, and transition periods change priorities, not merely exercise names.","zh":"准备期、竞赛期和过渡期改变的是优先级，而不只是动作名称。"}],"application":{"en":"Choose the model that fits competition density, athlete experience, available preparation time, and ability to recover—not the model with the most complexity.","zh":"选择适合比赛密度、训练经验、准备时间和恢复能力的模型，而不是最复杂的模型。"},"recall":{"en":"What is the practical difference between linear and undulating organization?","zh":"线性与波动组织在实践中的主要区别是什么？"},"answer":{"en":"Linear organization changes volume/intensity primarily across longer phases; undulating organization varies them more frequently within shorter intervals.","zh":"线性组织主要在较长阶段间改变容量/强度；波动组织在更短时间内更频繁变化。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w9-2', 'en', 'w9-2', 'An annual plan works backward from key competitions and coordinates macrocycles, mesocycles, and microcycles with sport practice and recovery.', '{"minutes":40,"source":"Ch. 22 · Annual planning","summary":{"en":"An annual plan works backward from key competitions and coordinates macrocycles, mesocycles, and microcycles with sport practice and recovery.","zh":"年度计划从关键比赛倒推，并协调大周期、中周期、微周期与专项训练和恢复。"},"points":[{"en":"Identify priority competitions and congested periods first.","zh":"先标出优先比赛和密集赛程。"},{"en":"Assign each phase a dominant objective while maintaining critical qualities.","zh":"每个阶段设定主导目标，同时维持关键能力。"},{"en":"Plan deloads, travel, transition, and re-entry instead of treating recovery as leftover time.","zh":"预先安排减量、旅行、过渡和重新进入训练，而不是把恢复当剩余时间。"}],"application":{"en":"Create a 12-month line with competitions, preparation blocks, monitoring points, and planned recovery. Then zoom one month into weekly doses.","zh":"画出 12 个月时间线，标注比赛、准备区块、监控点和计划恢复，再把一个月展开为周剂量。"},"recall":{"en":"Why should an annual plan be revised rather than followed rigidly?","zh":"为什么年度计划应持续修订而不能僵化执行？"},"answer":{"en":"Competition schedules, injuries, adaptation rates, readiness, and performance data change; the plan is a decision framework, not a prediction that must be obeyed.","zh":"赛程、伤病、适应速度、准备度和表现数据都会变化；计划是决策框架，不是必须服从的预测。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w9-3', 'en', 'w9-3', 'Program-design items test coherence. Every variable should point toward the same athlete need, phase, and performance date.', '{"minutes":25,"source":"Ch. 18, 21-22 · Program design checkpoint","summary":{"en":"Program-design items test coherence. Every variable should point toward the same athlete need, phase, and performance date.","zh":"计划设计题考的是一致性。每个变量都应指向同一运动员需求、阶段和表现日期。"},"points":[{"en":"Start with needs and calendar, not favorite exercises.","zh":"从需求和赛历开始，而不是个人偏爱的动作。"},{"en":"Check whether frequency, volume, intensity, order, and recovery can coexist.","zh":"检查频率、容量、强度、顺序和恢复能否共存。"},{"en":"Use monitoring to decide whether progression is appropriate.","zh":"使用监控数据决定是否进阶。"}],"application":{"en":"Take one sample week and explain the purpose of every session, its stress, and how it interacts with adjacent sessions.","zh":"选择一个示例周，说明每节课的目的、压力，以及与相邻训练的相互作用。"},"recall":{"en":"What is the fastest way to spot an incoherent program answer?","zh":"怎样最快识别不一致的计划答案？"},"answer":{"en":"Find the stated primary goal, then check whether the exercise choice, velocity/load, repetitions, rest, and weekly placement actually support that goal.","zh":"先找出首要目标，再检查动作、速度/负荷、次数、休息和周安排是否真正支持它。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w10-0', 'en', 'w10-0', 'Performance decrement exists on a continuum from planned functional overreaching to nonfunctional overreaching and overtraining syndrome. Time course and recovery response matter.', '{"minutes":35,"source":"Ch. 23-24 · Reconditioning and recovery","summary":{"en":"Performance decrement exists on a continuum from planned functional overreaching to nonfunctional overreaching and overtraining syndrome. Time course and recovery response matter.","zh":"表现下降从计划性的功能性过度刺激，到非功能性过度刺激和过度训练综合征构成连续谱；时间进程与恢复反应非常关键。"},"points":[{"en":"Functional overreaching produces a short decline followed by recovery and possible supercompensation.","zh":"功能性过度刺激造成短期下降，恢复后可能超量反弹。"},{"en":"Nonfunctional overreaching produces a longer decline without the intended performance benefit.","zh":"非功能性过度刺激造成更长时间下降，且没有预期表现收益。"},{"en":"Overtraining syndrome is prolonged, multifactorial, and requires medical evaluation; no single marker diagnoses it.","zh":"过度训练综合征持续时间长、因素复杂，需要医学评估；没有单一指标可诊断。"}],"application":{"en":"Respond to unexplained decline by reviewing total load, sleep, nutrition, illness, psychological stress, and recovery—not by automatically adding hard work.","zh":"面对无法解释的表现下降，应审查总负荷、睡眠、营养、疾病、心理压力和恢复，而不是自动加量。"},"recall":{"en":"What separates functional from nonfunctional overreaching most clearly?","zh":"区分功能性与非功能性过度刺激最清晰的依据是什么？"},"answer":{"en":"The duration of performance suppression and whether adequate recovery produces the intended rebound/adaptation.","zh":"表现受抑制持续时间，以及充分恢复后是否出现预期反弹/适应。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w10-1', 'en', 'w10-1', 'Rehabilitation and reconditioning are collaborative. The strength coach operates within medical restrictions and communicates objective training responses to the team.', '{"minutes":30,"source":"Ch. 23 · Return-to-sport roles","summary":{"en":"Rehabilitation and reconditioning are collaborative. The strength coach operates within medical restrictions and communicates objective training responses to the team.","zh":"康复与重建需要协作。体能教练在医疗限制内工作，并向团队沟通客观训练反应。"},"points":[{"en":"Diagnosis, treatment, and medical clearance belong to qualified health professionals.","zh":"诊断、治疗和医学许可属于合格医疗专业人员。"},{"en":"The strength coach progresses physical qualities and sport demands within the approved plan.","zh":"体能教练在批准的方案内推进体能和专项需求。"},{"en":"Return to participation, return to sport, and return to performance are related but distinct milestones.","zh":"恢复参与、重返运动和恢复表现是相关但不同的里程碑。"}],"application":{"en":"Document load, symptoms reported, technique, performance, and communication; stop and refer when signs exceed the approved response.","zh":"记录负荷、主诉症状、技术、表现与沟通；若迹象超出批准范围，应停止并转介。"},"recall":{"en":"Who makes medical clearance decisions, and what is the strength coach''s role afterward?","zh":"谁负责医学许可，许可后体能教练的角色是什么？"},"answer":{"en":"A qualified medical professional provides clearance/restrictions; the strength coach designs and monitors progressive reconditioning within them and communicates response.","zh":"合格医疗专业人员提供许可/限制；体能教练在其范围内设计并监控渐进重建，并沟通反应。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w10-2', 'en', 'w10-2', 'Facility management is preventive risk control: design traffic flow, spacing, supervision, inspection, documentation, and emergency response before an incident occurs.', '{"minutes":35,"source":"Ch. 25-26 · Facility and emergency action","summary":{"en":"Facility management is preventive risk control: design traffic flow, spacing, supervision, inspection, documentation, and emergency response before an incident occurs.","zh":"设施管理是预防性风险控制：在事故前设计动线、间距、监督、检查、记录和应急响应。"},"points":[{"en":"Equipment placement should preserve clear traffic paths, adequate activity space, visibility, and access to exits/emergency equipment.","zh":"器械布置应保留清晰动线、足够活动空间、监督视野，以及出口和应急设备通道。"},{"en":"Inspection and maintenance require schedules, documented findings, removal of unsafe equipment, and verified repair.","zh":"检查维护需要时间表、问题记录、不安全设备停用和维修确认。"},{"en":"An emergency action plan assigns roles, communication, equipment, access routes, and rehearsal.","zh":"应急行动计划明确角色、沟通、设备、进入路线和演练。"}],"application":{"en":"Rehearse the EAP with likely scenarios. A document that staff cannot execute quickly is not an effective plan.","zh":"用可能场景演练 EAP。员工无法快速执行的文件不是有效计划。"},"recall":{"en":"Name five elements that should be explicit in an emergency action plan.","zh":"说出应急行动计划中应明确的五个要素。"},"answer":{"en":"Emergency personnel/roles, communication method, available equipment such as AED, venue directions and EMS access, and documented response/rehearsal procedures.","zh":"应急人员/角色、沟通方式、AED 等设备、场馆定位与 EMS 进入路线，以及记录和演练流程。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w10-3', 'en', 'w10-3', 'Administration answers are guided by duty of care, written policy, qualified supervision, documentation, and consistent enforcement.', '{"minutes":25,"source":"Ch. 25-26 · Administration checkpoint","summary":{"en":"Administration answers are guided by duty of care, written policy, qualified supervision, documentation, and consistent enforcement.","zh":"管理题由照护义务、书面政策、合格监督、记录和一致执行所指导。"},"points":[{"en":"Foreseeable hazards should be identified and controlled before use.","zh":"可预见危险应在使用前识别并控制。"},{"en":"Policies must be communicated, trained, documented, and applied consistently.","zh":"政策必须被沟通、培训、记录并一致执行。"},{"en":"Incident response includes immediate care plus factual documentation and follow-up.","zh":"事故响应包括即时处理，以及事实性记录与后续跟进。"}],"application":{"en":"For each facility scenario, identify the foreseeable risk, preventive control, responsible role, and documentation required.","zh":"对每个设施情景，识别可预见风险、预防控制、责任角色和所需记录。"},"recall":{"en":"Why is an unwritten safety habit weaker than a formal policy?","zh":"为什么没有书面化的安全习惯弱于正式政策？"},"answer":{"en":"It is harder to train, apply consistently, audit, update, and document as evidence of reasonable professional practice.","zh":"它更难被培训、一致执行、审计、更新，也难作为合理专业实践的证据。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w11-0', 'en', 'w11-0', 'A simulation is useful only when conditions and review are standardized. Reproduce pacing, no-reference answering, and confidence marking.', '{"minutes":90,"source":"Scientific Foundations · Timed simulation","summary":{"en":"A simulation is useful only when conditions and review are standardized. Reproduce pacing, no-reference answering, and confidence marking.","zh":"只有条件和复盘标准化，模拟才有价值。应复现节奏、闭卷作答和信心标记。"},"points":[{"en":"Use the official section time as the long-form reference, but scale time proportionally for shorter sets.","zh":"以官方部分时长为完整参考，短题组按比例缩放时间。"},{"en":"Flag uncertain items and move on; do not sacrifice several questions to one stem.","zh":"标记不确定题并继续，不要为一道题牺牲多道题时间。"},{"en":"After scoring, analyze domain, cognition level, confidence, and error type.","zh":"评分后分析领域、认知层级、信心和错误类型。"}],"application":{"en":"For an 80-scored-item/90-minute reference, a 40-item practice block should target roughly 45 minutes before review.","zh":"以 80 道计分题/90 分钟为参考，40 题练习在复盘前目标约 45 分钟。"},"recall":{"en":"What four data points should be recorded for every miss?","zh":"每道错题应记录哪四类数据？"},"answer":{"en":"Domain/topic, why the selected option seemed attractive, the governing rule, and whether the error was knowledge, application, reading, or calculation.","zh":"领域/主题、错误选项为何有吸引力、支配规则，以及错误属于知识、应用、审题还是计算。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w11-1', 'en', 'w11-1', 'The applied section rewards rapid pattern recognition from athlete context, images/video, safety constraints, and program variables.', '{"minutes":150,"source":"Practical / Applied · Timed simulation","summary":{"en":"The applied section rewards rapid pattern recognition from athlete context, images/video, safety constraints, and program variables.","zh":"实践应用部分考查从运动员情境、图像/视频、安全限制和计划变量中快速识别模式。"},"points":[{"en":"Read the athlete goal and constraint before interpreting the answer choices.","zh":"先读运动员目标和限制，再看选项。"},{"en":"For technique items, identify the highest-risk or performance-limiting error first.","zh":"动作题先识别风险最高或最限制表现的错误。"},{"en":"For program items, test coherence across exercise, load, volume, order, rest, and schedule.","zh":"计划题检查动作、负荷、容量、顺序、休息和日程的一致性。"}],"application":{"en":"Use proportional timing for shorter sets and reserve a final review window for flagged items, especially calculations and image-based decisions.","zh":"短题组按比例计时，并为标记题保留最后复查时间，特别是计算和图像决策题。"},"recall":{"en":"What should you extract from an applied stem before choosing?","zh":"实践题选择前应从题干提取什么？"},"answer":{"en":"Athlete/training status, stated goal, current phase, key constraint or error, and the decision the question actually asks for.","zh":"运动员/训练状态、明确目标、当前阶段、关键限制或错误，以及题目真正要求的决策。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w11-2', 'en', 'w11-2', 'Overall score is a lagging summary. Domain accuracy, error type, confidence calibration, and response time tell you what to study next.', '{"minutes":30,"source":"Score analysis · Domain weighting","summary":{"en":"Overall score is a lagging summary. Domain accuracy, error type, confidence calibration, and response time tell you what to study next.","zh":"总分只是滞后汇总。领域正确率、错误类型、信心校准和作答时间才能告诉你下一步学什么。"},"points":[{"en":"Prioritize large deficits in high-weight domains.","zh":"优先处理高权重领域中的大缺口。"},{"en":"High-confidence errors reveal misconceptions and deserve immediate correction.","zh":"高信心错误代表错误概念，应立即纠正。"},{"en":"Slow correct answers may still need fluency practice before exam day.","zh":"答对但过慢的题在考前仍需流畅度训练。"}],"application":{"en":"Create a matrix with domain weight on one axis and accuracy/confidence on the other; select the next three study blocks from the highest-impact cells.","zh":"建立矩阵：一轴是领域权重，一轴是正确率/信心；从影响最大的单元选择接下来三个学习块。"},"recall":{"en":"Which is usually more urgent: a low-confidence miss or a high-confidence miss?","zh":"低信心错题与高信心错题，通常哪个更紧急？"},"answer":{"en":"A high-confidence miss often signals a stable misconception, whereas low confidence already indicates uncertainty; both matter, but the misconception needs fast correction.","zh":"高信心错题通常意味着稳定的错误概念；低信心本身已表明不确定。两者都重要，但错误概念应更快纠正。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w11-3', 'en', 'w11-3', 'Review is complete only when the learner can retrieve the rule and apply it to a changed example without seeing the original answer.', '{"minutes":35,"source":"Error correction · Retrieval loop","summary":{"en":"Review is complete only when the learner can retrieve the rule and apply it to a changed example without seeing the original answer.","zh":"只有学习者在看不到原答案时，能提取规则并应用到变化情景，复盘才算完成。"},"points":[{"en":"Write the rule in one sentence without copying the explanation.","zh":"不复制解析，用一句话写出规则。"},{"en":"Explain why each distractor is wrong in the original context.","zh":"说明每个干扰项在原情境中为何错误。"},{"en":"Retest with a changed example after a delay.","zh":"延迟后用变化情景重新测试。"}],"application":{"en":"Schedule each corrected concept for retrieval tomorrow, in three days, and in one week; remove it only after repeated successful application.","zh":"把每个纠正概念安排在明天、三天后和一周后主动提取；重复应用成功后再移出错题队列。"},"recall":{"en":"What evidence shows that a missed concept is mastered?","zh":"什么证据表明一个错题概念已掌握？"},"answer":{"en":"Accurate unaided recall plus correct application to a novel or changed scenario on more than one occasion.","zh":"在不看资料时准确提取，并在不止一次的新情景或变化情景中正确应用。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w12-0', 'en', 'w12-0', 'The final full simulation rehearses decisions, pacing, breaks, nutrition, and attention—not just knowledge.', '{"minutes":240,"source":"Full exam rhythm · Final simulation","summary":{"en":"The final full simulation rehearses decisions, pacing, breaks, nutrition, and attention—not just knowledge.","zh":"最后一次完整模拟训练决策、节奏、休息、营养和注意，而不只是知识。"},"points":[{"en":"Use the official section structure and planned break routine as closely as practical.","zh":"尽可能按官方部分结构和计划休息流程执行。"},{"en":"Use the same flag-and-move strategy intended for exam day.","zh":"使用考试当天计划采用的标记并继续策略。"},{"en":"Review only after the entire simulation is complete.","zh":"完整模拟结束后再统一复盘。"}],"application":{"en":"Prepare the environment, permitted materials, hydration, timing, and interruption control the night before the simulation.","zh":"模拟前一晚准备环境、允许物品、补水、计时和干扰控制。"},"recall":{"en":"Besides score, what should a final simulation validate?","zh":"除分数外，最后模拟还应验证什么？"},"answer":{"en":"Pacing, concentration, break strategy, physical comfort, nutrition/hydration routine, flagging behavior, and recovery between sections.","zh":"节奏、专注、休息策略、身体舒适、营养补水流程、标记行为和部分间恢复。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w12-1', 'en', 'w12-1', 'Late-stage review should narrow. Focus on misses, unstable high-weight rules, and low-confidence correct answers rather than reopening the entire textbook.', '{"minutes":30,"source":"Targeted review · Confidence calibration","summary":{"en":"Late-stage review should narrow. Focus on misses, unstable high-weight rules, and low-confidence correct answers rather than reopening the entire textbook.","zh":"后期复习应收窄范围。聚焦错题、高权重不稳定规则和低信心答对题，而不是重新打开整本书。"},"points":[{"en":"Sort items into know, unstable, and unknown.","zh":"把知识点分为已掌握、不稳定和未知。"},{"en":"Spend most time converting unstable high-impact concepts into fast recall.","zh":"把大部分时间用于把高影响的不稳定概念转为快速提取。"},{"en":"Avoid replacing retrieval with passive rereading.","zh":"避免用被动重读替代主动提取。"}],"application":{"en":"Build a final 20-rule sheet from memory, then check it against your verified notes and correct only the gaps.","zh":"凭记忆写出最后 20 条规则，再与已核实笔记对照，只纠正缺口。"},"recall":{"en":"Why review low-confidence correct answers?","zh":"为什么要复习低信心答对题？"},"answer":{"en":"The correct choice may have been a guess; confidence calibration identifies fragile knowledge before it becomes an exam-day miss.","zh":"正确答案可能来自猜测；信心校准能在考试前识别脆弱知识。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w12-2', 'en', 'w12-2', 'The final sheet should contain decisions that must be fast: formulas, units, testing order, referral triggers, safety rules, and program-design anchors.', '{"minutes":35,"source":"Formula and red-flag sheet · Final retrieval","summary":{"en":"The final sheet should contain decisions that must be fast: formulas, units, testing order, referral triggers, safety rules, and program-design anchors.","zh":"最后清单应包含必须快速作答的内容：公式、单位、测试顺序、转介触发、安全规则和计划设计锚点。"},"points":[{"en":"Write formulas with units and one worked example.","zh":"公式必须带单位和一个例题。"},{"en":"Write red flags as action rules: observe → stop/secure safety → refer/activate policy.","zh":"把危险信号写成行动规则：观察→停止/保障安全→转介/启动政策。"},{"en":"Keep only high-yield rules you can verify from the English source or official outline.","zh":"只保留可由英文原始资料或官方大纲核实的高频规则。"}],"application":{"en":"Close the sheet and reproduce it on blank paper in under ten minutes; compare, correct, and repeat after a delay.","zh":"合上清单，十分钟内在白纸上重现；对照纠正，并延迟后再次进行。"},"recall":{"en":"Name four categories that belong on the final rapid-recall sheet.","zh":"说出最终快速提取清单应包含的四类内容。"},"answer":{"en":"Examples: calculations/units, test order and measurement rules, program-design relationships, technique/safety rules, referral red flags, and emergency/administrative duties.","zh":"例如计算/单位、测试顺序与测量规则、计划设计关系、技术/安全规则、转介危险信号和应急/管理职责。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'w12-3', 'en', 'w12-3', 'The day before the exam is for readiness, not fitness or last-minute content volume. Protect sleep, logistics, confidence, and a calm routine.', '{"minutes":20,"source":"Exam readiness · Day-before plan","summary":{"en":"The day before the exam is for readiness, not fitness or last-minute content volume. Protect sleep, logistics, confidence, and a calm routine.","zh":"考前一天的目标是准备状态，而不是提升体能或临时堆知识量。应保护睡眠、后勤、信心和稳定流程。"},"points":[{"en":"Confirm identification, route, arrival time, permitted items, and section logistics.","zh":"确认身份证明、路线、到达时间、允许物品和考试流程。"},{"en":"Use only brief retrieval of stable summaries; stop heavy testing early enough to wind down.","zh":"只进行简短的稳定知识提取，并足够早停止高负荷测试以放松。"},{"en":"Keep food, hydration, caffeine, and sleep routine familiar.","zh":"饮食、补水、咖啡因和睡眠流程保持熟悉。"}],"application":{"en":"Write an if-then plan for difficult questions: if stuck after a reasonable read, eliminate, choose/flag, and move on.","zh":"为难题写 if-then 方案：若合理阅读后仍卡住，则排除、选择/标记并继续。"},"recall":{"en":"What is the goal of the final 24 hours?","zh":"最后 24 小时的目标是什么？"},"answer":{"en":"Arrive rested, organized, fueled, and confident enough to execute the practiced pacing and decision process.","zh":"以充分休息、后勤明确、能量充足和稳定信心进入考场，执行已演练的节奏与决策流程。"}}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now())
on conflict (certification_id, task_id, language, version) do update set
  title = excluded.title,
  summary = excluded.summary,
  content = excluded.content,
  source_refs = excluded.source_refs,
  status = excluded.status,
  published_at = excluded.published_at,
  updated_at = now();

insert into public.lessons (
  certification_id, task_id, language, title, summary, content,
  source_refs, version, status, published_at
)
values
  ('nsca-cscs-5', 'course-chapter-1', 'en', 'Structure and Function of Body Systems', 'Explain how muscle, bone, neural, cardiovascular, and respiratory systems combine to produce performance.', '{"n":1,"title":{"en":"Structure and Function of Body Systems","zh":"身体系统的结构与功能"},"domain":{"en":"Exercise Science","zh":"运动科学"},"minutes":150,"source":"Essentials, 5th ed., Ch. 1 · DCO Exercise Science A, B, D, G, H","objectives":[{"en":"Explain how muscle, bone, neural, cardiovascular, and respiratory systems combine to produce performance.","zh":"解释肌肉、骨骼、神经、心血管和呼吸系统如何共同产生运动表现。"},{"en":"Trace excitation-contraction coupling and distinguish fiber types, receptors, and muscle actions.","zh":"完整描述兴奋-收缩耦联，并区分肌纤维、感受器和肌肉动作。"},{"en":"Predict acute cardiorespiratory responses to aerobic and anaerobic exercise.","zh":"预测有氧与无氧运动的急性心肺反应。"}],"sections":[{"id":"musculoskeletal","title":{"en":"Muscle, bone, and connective-tissue organization","zh":"肌肉、骨骼与结缔组织层级"},"explanation":["Skeletal muscle is organized from whole muscle to fascicle, muscle fiber, myofibril, sarcomere, and myofilament. Epimysium surrounds the muscle, perimysium surrounds fascicles, and endomysium surrounds individual fibers. These connective layers merge into tendons that transmit muscle force to bone.","Bone is living tissue. Cortical bone provides a dense outer shell; trabecular bone forms an internal lattice. Osteoblasts build bone, osteoclasts resorb it, and osteocytes sense mechanical strain. Training adaptation depends on loading magnitude, rate, direction, and repetition as well as recovery and nutrition."],"details":["A sarcomere extends from Z-line to Z-line. The A band corresponds to the length of thick filaments; the I band contains thin filaments not overlapping thick filaments; the H zone is the central thick-only region.","Tendons connect muscle to bone and transmit force. Ligaments connect bone to bone and contribute to joint stability. Both adapt more slowly than muscle because of lower metabolic activity and blood supply.","The periosteum covers the external bone surface and is important for growth, repair, and tendon or ligament attachment. The epiphyseal plate is relevant when programming for growing athletes.","Wolff''s law describes bone remodeling in response to mechanical stress; connective tissues respond best to progressive, specific loading rather than abrupt workload spikes."],"decision":{"en":"When strength rises faster than tendon tolerance, progress load and volume conservatively; tissue capacity is limited by the slowest-adapting structure, not only by muscle force.","zh":"当力量增长快于肌腱耐受时，应保守推进负荷和容量；组织能力受适应最慢的结构限制，而不只看肌肉力量。"},"examCue":{"en":"Know the structural hierarchy and what changes during contraction. Filaments slide; they do not shorten.","zh":"掌握结构层级与收缩时的变化：肌丝滑动，但本身不缩短。"}},{"id":"contraction","title":{"en":"Excitation-contraction coupling and muscle actions","zh":"兴奋-收缩耦联与肌肉动作"},"explanation":["A motor-neuron action potential releases acetylcholine at the neuromuscular junction. Depolarization spreads along the sarcolemma and through T-tubules, triggering calcium release from the sarcoplasmic reticulum. Calcium binds troponin, moves tropomyosin away from actin''s binding sites, and permits ATP-dependent cross-bridge cycling.","During the power stroke, myosin pulls actin toward the sarcomere center. A new ATP molecule detaches myosin; ATP hydrolysis re-cocks the head. Relaxation requires calcium reuptake into the sarcoplasmic reticulum, which is also an active, energy-requiring process."],"details":["Concentric action: muscle produces force while shortening. Eccentric action: muscle produces force while lengthening. Isometric action: force is produced with no visible joint movement.","Eccentric actions can usually tolerate greater external load with lower energy cost, but unfamiliar eccentric volume produces more muscle damage and delayed soreness.","Length-tension describes the effect of sarcomere overlap on force. Force is reduced when the sarcomere is excessively shortened or lengthened.","The stretch-shortening cycle combines a rapid eccentric action, a brief amortization transition, and a concentric action. A long transition dissipates stored elastic energy and reduces potentiation."],"decision":{"en":"Select tempo and muscle action for the adaptation: controlled eccentrics for tissue loading, isometrics for angle-specific force, and high-intent concentrics for power.","zh":"按目标选择节奏和肌肉动作：受控离心用于组织负荷，等长用于特定角度力量，高意图向心用于功率。"},"examCue":{"en":"If the load moves down under control, the prime movers may be acting eccentrically even though gravity determines the movement direction.","zh":"负荷受控下降时，主动肌可能进行离心动作；不要用运动方向代替肌肉动作判断。"}},{"id":"neuromuscular","title":{"en":"Motor units, fiber types, and proprioceptors","zh":"运动单位、肌纤维与本体感受器"},"explanation":["A motor unit is one alpha motor neuron and every muscle fiber it innervates. Force rises through recruitment of additional motor units and increased firing rate. Recruitment generally follows the size principle: low-threshold, fatigue-resistant units are recruited before larger, high-force units as force demand increases.","Type I fibers contract slowly, resist fatigue, and have high mitochondrial and capillary density. Type II fibers shorten faster and produce greater force and power; IIa fibers have meaningful oxidative capacity, while the fastest phenotype is more glycolytic and fatigue-prone. Training shifts fiber properties along a continuum rather than creating an entirely different fiber inventory."],"details":["Rate coding is the change in motor-neuron firing frequency. Temporal summation occurs when stimuli arrive before complete relaxation, increasing force; tetanus is a sustained high-force state.","Muscle spindles lie in parallel with muscle fibers and sense muscle length and rate of stretch. Rapid stretch increases the stretch reflex and alpha motor-neuron activity.","Golgi tendon organs lie in series near the musculotendinous junction and respond to tension. Their feedback helps regulate force and protect tissue; training can change tolerance to high tension.","Reciprocal inhibition reduces antagonist activation when the agonist is activated. Autogenic inhibition refers to reduced activation of the same muscle after high tension and is used in some PNF explanations."],"decision":{"en":"High-load or high-velocity intent recruits high-threshold motor units. For power training, preserve intent and repetition quality rather than accumulating slow fatigue repetitions.","zh":"高负荷或高速度意图会募集高阈值运动单位。功率训练应保护意图和重复质量，而不是堆积疲劳慢动作。"},"examCue":{"en":"Muscle spindle = length and velocity of stretch; Golgi tendon organ = tension. Do not reverse them.","zh":"肌梭感受长度与拉伸速度；高尔基腱器官感受张力，切勿混淆。"}},{"id":"cardiovascular","title":{"en":"Cardiovascular transport and acute responses","zh":"心血管运输与急性反应"},"explanation":["The right heart receives deoxygenated systemic blood and pumps it through the pulmonary circulation. The left heart receives oxygenated blood and pumps it through the systemic circulation. Arteries carry blood away from the heart, veins return it, and capillaries provide the exchange surface.","During dynamic aerobic exercise, heart rate, stroke volume, cardiac output, and systolic blood pressure rise. Diastolic pressure usually changes little because vasodilation lowers peripheral resistance in active tissue. During heavy resistance exercise, intramuscular compression and the Valsalva maneuver can produce very large, brief blood-pressure responses."],"details":["Cardiac output equals heart rate multiplied by stroke volume. Stroke volume depends on preload, contractility, and afterload.","The Frank-Starling mechanism links greater ventricular filling to stronger contraction within physiological limits.","Blood flow is redistributed toward active muscle and skin during exercise. Plasma volume can temporarily fall because of filtration, sweating, and fluid shifts.","Arteriovenous oxygen difference reflects how much oxygen tissues extract from blood. Both central delivery and peripheral extraction determine maximal oxygen consumption."],"decision":{"en":"Use breathing instruction and appropriate screening with high-load lifting. Breath holding can improve trunk stiffness but is not appropriate for every athlete or medical context.","zh":"高负荷训练中应根据个体教授呼吸并进行筛查。屏息可提高躯干刚度，但并非适合所有运动员或医疗情境。"},"examCue":{"en":"Dynamic aerobic work: systolic pressure rises, diastolic pressure is relatively stable. Heavy resistance work can spike both pressures.","zh":"动态有氧：收缩压上升、舒张压相对稳定；大重量抗阻可使两者短时显著升高。"}},{"id":"respiratory","title":{"en":"Respiratory exchange and integrated oxygen use","zh":"呼吸交换与氧利用整合"},"explanation":["Ventilation moves air; diffusion moves gases across the alveolar-capillary membrane; perfusion moves blood through pulmonary capillaries. Oxygen binds primarily to hemoglobin, while carbon dioxide is transported dissolved, bound to proteins, and mainly as bicarbonate.","Minute ventilation equals tidal volume times breathing frequency. At low-to-moderate intensities, both rise; at high intensity, breathing frequency contributes increasingly. Ventilatory thresholds reflect nonlinear increases associated with metabolic acidosis and carbon-dioxide production."],"details":["External respiration is gas exchange between alveoli and blood; internal respiration is exchange between blood and tissues.","Oxygen delivery depends on ventilation, diffusion, hemoglobin concentration and saturation, cardiac output, and local blood flow.","The Fick relationship expresses oxygen consumption as cardiac output multiplied by arterial-venous oxygen difference.","Short maximal efforts do not stop using oxygen; all energy systems contribute, but the relative contribution changes with intensity, duration, and recovery."],"decision":{"en":"When performance falls, distinguish ventilatory limitation from local muscular fatigue, low oxygen-carrying capacity, poor economy, or inadequate recovery.","zh":"表现下降时，应区分通气限制、局部肌肉疲劳、携氧能力不足、经济性差或恢复不足。"},"examCue":{"en":"Ventilation is not the same as oxygen consumption. VO2 requires delivery and extraction, not simply faster breathing.","zh":"通气量不等于摄氧量；VO2 需要氧输送和组织提取，而不只是呼吸更快。"}}],"terms":[{"term":"Sarcomere","meaning":{"en":"The functional contractile unit from Z-line to Z-line.","zh":"从 Z 线到 Z 线的肌肉功能性收缩单位。"}},{"term":"Motor unit","meaning":{"en":"One alpha motor neuron and all fibers it innervates.","zh":"一个 α 运动神经元及其支配的全部肌纤维。"}},{"term":"Rate coding","meaning":{"en":"Regulation of force through motor-neuron firing frequency.","zh":"通过运动神经元放电频率调节力量。"}},{"term":"Stroke volume","meaning":{"en":"Blood ejected by the left ventricle per beat.","zh":"左心室每次搏动射出的血量。"}},{"term":"Cardiac output","meaning":{"en":"Blood pumped per minute: heart rate × stroke volume.","zh":"每分钟泵血量：心率 × 每搏输出量。"}},{"term":"Minute ventilation","meaning":{"en":"Air ventilated per minute: tidal volume × breathing frequency.","zh":"每分钟通气量：潮气量 × 呼吸频率。"}}],"formulas":[{"name":"Cardiac output","expression":"Q = HR × SV","use":{"en":"Connect heart rate and stroke volume to systemic blood flow.","zh":"把心率和每搏输出量与全身血流联系起来。"},"example":"HR 150 bpm × SV 120 mL = 18,000 mL/min = 18 L/min"},{"name":"Fick equation","expression":"VO₂ = Q × (a-vO₂ difference)","use":{"en":"Explain central oxygen delivery and peripheral extraction.","zh":"解释中枢氧输送与外周氧提取。"}},{"name":"Mean arterial pressure","expression":"MAP ≈ DBP + ⅓(SBP − DBP)","use":{"en":"Estimate average arterial driving pressure at normal resting rates.","zh":"在正常静息心率下估算平均动脉驱动压。"}},{"name":"Minute ventilation","expression":"V̇E = tidal volume × breathing frequency","use":{"en":"Separate breath depth from breathing rate.","zh":"区分呼吸深度与频率。"}}],"examChecklist":[{"en":"Trace the route of blood through every chamber, valve, and circulation.","zh":"口述血液经过心腔、瓣膜和循环的完整路径。"},{"en":"Compare type I and type II fibers by force, speed, fatigue, mitochondria, and typical recruitment.","zh":"按力量、速度、疲劳、线粒体和募集比较 I 型与 II 型纤维。"},{"en":"Predict what happens to HR, SV, Q, SBP, DBP, ventilation, and a-vO₂ difference as exercise intensity rises.","zh":"预测运动强度上升时 HR、SV、Q、SBP、DBP、通气和动静脉氧差的变化。"}],"recall":[{"prompt":{"en":"Trace excitation-contraction coupling without notes.","zh":"不看资料口述兴奋-收缩耦联。"},"answer":{"en":"Motor-neuron action potential → acetylcholine → sarcolemma/T-tubule depolarization → calcium release → troponin binding → tropomyosin shift → ATP-driven cross-bridge cycling → calcium reuptake for relaxation.","zh":"运动神经元动作电位 → 乙酰胆碱 → 肌膜/T 管去极化 → 释放钙 → 钙结合肌钙蛋白 → 原肌球蛋白移位 → ATP 驱动横桥循环 → 钙回收并舒张。"}},{"prompt":{"en":"Why can cardiac output rise even if stroke volume plateaus?","zh":"为什么每搏输出量平台后心输出量仍可上升？"},"answer":{"en":"Because heart rate can continue rising, and Q equals HR × SV.","zh":"因为心率仍可上升，而 Q = HR × SV。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-2', 'en', 'Biomechanics of Resistance Exercise', 'Analyze movement using planes, axes, joint actions, forces, moments, and muscle roles.', '{"n":2,"title":{"en":"Biomechanics of Resistance Exercise","zh":"抗阻运动的生物力学"},"domain":{"en":"Exercise Science","zh":"运动科学"},"minutes":135,"source":"Essentials, 5th ed., Ch. 2 · DCO Exercise Science C","objectives":[{"en":"Analyze movement using planes, axes, joint actions, forces, moments, and muscle roles.","zh":"使用平面、轴、关节动作、力、力矩和肌肉角色分析动作。"},{"en":"Calculate work, power, impulse, torque, and mechanical advantage.","zh":"计算功、功率、冲量、力矩和机械优势。"},{"en":"Use force-time and force-velocity relationships to guide exercise selection.","zh":"用力-时间和力-速度关系指导动作选择。"}],"sections":[{"id":"movement-language","title":{"en":"Planes, axes, and joint actions","zh":"平面、轴与关节动作"},"explanation":["The sagittal plane divides left and right and contains flexion-extension movements around a mediolateral axis. The frontal plane divides front and back and contains abduction-adduction around an anteroposterior axis. The transverse plane divides upper and lower and contains rotation around a longitudinal axis.","Real sport movement is multiplanar. The exam may ask for the dominant plane or joint action, so analyze each joint separately and specify the phase. The same muscle can have different roles across phases or when joint position changes."],"details":["Agonist: principal contributor to a joint action. Antagonist: opposes it. Synergist assists. Stabilizer limits unwanted movement. Neutralizer cancels an unwanted action of another muscle.","Open-chain movement leaves the distal segment free; closed-chain movement fixes or constrains it. This changes joint motion, force distribution, and muscle coordination.","Acceleration is the change in velocity over time. Kinematics describes motion; kinetics examines forces that cause or result from motion.","Center of mass location changes with body position and external load. Stability generally rises with a wider base, lower center of mass, and projection of the center of mass within the base."],"decision":{"en":"Name the joint, phase, plane, axis, and muscle action before choosing a technique correction.","zh":"在选择技术纠正前，先明确关节、阶段、平面、轴和肌肉动作。"},"examCue":{"en":"Do not label a whole exercise with one action. A squat descent includes eccentric control at several joints; ascent reverses the actions.","zh":"不要用一个动作概括整个练习。深蹲下降包含多个关节的离心控制，上升阶段动作相反。"}},{"id":"force-torque","title":{"en":"Force, torque, levers, and mechanical advantage","zh":"力、力矩、杠杆与机械优势"},"explanation":["Force changes motion according to mass and acceleration. Torque is the rotary effect of force and equals force multiplied by its perpendicular moment arm. Because the moment arm changes with joint angle, the same external load creates different joint torque through the range of motion.","First-class levers place the axis between force and resistance; second-class levers place resistance between axis and force; third-class levers place force between axis and resistance. Most human musculoskeletal levers are third class: mechanically disadvantaged for force but advantageous for speed and range of motion."],"details":["Internal torque from muscle must oppose or exceed external torque to hold or move a load. A long external moment arm increases muscular demand.","Mechanical advantage is the force arm divided by resistance arm. A value above one favors force; below one favors speed and displacement.","A cam machine changes the resistance moment arm through the range to better match a target strength curve. Free-weight torque is governed by gravity and the horizontal distance to the joint axis.","Friction opposes relative motion. Ground-reaction force is the equal-and-opposite force the ground applies to the athlete."],"decision":{"en":"To regress a movement without changing load, shorten the external moment arm or move the load closer to the working joint and center of mass.","zh":"不改变重量也可降低动作难度：缩短外部力臂，或让负荷更靠近工作关节和身体重心。"},"examCue":{"en":"Moment arm must be perpendicular. Distance along a limb is not automatically the torque-producing moment arm.","zh":"力臂必须是垂直距离；沿肢体的距离不一定就是产生力矩的力臂。"}},{"id":"work-power-impulse","title":{"en":"Work, power, momentum, and impulse","zh":"功、功率、动量与冲量"},"explanation":["Mechanical work occurs when force produces displacement in its direction. Power is the rate of doing work and can also be expressed as force multiplied by velocity. Two athletes may perform the same work, but the athlete completing it faster produces greater average power.","Momentum equals mass times velocity. Impulse equals force multiplied by the time it acts and equals the change in momentum. Jumping, sprinting, landing, and changing direction are therefore force-time problems, not force-only problems."],"details":["The force-time curve reveals peak force, time to peak, rate of force development, and impulse. Sport success may depend on force available within a short time window rather than maximal force measured without a time limit.","Average power differs from peak instantaneous power. Specify which metric a test reports.","Landing impulse can be distributed over more time by coordinated hip, knee, and ankle flexion, lowering peak force while producing the same total change in momentum.","Strength increases the ceiling for force; ballistic and explosive training improve how quickly usable force is expressed."],"decision":{"en":"Match the metric to the sport task: peak force for maximal-force demands, rate of force development for brief contacts, and impulse when force must be sustained over a defined time.","zh":"让指标匹配专项：最大力量需求看峰值力，短接触看力量发展率，需要在时间内持续施力时看冲量。"},"examCue":{"en":"Power is not synonymous with force. A heavy slow lift may have high force but less power than a lighter fast movement.","zh":"功率不等于力量；大重量慢速动作力量高，但功率可能低于较轻的高速动作。"}},{"id":"muscle-mechanics","title":{"en":"Force-length, force-velocity, and strength curves","zh":"力-长度、力-速度与力量曲线"},"explanation":["Active force depends on actin-myosin overlap; passive force rises as elastic tissues are stretched. Total force is the sum of active and passive components. Multi-joint movement also depends on moment arms, coordination, and the strength of muscles at each joint angle.","During concentric actions, force capacity falls as shortening velocity rises. During eccentric actions, force capacity rises above isometric levels as lengthening velocity increases and then plateaus. Power is normally maximized at an intermediate combination of force and velocity."],"details":["An ascending strength curve becomes mechanically stronger through the concentric range; a descending curve becomes weaker; a bell-shaped curve is strongest in the middle.","Accommodating resistance with bands or chains can increase external resistance where the athlete is mechanically stronger.","The sticking region reflects an unfavorable combination of joint angles, moment arms, muscle lengths, and bar momentum rather than a single weak muscle in every athlete.","Isokinetic dynamometers control angular velocity; isotonic literally implies constant tension, which free-weight movement does not maintain perfectly."],"decision":{"en":"Use load, intent, range, and resistance profile together. Do not assume that one percentage of 1RM creates the same velocity or effort in every exercise and athlete.","zh":"结合负荷、意图、幅度和阻力曲线；不要假定同一 1RM 百分比在不同动作和运动员中产生相同速度或用力。"},"examCue":{"en":"Concentric: faster velocity means lower force capacity. Eccentric force capacity exceeds isometric and concentric force capacity.","zh":"向心速度越快，力量能力越低；离心力量能力通常高于等长和向心。"}},{"id":"joint-risk","title":{"en":"Joint loading and technique decisions","zh":"关节负荷与技术决策"},"explanation":["Joint stress cannot be inferred from one visible angle alone. External load, moment arm, movement speed, tissue tolerance, fatigue, anatomy, and technique all matter. The coach identifies modifiable risk while preserving the training goal.","Spinal loading includes compression, shear, and bending moments. Trunk stiffness, load position, and technique influence their distribution. Knee and shoulder questions similarly require identifying the direction of external force and the athlete''s capacity, not relying on slogans."],"details":["Moving a load away from the body generally increases the external moment arm and trunk demand.","A controlled Valsalva maneuver can increase intra-abdominal pressure and torso stiffness during heavy effort, but screening and context matter.","Technique standards should be scaled to the athlete''s anatomy and task while maintaining joint control and safe equipment use.","Fatigue changes kinematics and force distribution; terminate or regress when the target quality or safety standard cannot be maintained."],"decision":{"en":"Correct the highest-risk or most performance-limiting fault first with one short external cue, then reobserve.","zh":"先用一个简短外部提示纠正风险最高或最限制表现的问题，再重新观察。"},"examCue":{"en":"Choose the answer that manages the actual force or moment described in the stem, not a universal ''perfect posture'' rule.","zh":"选择能处理题干实际力或力矩的答案，而不是套用所谓统一完美姿势。"}}],"terms":[{"term":"Kinematics","meaning":{"en":"Description of motion without focusing on its causes.","zh":"描述运动本身，不重点讨论其原因。"}},{"term":"Kinetics","meaning":{"en":"Forces and torques associated with motion.","zh":"与运动相关的力和力矩。"}},{"term":"Moment arm","meaning":{"en":"Perpendicular distance from the force line of action to the axis.","zh":"力的作用线到旋转轴的垂直距离。"}},{"term":"Impulse","meaning":{"en":"Force applied over time; equals change in momentum.","zh":"力在时间上的累积，等于动量变化。"}},{"term":"Rate of force development","meaning":{"en":"Change in force divided by change in time.","zh":"力量变化量除以时间变化量。"}}],"formulas":[{"name":"Force","expression":"F = m × a","use":{"en":"Relate mass and acceleration to net force.","zh":"把质量和加速度与合力联系起来。"},"example":"100 kg system × 2 m/s² = 200 N net force"},{"name":"Torque","expression":"τ = F × perpendicular moment arm","use":{"en":"Calculate rotary demand about a joint.","zh":"计算关节周围的旋转需求。"},"example":"200 N × 0.35 m = 70 N·m"},{"name":"Work","expression":"W = F × displacement","use":{"en":"Calculate mechanical energy transferred through displacement.","zh":"计算力通过位移传递的机械能。"}},{"name":"Power","expression":"P = W ÷ time = F × velocity","use":{"en":"Compare how rapidly work is performed.","zh":"比较完成工作的速率。"}},{"name":"Momentum and impulse","expression":"p = m × v; impulse = F × Δt = Δp","use":{"en":"Analyze acceleration, deceleration, jumping, and landing.","zh":"分析加速、减速、跳跃和落地。"}}],"examChecklist":[{"en":"Analyze a squat, bench press, sprint, and landing by phase and joint.","zh":"按阶段和关节分析深蹲、卧推、冲刺与落地。"},{"en":"Calculate torque, work, power, momentum, and impulse with units.","zh":"带单位计算力矩、功、功率、动量和冲量。"},{"en":"Explain why the same load feels different across joint angles.","zh":"解释为何相同负荷在不同关节角度感觉不同。"}],"recall":[{"prompt":{"en":"Why does holding a dumbbell farther from the elbow increase difficulty?","zh":"为什么把哑铃拿得离肘更远会更难？"},"answer":{"en":"It lengthens the perpendicular external moment arm, increasing external torque that the elbow flexors must oppose.","zh":"这增加了外部垂直力臂，使屈肘肌必须抵抗更大的外部力矩。"}},{"prompt":{"en":"How can landing with more flexion reduce peak force?","zh":"增加屈曲如何降低落地峰值力？"},"answer":{"en":"The same momentum change is spread over a longer time, so average and peak force can be lower.","zh":"相同动量变化分布在更长时间内，平均力和峰值力可降低。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-3', 'en', 'Bioenergetics of Exercise and Training', 'Explain how ATP is regenerated by phosphagen, glycolytic, and oxidative pathways.', '{"n":3,"title":{"en":"Bioenergetics of Exercise and Training","zh":"运动与训练的生物能量学"},"domain":{"en":"Exercise Science","zh":"运动科学"},"minutes":120,"source":"Essentials, 5th ed., Ch. 3 · DCO Exercise Science E, I","objectives":[{"en":"Explain how ATP is regenerated by phosphagen, glycolytic, and oxidative pathways.","zh":"解释磷酸原、糖酵解和氧化途径如何再合成 ATP。"},{"en":"Predict dominant energy-system contributions from intensity, duration, and recovery.","zh":"根据强度、时间和恢复预测供能贡献。"},{"en":"Connect substrate depletion, fatigue, and work-to-rest design.","zh":"把底物消耗、疲劳和做功-休息设计联系起来。"}],"sections":[{"id":"atp","title":{"en":"ATP, energy, and pathway interaction","zh":"ATP、能量与途径协作"},"explanation":["ATP hydrolysis releases usable energy for contraction, ion pumping, and cellular work. Stored ATP is limited, so continuous resynthesis is essential. The phosphagen, glycolytic, and oxidative systems are always active; ''dominant system'' means the largest relative contributor for the current task.","Energy-system selection follows the required rate of ATP production and total capacity. High power requires fast ATP delivery; long duration requires high total yield and sustainable substrate supply."],"details":["Catabolic reactions break molecules and release energy; anabolic reactions build molecules and require energy.","Exergonic reactions release energy, while endergonic reactions require it. Coupling ATP hydrolysis to contraction makes cellular work possible.","Enzymes regulate pathway rates but do not change the total energy available from a reaction.","Metabolic specificity means training adaptations reflect the pathways, rates, muscle actions, and recovery pattern repeatedly stressed."],"decision":{"en":"Program the output first, then choose work duration and recovery that preserve the desired ATP demand.","zh":"先确定目标输出，再选择能维持目标 ATP 需求的做功时间与恢复。"},"examCue":{"en":"Never answer that one system turns off when another begins. Contribution shifts continuously.","zh":"不要选择“一套系统开始、另一套关闭”的答案；贡献始终连续变化。"}},{"id":"phosphagen","title":{"en":"Phosphagen system and short maximal work","zh":"磷酸原系统与短时最大做功"},"explanation":["The phosphagen system uses stored ATP and phosphocreatine. Creatine kinase transfers a phosphate from phosphocreatine to ADP, rapidly restoring ATP. The system has the highest rate but lowest capacity and dominates very brief maximal efforts.","Phosphocreatine restoration is largely oxidative, so repeated maximal efforts need substantial recovery. Incomplete rest reduces peak power even when motivation remains high."],"details":["The adenylate kinase reaction can combine two ADP molecules to form ATP and AMP, but this is a smaller contribution.","Work intervals of only a few seconds can still accumulate glycolytic and oxidative contribution over repeated repetitions.","Longer between-set rest supports maximal strength, sprint, and power quality by improving phosphocreatine restoration and neural readiness.","Creatine supplementation can increase intramuscular creatine stores and repeated high-intensity capacity in responders; quality and scope-of-practice rules still apply."],"decision":{"en":"If the goal is maximal sprint or jump power, stop or extend rest when output falls beyond the planned threshold.","zh":"若目标是最大冲刺或跳跃功率，当输出下降超过计划阈值时应停止或延长休息。"},"examCue":{"en":"Short maximal work requires high work:rest ratios favoring rest; do not confuse a fatigue circuit with power training.","zh":"短时最大做功需要偏向休息的高休息比例；不要把疲劳循环训练当成功率训练。"}},{"id":"glycolysis","title":{"en":"Glycolysis, lactate, and high-intensity fatigue","zh":"糖酵解、乳酸与高强度疲劳"},"explanation":["Glycolysis converts glucose or glycogen to pyruvate in the cytosol. When ATP demand exceeds mitochondrial processing, pyruvate is converted to lactate while NAD+ is regenerated, allowing glycolysis to continue. Lactate is a usable fuel and transport molecule, not simply a waste product.","High-intensity fatigue is multifactorial. Hydrogen-ion accumulation, inorganic phosphate, disturbed calcium handling, substrate depletion, and neural factors can all impair output. Lactate concentration is associated with intense glycolysis but is not the sole cause of fatigue or next-day soreness."],"details":["Net ATP yield is greater from muscle glycogen than blood glucose because glycogen enters glycolysis after an ATP-requiring step.","Fast glycolysis supplies ATP rapidly but has lower capacity than oxidative metabolism.","Lactate can be oxidized by muscle or heart and can be converted back to glucose in the liver.","Buffering and transport adaptations improve tolerance and repeated high-intensity performance without eliminating metabolite accumulation."],"decision":{"en":"Use moderate rest and controlled output decline when the goal is glycolytic capacity; preserve longer rest when the goal is peak speed.","zh":"目标为糖酵解能力时可用中等休息并允许受控输出下降；目标为峰值速度时应保留更长休息。"},"examCue":{"en":"Lactate does not cause delayed-onset muscle soreness. DOMS is more closely related to unfamiliar mechanical stress and tissue disruption.","zh":"乳酸不会导致延迟性肌肉酸痛；DOMS 更与陌生机械应力和组织扰动相关。"}},{"id":"oxidative","title":{"en":"Oxidative metabolism and oxygen kinetics","zh":"氧化代谢与氧动力学"},"explanation":["The oxidative system uses mitochondrial pathways to oxidize carbohydrate, fat, and sometimes amino acids. Acetyl-CoA enters the citric acid cycle, reducing carriers deliver electrons to the electron transport chain, and the proton gradient drives ATP synthase.","Oxidative metabolism has a slower maximum rate but far greater capacity. It supports prolonged exercise and restores homeostasis between high-intensity bouts, including phosphocreatine resynthesis and lactate oxidation."],"details":["Carbohydrate supports a higher rate of ATP production per unit time; fat provides large energy reserves but requires more oxygen per ATP and slower processing.","At a given submaximal workload, trained athletes often show lower lactate, less ventilation, and reduced relative effort because of improved delivery, mitochondrial capacity, and economy.","EPOC reflects elevated postexercise oxygen use for restoration, thermoregulation, circulation, and other processes; it is not repayment of one single ''oxygen debt.''","The crossover toward greater carbohydrate use occurs as intensity rises, while long duration and lower glycogen availability increase relative fat use."],"decision":{"en":"Choose intensity using the athlete''s threshold, pace, power, heart rate, or perceived exertion—not a generic label alone.","zh":"应依据运动员阈值、配速、功率、心率或主观用力选择强度，而不只使用笼统标签。"},"examCue":{"en":"Higher fat oxidation does not necessarily mean higher total energy expenditure or better performance.","zh":"脂肪氧化比例更高不等于总能量消耗更高或表现更好。"}},{"id":"specificity","title":{"en":"Substrate recovery and metabolic specificity","zh":"底物恢复与代谢专项性"},"explanation":["Phosphocreatine, muscle glycogen, blood glucose, and fluid availability recover on different timelines. Recovery depends on depletion magnitude, nutrition, training status, blood flow, and time. A session''s quality therefore reflects both the current work interval and what preceded it.","Training design should reproduce the sport''s pattern without blindly copying game duration. Identify high-intensity action length, recovery type, total repetitions, positional demands, and the quality that must remain intact."],"details":["Work:rest ratio describes timing but not intensity. A 1:3 ratio can train different systems depending on speed, mode, and duration.","Active recovery can assist metabolite transport but may slow phosphocreatine restoration if its intensity is too high.","Glycogen restoration is accelerated by carbohydrate intake after demanding sessions, especially when the next session is soon.","Repeated-sprint ability depends on phosphocreatine recovery, aerobic capacity, buffering, neuromuscular qualities, and pacing."],"decision":{"en":"Track output across repetitions. The same written interval can become a different training stimulus when speed deteriorates.","zh":"追踪每次输出；当速度明显下降时，同一纸面间歇已经变成不同训练刺激。"},"examCue":{"en":"Duration alone does not identify the system. Intensity, mode, work:rest, and repetition number change the contribution.","zh":"不能只凭持续时间判断供能系统；强度、方式、做功休息比和重复次数都会改变贡献。"}}],"terms":[{"term":"Phosphocreatine","meaning":{"en":"A high-energy phosphate donor for rapid ATP resynthesis.","zh":"用于快速再合成 ATP 的高能磷酸供体。"}},{"term":"Glycolysis","meaning":{"en":"Cytosolic conversion of glucose or glycogen to pyruvate.","zh":"在细胞质中把葡萄糖或糖原转化为丙酮酸。"}},{"term":"Oxidative phosphorylation","meaning":{"en":"Mitochondrial ATP production using electron transport and oxygen.","zh":"利用电子传递和氧在线粒体中生成 ATP。"}},{"term":"Lactate threshold","meaning":{"en":"An exercise intensity associated with a sustained rise in blood lactate above baseline.","zh":"血乳酸持续高于基线的运动强度区域。"}},{"term":"EPOC","meaning":{"en":"Elevated oxygen consumption during recovery after exercise.","zh":"运动后恢复期升高的氧耗。"}}],"formulas":[{"name":"Work-to-rest ratio","expression":"work duration : recovery duration","use":{"en":"Describe interval timing while also specifying intensity and mode.","zh":"描述间歇时间，同时必须注明强度与方式。"},"example":"6 s sprint : 180 s recovery = 1:30"},{"name":"Metabolic power concept","expression":"ATP demand rate ∝ exercise intensity","use":{"en":"Distinguish rapid ATP rate from total ATP capacity.","zh":"区分快速 ATP 供给率与总容量。"}}],"examChecklist":[{"en":"Rank the systems by rate and capacity, then apply them to repeated work.","zh":"按供能速度和容量排序三大系统，并应用于重复做功。"},{"en":"Explain lactate production, transport, and oxidation without calling it waste.","zh":"解释乳酸生成、转运和氧化，避免把它称为废物。"},{"en":"Design intervals for peak power, glycolytic capacity, and aerobic development.","zh":"分别为峰值功率、糖酵解能力和有氧发展设计间歇。"}],"recall":[{"prompt":{"en":"Why does a repeated-sprint session become more oxidative over time?","zh":"为什么重复冲刺随时间会增加氧化供能？"},"answer":{"en":"Oxidative metabolism supports phosphocreatine restoration and contributes more as high-intensity stores are repeatedly depleted and recovery is incomplete.","zh":"氧化代谢支持磷酸肌酸恢复；高强度储备反复消耗且恢复不完全时，其相对贡献上升。"}},{"prompt":{"en":"Why is lactate not the direct cause of DOMS?","zh":"为什么乳酸不是 DOMS 的直接原因？"},"answer":{"en":"Lactate is cleared or reused relatively quickly, whereas DOMS peaks later and is linked to unfamiliar mechanical loading and inflammatory repair.","zh":"乳酸较快被清除或再利用，而 DOMS 更晚达到峰值，与陌生机械负荷和炎症修复相关。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-4', 'en', 'Endocrine Responses to Resistance Exercise and Training', 'Explain hormone classes, receptors, signaling, and feedback.', '{"n":4,"title":{"en":"Endocrine Responses to Resistance Exercise and Training","zh":"抗阻运动与训练的内分泌反应"},"domain":{"en":"Exercise Science","zh":"运动科学"},"minutes":105,"source":"Essentials, 5th ed., Ch. 4 · DCO Exercise Science F, H","objectives":[{"en":"Explain hormone classes, receptors, signaling, and feedback.","zh":"解释激素类别、受体、信号传导与反馈。"},{"en":"Predict acute hormonal responses from load, volume, rest, muscle mass, and training status.","zh":"根据负荷、容量、休息、肌群和训练状态预测急性激素反应。"},{"en":"Interpret testosterone, growth hormone, IGF, cortisol, and catecholamines without overclaiming causation.","zh":"正确解读睾酮、生长激素、IGF、皮质醇和儿茶酚胺，避免过度推断因果。"}],"sections":[{"id":"signaling","title":{"en":"Hormone classes, receptors, and signaling","zh":"激素类别、受体与信号传导"},"explanation":["Hormones are chemical messengers released into circulation. Peptide hormones and catecholamines generally bind cell-membrane receptors and use second-messenger cascades. Steroid hormones diffuse through cell membranes and bind intracellular receptors that influence gene transcription.","A hormone''s effect depends on concentration, receptor number and sensitivity, binding proteins, clearance, interaction with other signals, and the target tissue''s current state. More hormone in blood does not guarantee a larger tissue response."],"details":["Negative feedback stabilizes endocrine systems by reducing upstream stimulation when the downstream signal rises.","Upregulation increases receptor number or sensitivity; downregulation reduces responsiveness after persistent exposure.","Endocrine signaling travels through blood; paracrine signaling acts locally on neighboring cells; autocrine signaling acts on the same cell.","Permissive, additive, synergistic, and antagonistic interactions describe how combined hormones alter the final response."],"decision":{"en":"Treat hormonal measures as one part of a network. Combine them with performance, workload, sleep, nutrition, and symptoms.","zh":"把激素指标视为网络中的一部分，并与表现、负荷、睡眠、营养和症状结合。"},"examCue":{"en":"Steroid hormones use intracellular receptors; peptide hormones generally use membrane receptors and second messengers.","zh":"类固醇激素使用细胞内受体；肽类激素通常使用膜受体和第二信使。"}},{"id":"acute-response","title":{"en":"Acute resistance-exercise responses","zh":"抗阻运动的急性激素反应"},"explanation":["Acute endocrine responses are shaped by exercise selection, recruited muscle mass, intensity, total volume, rest interval, effort, training status, sex, age, nutrition, and time of day. Large-muscle, high-volume sessions with short-to-moderate rest often produce larger transient metabolic and hormonal disturbances.","These acute elevations help coordinate fuel availability, cardiovascular support, and tissue signaling, but the size of a postexercise blood spike is not a direct score of future hypertrophy or program quality."],"details":["Heavy resistance exercise can acutely increase testosterone, especially when substantial muscle mass and volume are involved.","Growth hormone responses are often greater with high volume, moderate loads, shorter rest, and metabolic stress.","Catecholamines rise with intensity and stress, increasing cardiac output and mobilizing substrates.","Cortisol supports energy availability and stress response; chronically interpreting it as simply ''bad'' ignores timing and context."],"decision":{"en":"Select variables for the performance adaptation, not to chase a hormone spike. Use hormonal data only when collection and interpretation are standardized.","zh":"按表现适应选择训练变量，而不是追求激素峰值；只有在采集与解释标准化时才使用激素数据。"},"examCue":{"en":"High volume plus short rest tends to increase metabolic stress and GH response; maximal strength uses heavier load and longer rest.","zh":"高容量加短休息倾向提高代谢压力和 GH 反应；最大力量训练使用更重负荷与更长休息。"}},{"id":"anabolic","title":{"en":"Testosterone, growth hormone, and IGF signaling","zh":"睾酮、生长激素与 IGF 信号"},"explanation":["Testosterone is a steroid hormone that supports protein remodeling, neural function, and training adaptation through androgen receptors. Growth hormone is a peptide hormone with metabolic and tissue-remodeling roles. Insulin-like growth factors act through endocrine and local pathways and are influenced by binding proteins.","Muscle remodeling reflects mechanical tension, local signaling, amino-acid availability, satellite-cell activity, and repeated exposure. Systemic hormone concentration is one input rather than the sole driver."],"details":["Resistance training can alter receptor content and tissue sensitivity even when resting hormone concentrations change little.","Insulin is permissive and anticatabolic when amino acids and energy are available; it is not necessary to create an extreme insulin spike after training.","IGF biology includes circulating and locally produced forms plus binding proteins that regulate availability.","Sex and age influence absolute concentrations, yet women and older adults still gain substantial strength and muscle from appropriate training."],"decision":{"en":"Evaluate adaptation through performance, body composition, training tolerance, and recovery trends rather than a single endocrine snapshot.","zh":"通过表现、身体成分、训练耐受和恢复趋势评估适应，而不是依赖一次激素检测。"},"examCue":{"en":"Do not infer that lower resting testosterone means an athlete cannot adapt, or that a larger acute spike guarantees hypertrophy.","zh":"不要推断较低静息睾酮意味着无法适应，也不要认为更大急性峰值必然带来肥大。"}},{"id":"stress","title":{"en":"Cortisol, catecholamines, and training stress","zh":"皮质醇、儿茶酚胺与训练压力"},"explanation":["Cortisol is released through the hypothalamic-pituitary-adrenal axis and helps maintain blood glucose, mobilize substrates, and regulate immune activity. Catecholamines support rapid sympathetic responses, increasing heart rate, contractility, blood flow redistribution, and fuel mobilization.","A useful stress response is acute and recoverable. Problems arise when training, competition, life stress, travel, sleep loss, or low energy availability chronically exceed recovery capacity."],"details":["Epinephrine is primarily released from the adrenal medulla; norepinephrine is also released from sympathetic nerve endings.","Repeated training reduces the hormonal cost of a standardized submaximal workload as the athlete becomes more efficient.","Peripheral blood values vary with posture, food, circadian rhythm, hydration, collection timing, and assay method.","No single hormone reliably diagnoses overtraining syndrome; use a pattern of performance and multidomain symptoms."],"decision":{"en":"When performance falls with sleep, mood, soreness, or illness changes, reduce uncertainty with standardized monitoring before making large program changes.","zh":"表现下降并伴随睡眠、情绪、酸痛或疾病变化时，应先用标准化监控降低不确定性，再做重大计划调整。"},"examCue":{"en":"Cortisol is necessary, not purely harmful. Context, timing, and chronic balance determine interpretation.","zh":"皮质醇是必需激素，并非纯粹有害；解释取决于情境、时间和长期平衡。"}}],"terms":[{"term":"Receptor","meaning":{"en":"A protein that binds a signal and initiates a cellular response.","zh":"结合信号并启动细胞反应的蛋白质。"}},{"term":"Second messenger","meaning":{"en":"An intracellular signal activated after a membrane receptor is stimulated.","zh":"膜受体受刺激后激活的细胞内信号。"}},{"term":"Upregulation","meaning":{"en":"Increase in receptor number or responsiveness.","zh":"受体数量或反应性增加。"}},{"term":"Catecholamines","meaning":{"en":"Epinephrine and norepinephrine; rapid sympathetic mediators.","zh":"肾上腺素与去甲肾上腺素，快速交感反应介质。"}},{"term":"Cortisol","meaning":{"en":"A glucocorticoid involved in substrate mobilization and stress regulation.","zh":"参与底物动员和压力调节的糖皮质激素。"}}],"formulas":[],"examChecklist":[{"en":"Classify steroid versus peptide hormone signaling.","zh":"区分类固醇与肽类激素信号。"},{"en":"Predict how load, volume, rest, and muscle mass alter the acute response.","zh":"预测负荷、容量、休息和肌群大小如何改变急性反应。"},{"en":"Explain why systemic hormone changes cannot independently prove adaptation.","zh":"解释为何系统性激素变化不能单独证明适应。"}],"recall":[{"prompt":{"en":"Why can two athletes show different responses to the same hormone concentration?","zh":"为什么相同激素浓度可在两名运动员中产生不同反应？"},"answer":{"en":"Receptor number and sensitivity, binding proteins, clearance, target-tissue state, and interacting signals can differ.","zh":"受体数量与敏感性、结合蛋白、清除速度、靶组织状态和其他信号均可不同。"}},{"prompt":{"en":"What session variables tend to increase acute growth-hormone response?","zh":"哪些训练变量倾向提高急性生长激素反应？"},"answer":{"en":"Large muscle mass, higher total volume, moderate-to-heavy loading, relatively short rest, and substantial metabolic stress.","zh":"大肌群、较高总容量、中高负荷、相对短休息和显著代谢压力。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-5', 'en', 'Adaptations to Anaerobic Training', 'Connect resistance, sprint, and plyometric training to neural, muscular, connective-tissue, and metabolic adaptation.', '{"n":5,"title":{"en":"Adaptations to Anaerobic Training","zh":"无氧训练的适应"},"domain":{"en":"Exercise Science","zh":"运动科学"},"minutes":120,"source":"Essentials, 5th ed., Ch. 5 · DCO Exercise Science D, H, I","objectives":[{"en":"Connect resistance, sprint, and plyometric training to neural, muscular, connective-tissue, and metabolic adaptation.","zh":"把抗阻、冲刺和增强式训练与神经、肌肉、结缔组织和代谢适应联系起来。"},{"en":"Explain hypertrophy, strength gain, tendon and bone adaptation, concurrent training, and detraining.","zh":"解释肥大、力量增长、肌腱与骨适应、并行训练和停训。"}],"sections":[{"id":"neural-adaptation","title":{"en":"Neural adaptation and skill expression","zh":"神经适应与技能表现"},"explanation":["Early strength gains are largely neural: improved recruitment of high-threshold motor units, firing rate, intermuscular coordination, technique, and reduced unnecessary antagonist coactivation. These changes are specific to the movement, contraction type, velocity, range, and intent practiced.","Maximal strength raises the force ceiling; explosive training improves rapid expression. Rate of force development is strongly task- and time-window-specific."],"details":["Experienced athletes may show smaller rapid gains because basic recruitment and skill are already developed.","Bilateral deficit or facilitation describes differences between summed unilateral force and bilateral force; the direction varies by athlete and task.","Motor learning can increase measured 1RM without equivalent structural change, especially during early familiarization.","High intent matters even when the bar moves slowly under heavy load because attempted acceleration influences neural drive."],"decision":{"en":"Use repeated high-quality exposure to the target skill; changing exercises too frequently can reduce practice specificity.","zh":"对目标技能进行重复高质量练习；过于频繁更换动作会降低练习专项性。"},"examCue":{"en":"A rapid 1RM increase in the first weeks is more likely neural and technical than new fiber formation.","zh":"前几周 1RM 快速上升更可能来自神经和技术，而非新肌纤维形成。"}},{"id":"hypertrophy","title":{"en":"Muscle hypertrophy and architecture","zh":"肌肉肥大与结构"},"explanation":["Hypertrophy occurs when repeated training and nutrition produce a net accumulation of muscle protein and related cellular material. Mechanical tension is the primary training signal; sufficient volume, proximity to failure, range, and progression determine how much tissue is effectively stimulated.","Muscle architecture can adapt through changes in physiological cross-sectional area, pennation angle, fascicle length, and fiber phenotype. Hyperplasia is not considered a primary explanation for human training-induced muscle growth."],"details":["Type II fibers generally have greater hypertrophy potential, though all recruited fibers can adapt.","Multiple loading zones can produce hypertrophy when sets are sufficiently challenging; heavier loads are more specific to maximal strength.","Satellite cells support remodeling and may donate nuclei to growing fibers.","Swelling immediately after training is not the same as chronic hypertrophy; standardized measurement is essential."],"decision":{"en":"Build weekly volume progressively, distribute hard sets so quality remains high, and ensure adequate protein and energy availability.","zh":"逐步建立周训练量，分散高强度组以保持质量，并保证蛋白质与能量充足。"},"examCue":{"en":"Strength and hypertrophy overlap but are not identical outcomes. Neural skill and loading specificity explain part of strength gain.","zh":"力量与肥大重叠但并不相同；神经技能和负荷专项性解释部分力量增长。"}},{"id":"connective","title":{"en":"Bone, tendon, ligament, and cartilage adaptation","zh":"骨、肌腱、韧带与软骨适应"},"explanation":["Mechanical loading stimulates bone remodeling and connective-tissue collagen synthesis. Adaptation is site-specific and responds to strain magnitude, rate, direction, and novelty. High-rate and multidirectional loading can be osteogenic when introduced safely.","Tendon adaptation includes changes in stiffness, material properties, and cross-sectional area, but its time course is slower than neural or muscle adaptation. Sudden workload increases can therefore exceed tissue capacity even when the athlete feels muscularly strong."],"details":["Bone adaptation requires adequate energy, protein, calcium, vitamin D, and hormonal health in addition to mechanical strain.","Progressive heavy loading and appropriately dosed plyometrics can improve tendon mechanical properties.","Ligament and joint adaptation is slower and less visible; absence of soreness does not prove readiness for a large spike.","Immobilization and unloading rapidly reduce tissue capacity, so return-to-training must be progressive."],"decision":{"en":"Progress tissue load using magnitude, rate, volume, and frequency—not load alone—and monitor the next-day response.","zh":"用负荷大小、加载速度、容量和频率共同推进组织负荷，而不只看重量，并监测次日反应。"},"examCue":{"en":"Muscle may adapt faster than tendon and bone. The correct progression often protects the slower tissue.","zh":"肌肉可比肌腱和骨适应更快；正确进阶通常要保护更慢的组织。"}},{"id":"metabolic","title":{"en":"Metabolic and cardiovascular adaptations","zh":"代谢与心血管适应"},"explanation":["Anaerobic training increases capacity in the pathways and contractile tasks stressed. Adaptations can include greater phosphagen availability, glycolytic enzyme activity, buffering, glycogen storage, repeated-sprint ability, and tolerance of high force or velocity.","Resistance training can improve cardiac and vascular health, but its central endurance adaptations differ from those produced by sustained aerobic training. Acute blood-pressure spikes should not be confused with chronic resting responses."],"details":["Sprint training recruits large motor units and can produce both anaerobic and aerobic adaptation depending on work and recovery.","Buffering improvements help manage acid-base disturbance during intense work.","Resting heart rate may change little with resistance training even when health and work capacity improve.","Specificity means a hypertrophy block, maximal-strength block, and repeated-sprint block should not be expected to produce identical adaptations."],"decision":{"en":"Write the intended adaptation beside every training variable; if a variable does not support the goal, change it.","zh":"在每个训练变量旁写明目标适应；若变量不支持目标，就应调整。"},"examCue":{"en":"Anaerobic training can still improve oxidative function; categories describe emphasis, not exclusive biology.","zh":"无氧训练仍可改善氧化功能；分类表示强调方向，而非排他生理。"}},{"id":"concurrent-detraining","title":{"en":"Concurrent training, interference, and detraining","zh":"并行训练、干扰与停训"},"explanation":["Concurrent training can improve strength and endurance together, but high endurance volume, fatigue, conflicting molecular signals, and poor sequencing may blunt strength or power development. Interference is most concerning when lower-body endurance volume is high and maximal strength or power is the priority.","Detraining reverses adaptations at different rates. Some neural and aerobic changes decline within weeks, while structural changes may persist longer. A small maintenance dose can preserve more adaptation than complete cessation."],"details":["Separate demanding strength and endurance sessions when possible; prioritize the most important quality earlier or on a fresher day.","Cycling may create less eccentric muscle damage than running, but mode must still match sport and athlete.","In-season maintenance usually reduces volume while retaining some intensity and specificity.","Training age, nutrition, sleep, and total stress alter how much concurrent work an athlete tolerates."],"decision":{"en":"Protect the priority quality with sequencing, spacing, and volume control rather than automatically removing all endurance work.","zh":"通过训练顺序、间隔和容量控制保护优先能力，而不是自动取消所有耐力训练。"},"examCue":{"en":"Interference is conditional, not inevitable. Look for high volume, poor recovery, similar muscle groups, and competing priorities.","zh":"干扰是有条件的，并非必然；关注高容量、恢复不足、相同肌群和竞争目标。"}}],"terms":[{"term":"Hypertrophy","meaning":{"en":"Increase in muscle-fiber size and associated tissue.","zh":"肌纤维及相关组织尺寸增加。"}},{"term":"Pennation angle","meaning":{"en":"Angle between muscle fibers and the line of force transmission.","zh":"肌纤维与力传递方向之间的角度。"}},{"term":"Buffering capacity","meaning":{"en":"Ability to resist disruptive changes in acid-base balance.","zh":"抵抗酸碱平衡扰动的能力。"}},{"term":"Concurrent training","meaning":{"en":"Training strength/power and endurance qualities within the same program period.","zh":"在同一计划阶段训练力量/功率和耐力能力。"}},{"term":"Detraining","meaning":{"en":"Partial or complete loss of adaptation after reduced or stopped training.","zh":"训练减少或停止后适应部分或完全消退。"}}],"formulas":[{"name":"Training volume load","expression":"sets × reps × external load","use":{"en":"Compare one estimate of resistance-training work while recognizing its limits.","zh":"比较抗阻训练工作量的一种估计，同时认识其局限。"}}],"examChecklist":[{"en":"Separate early neural gains from later structural gains.","zh":"区分早期神经增长与后期结构增长。"},{"en":"Compare adaptations from hypertrophy, strength, power, and sprint training.","zh":"比较肥大、力量、功率和冲刺训练的适应。"},{"en":"Explain how to reduce concurrent-training interference.","zh":"解释如何降低并行训练干扰。"}],"recall":[{"prompt":{"en":"Why can strength increase without measurable hypertrophy?","zh":"为什么力量可在没有可测肥大时上升？"},"answer":{"en":"Neural recruitment, firing rate, coordination, technique, and task-specific skill can increase force expression.","zh":"运动单位募集、放电频率、协调、技术和专项技能可提高力量表达。"}},{"prompt":{"en":"What is the simplest in-season maintenance principle?","zh":"最简单的赛季中维持原则是什么？"},"answer":{"en":"Retain some intensity and specificity while reducing total volume enough to recover from sport demands.","zh":"保留一定强度与专项性，同时把总容量降到能从比赛需求中恢复。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-6', 'en', 'Adaptations to Aerobic Training', 'Explain central and peripheral endurance adaptations and their effect on VO2max, threshold, and economy.', '{"n":6,"title":{"en":"Adaptations to Aerobic Training","zh":"有氧训练的适应"},"domain":{"en":"Exercise Science","zh":"运动科学"},"minutes":110,"source":"Essentials, 5th ed., Ch. 6 · DCO Exercise Science G, H, I","objectives":[{"en":"Explain central and peripheral endurance adaptations and their effect on VO2max, threshold, and economy.","zh":"解释中枢与外周耐力适应及其对 VO2max、阈值和经济性的影响。"},{"en":"Predict acute and chronic responses across training status, environment, and detraining.","zh":"根据训练状态、环境和停训预测急性与长期反应。"}],"sections":[{"id":"central","title":{"en":"Central cardiovascular adaptations","zh":"中枢心血管适应"},"explanation":["Endurance training expands plasma volume, increases ventricular filling, and improves stroke volume. Maximal cardiac output can rise because stroke volume is larger; at the same submaximal workload, heart rate is usually lower because the required output can be achieved with fewer beats.","Structural cardiac adaptation in trained endurance athletes is a physiological response to repeated volume loading. It must be interpreted separately from pathology and in the context of the athlete and medical evaluation."],"details":["Plasma-volume expansion can occur early and improves preload, thermoregulation, and stroke volume.","Resting and submaximal heart rate often decrease; maximal heart rate usually changes little and is influenced mainly by age and individual variation.","Blood volume and red-cell mass influence oxygen carrying capacity, but hematocrit may fall after plasma expansion despite improved total oxygen transport.","Systolic pressure at a given workload may be lower after training, while maximal systolic pressure can still be high because greater workloads are achieved."],"decision":{"en":"Compare athletes at the same absolute workload and at the same relative intensity; the physiological interpretation differs.","zh":"分别比较相同绝对负荷和相同相对强度下的运动员，生理解释不同。"},"examCue":{"en":"Submaximal HR falls after training; maximal HR is generally unchanged. Stroke volume and maximal Q rise.","zh":"训练后次最大心率下降；最大心率通常不变；每搏输出量和最大 Q 上升。"}},{"id":"peripheral","title":{"en":"Peripheral muscular adaptations","zh":"外周肌肉适应"},"explanation":["Training increases mitochondrial content, oxidative enzymes, capillary density, and the ability to transport and oxidize lactate and fat. At a given workload, ATP can be supplied with less glycolytic disturbance and lower relative recruitment of fast-fatiguing fibers.","Greater arterial-venous oxygen difference at maximal exercise reflects improved tissue extraction. Local adaptations are highly specific to trained muscles and movement modes."],"details":["More capillaries improve exchange surface and diffusion distance; more mitochondria increase oxidative processing capacity.","Muscle glycogen storage and sparing can improve, while fat oxidation at a given submaximal workload increases.","Lactate threshold shifts to a higher absolute workload through improved production-clearance balance and oxidative capacity.","Type II fibers can become more oxidative without becoming identical to type I fibers."],"decision":{"en":"Use sport-specific mode for local adaptation, then add cross-training when reduced impact or extra volume is more important than specificity.","zh":"局部适应优先使用专项方式；当降低冲击或增加容量更重要时，再加入交叉训练。"},"examCue":{"en":"A lower lactate value at the same speed after training usually indicates reduced relative metabolic stress, not reduced effort by definition.","zh":"训练后相同速度下乳酸更低通常代表相对代谢压力下降，而非必然代表没有努力。"}},{"id":"performance","title":{"en":"VO2max, threshold, and economy","zh":"VO2max、阈值与经济性"},"explanation":["Endurance performance is not determined by VO2max alone. Sustainable fraction of VO2max, movement economy, tactical pacing, substrate availability, and fatigue resistance distinguish athletes with similar maximal oxygen consumption.","VO2max follows the Fick equation, so it can improve through greater maximal cardiac output and/or oxygen extraction. Threshold measures the intensity at which metabolic disturbance rises; economy measures the oxygen cost at a given submaximal speed or power."],"details":["A high VO2max provides a large aerobic ceiling, but competition performance depends on how much of that ceiling can be sustained.","Running economy is affected by technique, stiffness, body size, footwear, terrain, fatigue, and training history.","High-intensity intervals can strongly stimulate VO2max; tempo or threshold work develops sustainable high fractions; low-intensity volume supports mitochondrial, capillary, and recovery adaptations.","Pacing that is too aggressive early increases disturbance and can lower average performance despite a faster start."],"decision":{"en":"Diagnose the limiter before prescribing: ceiling, threshold, economy, durability, or fueling may require different sessions.","zh":"处方前先诊断限制因素：有氧上限、阈值、经济性、耐久性或补给需要不同训练。"},"examCue":{"en":"VO2max, threshold, and economy are related but distinct. Improvement in one does not guarantee equal change in the others.","zh":"VO2max、阈值和经济性相关但不同；其中一项改善不保证其他项同幅变化。"}},{"id":"individual-environment","title":{"en":"Individual and environmental modifiers","zh":"个体与环境修饰因素"},"explanation":["Initial fitness, genetics, training age, sex, age, nutrition, sleep, heat, altitude, and program adherence affect adaptation. Athletes with lower starting fitness often show larger relative early gains, while advanced athletes need more precise stimulus and recovery.","Heat acclimation expands plasma volume and improves sweating responses. Altitude reduces oxygen partial pressure and can stimulate erythropoiesis over time, but training quality may fall if intensity is not adjusted."],"details":["Dehydration increases cardiovascular strain and can reduce performance in prolonged heat exposure.","At altitude, the same pace creates higher relative intensity; heart rate and ventilation rise acutely.","Female and male athletes show similar relative trainability when training and baseline are considered, though absolute values and iron risk can differ.","Low energy availability and iron deficiency can blunt endurance adaptation and require qualified referral."],"decision":{"en":"Adjust pace and recovery to environmental strain, and compare data to environment-specific baselines.","zh":"根据环境压力调整配速和恢复，并与相同环境下的基线比较数据。"},"examCue":{"en":"Heat acclimation and altitude acclimatization are different: heat emphasizes plasma and sweating; altitude emphasizes ventilation and, later, red-cell adaptation.","zh":"热适应与高原适应不同：热环境强调血浆和出汗；高原强调通气及后期红细胞适应。"}},{"id":"detraining","title":{"en":"Detraining and maintenance","zh":"停训与维持"},"explanation":["Aerobic adaptations begin to regress when training stimulus is removed. Plasma volume and stroke volume can fall relatively quickly, reducing VO2max; mitochondrial and capillary adaptations decline over longer periods. Complete bed rest causes faster loss than reduced training.","Frequency and duration can often be reduced while intensity is retained, preserving much of the adaptation for a limited period. The minimum effective maintenance dose depends on athlete level and interruption length."],"details":["A short taper is not detraining when intensity is retained and fatigue falls; performance may improve as accumulated fatigue dissipates.","Injury cross-training can preserve central capacity if sufficient muscle mass and intensity are used.","Returning after interruption requires rebuilding both metabolic capacity and tissue tolerance.","Monitoring pace or power at a standardized heart rate can reveal changes in submaximal efficiency."],"decision":{"en":"During reduced training, keep some high-quality intensity if safe, reduce volume, and reintroduce impact separately from aerobic strain.","zh":"减少训练期间，在安全时保留部分高质量强度、降低容量，并把冲击负荷与有氧压力分开重新引入。"},"examCue":{"en":"Taper reduces fatigue while preserving fitness; detraining removes enough stimulus for fitness to decline.","zh":"减量期降低疲劳并保留体能；停训则因刺激不足导致体能下降。"}}],"terms":[{"term":"VO2max","meaning":{"en":"Highest rate of oxygen consumption during severe whole-body exercise.","zh":"高强度全身运动中的最高摄氧速率。"}},{"term":"Economy","meaning":{"en":"Energy or oxygen cost at a standardized submaximal output.","zh":"标准化次最大输出下的能量或氧成本。"}},{"term":"Lactate threshold","meaning":{"en":"Intensity associated with a sustained nonlinear rise in blood lactate.","zh":"血乳酸持续非线性升高相关的强度。"}},{"term":"Cardiac drift","meaning":{"en":"Progressive HR rise with SV decline during prolonged steady work, often influenced by heat and dehydration.","zh":"长时间稳定运动中心率逐渐上升、每搏输出下降，常受热和脱水影响。"}},{"term":"Taper","meaning":{"en":"Planned reduction in training load to dissipate fatigue while retaining fitness.","zh":"为消除疲劳并保留体能而计划性降低训练负荷。"}}],"formulas":[{"name":"Fick equation","expression":"VO₂ = Q × (a-vO₂ difference)","use":{"en":"Separate central delivery and peripheral extraction adaptations.","zh":"区分中枢输送与外周提取适应。"}},{"name":"Relative VO2","expression":"mL·kg⁻¹·min⁻¹","use":{"en":"Scale oxygen consumption to body mass while recognizing size-related limitations.","zh":"按体重标准化摄氧量，同时认识体型带来的局限。"}}],"examChecklist":[{"en":"List central versus peripheral adaptations without mixing them.","zh":"准确列出中枢与外周适应。"},{"en":"Differentiate VO2max, threshold, economy, and durability.","zh":"区分 VO2max、阈值、经济性和耐久性。"},{"en":"Predict submaximal and maximal HR, SV, Q, ventilation, and lactate after training.","zh":"预测训练后次最大和最大 HR、SV、Q、通气和乳酸变化。"}],"recall":[{"prompt":{"en":"Name two central and four peripheral endurance adaptations.","zh":"说出两项中枢和四项外周耐力适应。"},"answer":{"en":"Central: greater stroke volume and maximal cardiac output. Peripheral: more capillaries, mitochondria, oxidative enzymes, and oxygen extraction; improved lactate transport and fat oxidation also qualify.","zh":"中枢：每搏输出量和最大心输出量增加。外周：毛细血管、线粒体、氧化酶和氧提取增加；乳酸转运与脂肪氧化改善也可。"}},{"prompt":{"en":"Why can performance improve with little change in VO2max?","zh":"为什么 VO2max 变化很小时表现仍可提高？"},"answer":{"en":"Threshold, economy, pacing, fatigue resistance, and fueling can improve the sustainable speed or power below the same ceiling.","zh":"阈值、经济性、配速、抗疲劳和补给可提高相同上限下可持续的速度或功率。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-7', 'en', 'Age-Related Differences and Their Implications for Resistance Training', 'Program from biological readiness rather than chronological age alone.', '{"n":7,"title":{"en":"Age-Related Differences and Their Implications for Resistance Training","zh":"年龄差异与抗阻训练"},"domain":{"en":"Exercise Science","zh":"运动科学"},"minutes":105,"source":"Essentials, 5th ed., Ch. 7 · DCO Exercise Science A-H individual differences","objectives":[{"en":"Program from biological readiness rather than chronological age alone.","zh":"依据生物准备度而不是只按实际年龄设计计划。"},{"en":"Apply safe progression, supervision, and recovery principles to youth and older adults.","zh":"把安全进阶、监督和恢复原则应用于青少年与老年人。"}],"sections":[{"id":"growth-maturation","title":{"en":"Growth, maturation, and trainability","zh":"生长、成熟与可训练性"},"explanation":["Chronological age measures time since birth; biological age reflects maturation. Peak height velocity marks the period of fastest stature growth and helps contextualize temporary changes in coordination, tissue loading, and recovery. Children of the same age may differ substantially in size, strength, and maturity.","Youth can gain strength through neural coordination, skill, and later hypertrophy. Well-designed resistance training does not inherently damage growth plates; poor supervision, excessive loading, unsafe equipment, or inappropriate progression creates risk."],"details":["Assess movement competency, training age, attention, ability to follow instructions, and emotional readiness before load progression.","During rapid growth, limb lengths and leverage change quickly; regress complexity when technique temporarily becomes inconsistent.","Prepubertal athletes often gain strength mainly through neural and technical factors, while hormonal maturation expands hypertrophy potential.","Long-term athletic development balances strength, speed, power, coordination, mobility, and enjoyment rather than early single-sport volume alone."],"decision":{"en":"Progress the child who demonstrates control, not the child who is merely older or larger.","zh":"进阶应给予能稳定控制动作的孩子，而不是仅仅年龄更大或体型更大者。"},"examCue":{"en":"Chronological age is not a readiness test. Qualified supervision and technique are central safety factors.","zh":"实际年龄不是准备度测试；合格监督和技术是安全核心。"}},{"id":"youth-programming","title":{"en":"Youth session design and safety","zh":"青少年训练设计与安全"},"explanation":["Youth resistance training begins with clear rules, appropriately sized equipment, dynamic preparation, and mastery of fundamental movement patterns. Loads should allow controlled repetition and successful instruction; maximal testing is acceptable only when technique, supervision, and protocol are appropriate.","Frequency, volume, and intensity must fit school, sport, growth, and recovery demands. The goal is a durable base of competence rather than rapid specialization."],"details":["Use one or more light-to-moderate sets initially and progress volume before maximal loading when skill is limited.","Teach landing, deceleration, pushing, pulling, squatting, hinging, bracing, carrying, jumping, and throwing.","Allow adequate recovery between sessions for the same muscle groups and monitor pain, growth-related symptoms, and enthusiasm.","External load is only one progression variable; range, speed, stability, unilateral demand, and task complexity also matter."],"decision":{"en":"When technique fails, reduce complexity or load and reteach; do not use fatigue as proof of a productive youth session.","zh":"技术失败时降低复杂度或负荷并重新教学；不要把疲劳当作青少年训练有效的证明。"},"examCue":{"en":"A supervised youth program is beneficial; the unsafe answer is unsupervised, poorly progressed, or technically uncontrolled training.","zh":"有监督的青少年计划有益；不安全的是无人监督、进阶不当或技术失控。"}},{"id":"aging","title":{"en":"Aging physiology and performance","zh":"衰老生理与表现"},"explanation":["Aging is associated with losses in muscle mass, strength, power, bone density, balance, aerobic capacity, and recovery speed, but inactivity accelerates these changes. Fast force and type II fiber function often decline disproportionately, making power and fall-prevention capacity important targets.","Older adults remain highly trainable. Resistance, power, balance, aerobic, and mobility training can improve function and independence when medical context and current ability are respected."],"details":["Sarcopenia describes age-related loss of muscle mass and function; dynapenia emphasizes loss of strength.","Reduced anabolic sensitivity increases the importance of adequate protein distribution and sufficient training stimulus.","Comorbidities, medications, blood-pressure response, joint limitations, vision, and fall risk influence exercise choice and setup.","Longer warm-up and recovery may be useful, but age alone does not justify permanently low effort or no progression."],"decision":{"en":"Train the capacity that protects independence: lower-body strength, rapid but controlled force, balance, gait, and aerobic reserve.","zh":"训练能保护独立生活的能力：下肢力量、快速但受控的发力、平衡、步态和有氧储备。"},"examCue":{"en":"Older adults need individualized progression, not automatic exclusion from heavy or power training.","zh":"老年人需要个体化进阶，而不是自动排除大重量或功率训练。"}},{"id":"older-programming","title":{"en":"Programming and monitoring older adults","zh":"老年人计划与监控"},"explanation":["Start from the athlete''s functional baseline. Stable machines, supported patterns, controlled free weights, and sit-to-stand variations can build confidence before more complex tasks. Power work uses light-to-moderate resistance with intentional acceleration and safe deceleration.","Monitor symptoms and response to medication. Stop and follow referral or emergency procedures for concerning chest pain, syncope, unusual shortness of breath, neurological symptoms, or other red flags."],"details":["Use rating of perceived exertion and repetition quality when heart-rate response is altered by medication.","Progress one major variable at a time and allow familiarization before interpreting performance tests.","Balance tasks should challenge without creating unmanageable fall risk; environmental setup and spotting matter.","Functional outcomes such as rising, stair climbing, carrying, walking speed, and confidence can be more meaningful than gym numbers alone."],"decision":{"en":"Choose the safest exercise that still trains the limiting capacity; safety is not synonymous with underloading.","zh":"选择既安全又能训练限制能力的动作；安全不等于负荷不足。"},"examCue":{"en":"Beta-blockers can blunt HR response, so use symptoms, workload, and RPE rather than a standard HR target alone.","zh":"β 受体阻滞剂可减弱心率反应，因此应结合症状、工作量和 RPE，而非只看标准心率区间。"}}],"terms":[{"term":"Chronological age","meaning":{"en":"Time since birth.","zh":"出生后的时间。"}},{"term":"Biological age","meaning":{"en":"Level of physical and physiological maturation.","zh":"身体和生理成熟水平。"}},{"term":"Peak height velocity","meaning":{"en":"Period of fastest increase in stature during adolescence.","zh":"青春期身高增长最快的时期。"}},{"term":"Sarcopenia","meaning":{"en":"Age-related decline in muscle mass and function.","zh":"与年龄相关的肌肉量和功能下降。"}},{"term":"Dynapenia","meaning":{"en":"Age-related decline in muscle strength.","zh":"与年龄相关的肌力下降。"}}],"formulas":[],"examChecklist":[{"en":"Compare chronological age, biological age, and training age.","zh":"比较实际年龄、生物年龄和训练年龄。"},{"en":"Write a safe youth progression and an older-adult power progression.","zh":"写出安全的青少年进阶和老年人功率进阶。"},{"en":"Identify when medication or symptoms require modified monitoring or referral.","zh":"识别药物或症状何时需要修改监控或转介。"}],"recall":[{"prompt":{"en":"What four readiness factors are more useful than age alone?","zh":"哪四项准备因素比年龄更有用？"},"answer":{"en":"Movement competency, training age, maturation/health status, ability to follow instruction, supervision, and recovery capacity are valid examples.","zh":"动作能力、训练年龄、成熟/健康状态、遵循指令能力、监督和恢复能力均可。"}},{"prompt":{"en":"Why is power training relevant to older adults?","zh":"为什么功率训练对老年人重要？"},"answer":{"en":"Rapid force declines strongly with age and is required for balance recovery, stair climbing, and preventing falls.","zh":"快速发力随年龄显著下降，而恢复平衡、爬楼和预防跌倒都需要它。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-8', 'en', 'Sex-Related Differences and Their Implications for Resistance Training', 'Distinguish average population differences from individual programming decisions.', '{"n":8,"title":{"en":"Sex-Related Differences and Their Implications for Resistance Training","zh":"性别差异与抗阻训练"},"domain":{"en":"Exercise Science","zh":"运动科学"},"minutes":80,"source":"Essentials, 5th ed., Ch. 8 · DCO Exercise Science individual differences","objectives":[{"en":"Distinguish average population differences from individual programming decisions.","zh":"区分群体平均差异与个体计划决策。"},{"en":"Apply evidence-based considerations for strength, body composition, menstrual health, and injury risk.","zh":"把证据应用于力量、身体成分、月经健康和伤病风险。"}],"sections":[{"id":"body-composition","title":{"en":"Body size, composition, and absolute performance","zh":"体型、身体成分与绝对表现"},"explanation":["On average, adult males have greater total and upper-body lean mass and higher absolute strength and power, influenced by body size, muscle cross-sectional area, and hormonal environment. Relative to muscle cross-sectional area, force capacity is much more similar than absolute comparisons imply.","Group averages do not define an individual athlete. Sport, training history, position, technique, motivation, and access to training create large overlap between sexes."],"details":["Upper-body absolute differences are commonly larger than lower-body differences because lean-mass distribution differs.","Allometric or body-mass scaling can change comparisons; simple strength divided by body mass is useful but not perfect.","Women may perform more repetitions at the same relative load in some exercises, but this varies by muscle group, load, and training status.","Programming from stereotypes can underload the individual and limit adaptation."],"decision":{"en":"Use the athlete''s assessment, goal, and response—not sex alone—to assign load, volume, rest, and progression.","zh":"依据运动员评估、目标和反应，而不是仅凭性别分配负荷、容量、休息和进阶。"},"examCue":{"en":"Expect similar relative trainability with appropriate training; do not confuse lower average absolute strength with lower ability to improve.","zh":"合适训练下相对可训练性相近；不要把较低平均绝对力量等同于较低改善能力。"}},{"id":"adaptation-fatigue","title":{"en":"Training adaptation and fatigue characteristics","zh":"训练适应与疲劳特点"},"explanation":["Women and men both gain strength, power, muscle, bone, and endurance from progressive training. Relative improvements are often similar when program quality and baseline are matched. Differences in substrate use, fiber distribution, and absolute muscle mass may affect fatigue and recovery in specific tasks.","Lower absolute force can produce less mechanical disruption at the same relative intensity, while greater proportional type I area in some muscles may support fatigue resistance. These are tendencies, not universal rules."],"details":["Trainability depends more on initial status, dose, adherence, energy availability, and sleep than on a single sex category.","Individual recovery should be monitored through performance and symptoms rather than assumed.","Strength and power training are essential for female athletes and should not be replaced by only low-load endurance work.","Pregnancy and postpartum training require individualized medical coordination and are separate from generic sex-based programming."],"decision":{"en":"Adjust recovery when the athlete''s actual output and symptoms indicate it; avoid fixed sex-based rest prescriptions.","zh":"根据实际输出和症状调整恢复，避免固定的性别化休息处方。"},"examCue":{"en":"The most defensible answer individualizes from measured performance rather than assuming all women are more fatigue resistant.","zh":"最可靠的答案会依据测得表现个体化，而不是假定所有女性都更抗疲劳。"}},{"id":"menstrual-health","title":{"en":"Menstrual health, energy availability, and training","zh":"月经健康、能量可用性与训练"},"explanation":["Menstrual-cycle effects on performance are individually variable and usually smaller than sleep, illness, training load, or energy availability. The coach can track symptoms and performance with consent, but should not impose blanket phase-based programming.","Menstrual dysfunction can be a sign of low energy availability or medical concern. Combined with recurrent stress injury, fatigue, or restrictive eating, it warrants referral to qualified medical and nutrition professionals."],"details":["Oral contraceptives alter the hormonal pattern and make simple natural-cycle assumptions invalid.","Iron deficiency risk is relevant because of menstrual losses and endurance demands; diagnosis and treatment are medical responsibilities.","Communication must protect privacy and avoid stigma. Ask about symptoms that affect training rather than making assumptions.","Adequate energy, carbohydrate, protein, calcium, vitamin D, and recovery support both performance and bone health."],"decision":{"en":"Use symptom-guided flexible adjustments and refer persistent dysfunction; do not diagnose or prescribe treatment.","zh":"使用症状指导的灵活调整并对持续异常进行转介；不要自行诊断或治疗。"},"examCue":{"en":"Amenorrhea is not a normal or desirable training adaptation; recognize and refer.","zh":"闭经不是正常或理想的训练适应，应识别并转介。"}},{"id":"injury-context","title":{"en":"Injury risk and neuromuscular preparation","zh":"伤病风险与神经肌肉准备"},"explanation":["Some female athlete populations show higher noncontact ACL injury rates, but risk is multifactorial: exposure, anatomy, hormones, strength, landing and cutting strategy, fatigue, sport context, and previous injury all contribute. Screening does not perfectly predict an individual injury.","Neuromuscular programs that include strength, landing, deceleration, plyometrics, balance, and change-of-direction technique can reduce risk when performed consistently."],"details":["Hip and hamstring strength, trunk control, braking strategy, and progressive cutting exposure are trainable.","Risk reduction is not achieved by one corrective exercise or one visual screen.","Programs should begin before the competitive season and continue with a maintenance dose.","The coach manages modifiable capacity and exposure while collaborating with the medical team after injury."],"decision":{"en":"Build robust movement options and progressive exposure instead of labeling an athlete as ''high risk'' from one test.","zh":"通过多样动作能力和渐进暴露建立稳健性，而不是凭一次测试给运动员贴“高风险”标签。"},"examCue":{"en":"Choose multifactorial, sustained neuromuscular training over a single muscle or single-angle explanation.","zh":"选择多因素、持续性的神经肌肉训练，而不是单一肌肉或单一角度解释。"}}],"terms":[{"term":"Absolute strength","meaning":{"en":"Total external force or load without scaling to body size.","zh":"未按体型标准化的总外力或负荷。"}},{"term":"Relative strength","meaning":{"en":"Strength scaled to body mass or another size measure.","zh":"按体重或其他体型指标标准化的力量。"}},{"term":"Amenorrhea","meaning":{"en":"Absence of menstrual periods; persistent cases require medical evaluation.","zh":"月经缺失；持续情况需要医疗评估。"}},{"term":"Low energy availability","meaning":{"en":"Insufficient dietary energy remaining for physiological function after exercise expenditure.","zh":"扣除运动消耗后，留给生理功能的膳食能量不足。"}}],"formulas":[{"name":"Simple relative strength","expression":"1RM ÷ body mass","use":{"en":"Compare performance across body sizes while recognizing that nonlinear scaling may be better for research.","zh":"跨体型比较表现，同时认识研究中非线性缩放可能更合适。"},"example":"120 kg squat ÷ 60 kg = 2.0× body mass"}],"examChecklist":[{"en":"Separate absolute differences from relative adaptation.","zh":"区分绝对差异与相对适应。"},{"en":"Recognize low-energy-availability and menstrual-health referral signals.","zh":"识别低能量可用性和月经健康转介信号。"},{"en":"Describe a multifactorial lower-limb injury-risk-reduction program.","zh":"描述多因素下肢伤病风险降低计划。"}],"recall":[{"prompt":{"en":"Why should programs not be assigned from sex alone?","zh":"为什么不能只按性别分配计划？"},"answer":{"en":"Individual training status, body size, skill, sport demands, goals, and response show substantial overlap and determine the needed dose.","zh":"个体训练状态、体型、技能、专项需求、目标和反应存在大量重叠，并决定所需剂量。"}},{"prompt":{"en":"What cluster should trigger RED-S or low-energy-availability referral?","zh":"哪些信号组合应触发 RED-S 或低能量可用性转介？"},"answer":{"en":"Persistent fatigue or performance decline with restrictive intake, menstrual dysfunction, recurrent stress injury, or other health changes.","zh":"持续疲劳或表现下降，同时出现限制性饮食、月经异常、反复应力性损伤或其他健康变化。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-9', 'en', 'Psychological Foundations of Performance', 'Apply motivation, arousal, attention, confidence, imagery, and self-talk to coaching.', '{"n":9,"title":{"en":"Psychological Foundations of Performance","zh":"运动表现的心理学基础"},"domain":{"en":"Sport Psychology","zh":"运动心理学"},"minutes":135,"source":"Essentials, 5th ed., Ch. 9 · DCO Sport Psychology A-B · DCO Program Implementation A2","objectives":[{"en":"Apply motivation, arousal, attention, confidence, imagery, and self-talk to coaching.","zh":"把动机、唤醒、注意、信心、表象和自我对话应用于教练实践。"},{"en":"Recognize distress, injury responses, and when referral is required.","zh":"识别心理困扰、伤后反应和何时需要转介。"},{"en":"Use motor-learning principles to teach and retain skill.","zh":"使用运动学习原则教授并保持技能。"}],"sections":[{"id":"arousal","title":{"en":"Arousal, anxiety, stress, and the ideal state","zh":"唤醒、焦虑、压力与理想状态"},"explanation":["Arousal is general activation; anxiety includes cognitive worry and somatic symptoms; stress arises when perceived demands exceed perceived resources. Performance depends on task, experience, interpretation, and the athlete''s preferred state rather than one universally optimal arousal level.","Simple tasks and gross power actions may tolerate higher arousal, while fine or unfamiliar skills often require a narrower, calmer state. Catastrophe models emphasize that high cognitive anxiety can make excessive physiological arousal especially disruptive."],"details":["Under-arousal may present as flat energy and slow initiation; over-arousal may narrow attention, speed decisions excessively, and increase unnecessary tension.","Breathing, routines, cue words, muscle relaxation, and attentional shifts can downregulate arousal.","Music, movement, energizing self-talk, and competitive cues can increase activation when appropriate.","The athlete should practice regulation during training so the strategy is familiar under competition pressure."],"decision":{"en":"Identify whether activation is too low, useful, or too high for this athlete and task before selecting a strategy.","zh":"先判断对该运动员和任务而言唤醒是过低、合适还是过高，再选择策略。"},"examCue":{"en":"The best answer regulates arousal toward an individual task-specific zone; it does not always reduce arousal.","zh":"最佳答案把唤醒调向个体化、任务特定区间，并非总是降低唤醒。"}},{"id":"motivation","title":{"en":"Motivation, goals, confidence, and reinforcement","zh":"动机、目标、信心与强化"},"explanation":["Self-determination theory emphasizes autonomy, competence, and relatedness. Goal-orientation theory distinguishes mastery or task focus from ego or comparison focus. A mastery climate rewards learning, effort, problem solving, and progress, which supports persistence when outcomes are uncertain.","Outcome goals give direction, performance goals define measurable standards, and process goals specify controllable actions. The strongest plan links all three while daily coaching emphasizes process."],"details":["Confidence grows from mastery experiences, credible feedback, modeling, preparation, and interpretation of physiological state.","Positive reinforcement increases the likelihood of a behavior by adding a valued consequence; negative reinforcement increases behavior by removing an aversive condition. Punishment aims to reduce behavior.","Feedback should be specific, truthful, and tied to controllable behavior rather than empty praise.","Athlete choice can support autonomy without abandoning structure: offer bounded options that both serve the session goal."],"decision":{"en":"Translate ''win'' into today''s controllable behaviors and give feedback on the behavior, timing, and result.","zh":"把“赢”转化为今天可控的行为，并针对行为、时机和结果提供反馈。"},"examCue":{"en":"Negative reinforcement is not punishment; it increases behavior by removing something aversive.","zh":"负强化不是惩罚；它通过移除厌恶刺激来增加行为。"}},{"id":"attention-skills","title":{"en":"Attention, imagery, self-talk, and routines","zh":"注意、表象、自我对话与流程"},"explanation":["Attention can be broad or narrow and internal or external. Athletes scan broadly to assess a situation, then narrow attention to the most relevant cue. Under pressure, attention may become too narrow or shift toward threat and internal monitoring.","Imagery is most useful when vivid, controllable, and functionally similar to performance. Self-talk should be short, believable, and linked to a decision or action. Preperformance routines stabilize attention and reduce unnecessary choice."],"details":["External-focus cues direct attention to the movement effect and often support automatic execution; internal cues can still be useful for rehabilitation or body awareness.","Instructional self-talk guides technique; motivational self-talk regulates effort and confidence.","Imagery can include visual, kinesthetic, auditory, and emotional features and should rehearse coping as well as ideal performance.","Routines should be practiced under increasing pressure and include a reset step after errors."],"decision":{"en":"Give one cue that directs attention to the most important movement effect, then let the athlete execute before adding information.","zh":"给出一个指向最重要动作效果的提示，然后让运动员执行，再决定是否增加信息。"},"examCue":{"en":"''Push the floor away'' is external focus; ''extend your knees'' is internal focus.","zh":"“把地面推开”是外部注意；“伸膝”是内部注意。"}},{"id":"mental-health","title":{"en":"Mental health, eating concerns, injury, and referral","zh":"心理健康、进食问题、伤病与转介"},"explanation":["The strength coach observes, listens, supports, follows organizational policy, and refers. The coach does not diagnose or provide psychotherapy. Useful warning signs include persistent changes in affect, behavior, and cognition; functional impairment; social withdrawal; sleep or appetite change; hopeless statements; and concerning eating or exercise patterns.","Injury may threaten identity, belonging, control, and confidence. A supportive coach maintains appropriate team connection, offers realistic controllable goals, and coordinates with the interdisciplinary team."],"details":["Use a private, nonjudgmental conversation: describe observations, express concern, listen, and connect the athlete with the designated resource.","Imminent self-harm, harm to others, or inability to maintain safety requires immediate emergency or crisis protocol.","Disordered eating and eating disorders are not diagnosed by the coach; recognize patterns and refer.","Confidentiality has limits when safety, law, or policy requires disclosure. Explain those limits honestly."],"decision":{"en":"If safety is immediate, stay with the athlete and activate the crisis procedure; do not promise secrecy or manage the situation alone.","zh":"若存在即时安全风险，陪伴运动员并启动危机流程；不要承诺绝对保密，也不要独自处理。"},"examCue":{"en":"Persistent ABC changes plus impaired function = supportive conversation and referral, not diagnosis.","zh":"持续 ABC 变化并影响功能 = 支持性沟通与转介，而不是诊断。"}},{"id":"motor-learning","title":{"en":"Motor learning and feedback","zh":"运动学习与反馈"},"explanation":["Motor performance is temporary execution; motor learning is a relatively permanent change in capability inferred from retention and transfer. Early cognitive learning uses more instruction; associative learning refines errors; autonomous performance requires less conscious control.","Blocked practice repeats one skill and helps initial performance. Random or variable practice is more difficult during training but can improve retention and transfer once a basic pattern exists."],"details":["Knowledge of results describes the outcome; knowledge of performance describes the movement pattern.","Concurrent feedback occurs during movement; terminal feedback follows it. Excessive immediate feedback can create dependency.","Bandwidth feedback is given when error exceeds an acceptable range; summary feedback covers several trials.","Demonstration, simple cues, constraints, and representative practice conditions should match the learner''s stage."],"decision":{"en":"Provide enough feedback for safety and understanding, then fade frequency so the athlete learns to detect and correct errors.","zh":"提供足够反馈确保安全和理解，随后逐步降低频率，让运动员学会自行发现和纠正错误。"},"examCue":{"en":"A better practice-session score does not always mean better learning; use delayed retention and transfer.","zh":"练习当下表现更好不一定代表学习更好；应看延迟保持与迁移。"}}],"terms":[{"term":"Arousal","meaning":{"en":"General physiological and psychological activation.","zh":"一般生理与心理激活水平。"}},{"term":"Self-determination","meaning":{"en":"Motivation supported by autonomy, competence, and relatedness.","zh":"由自主、胜任和关系感支持的动机。"}},{"term":"Process goal","meaning":{"en":"A controllable action target used during execution.","zh":"执行过程中可控的行动目标。"}},{"term":"Knowledge of results","meaning":{"en":"Feedback about the outcome of a movement.","zh":"关于动作结果的反馈。"}},{"term":"Retention","meaning":{"en":"Ability to perform the learned skill after a delay.","zh":"延迟后执行已学技能的能力。"}}],"formulas":[],"examChecklist":[{"en":"Select an arousal strategy from the athlete and task, not a universal rule.","zh":"根据运动员与任务选择唤醒策略，而非套用统一规则。"},{"en":"Distinguish outcome, performance, and process goals.","zh":"区分结果、表现和过程目标。"},{"en":"Use ABC observations, scope of practice, and emergency referral correctly.","zh":"正确使用 ABC 观察、执业范围和紧急转介。"},{"en":"Differentiate temporary performance from retained motor learning.","zh":"区分临时表现与保持下来的运动学习。"}],"recall":[{"prompt":{"en":"Convert an outcome goal into a process goal.","zh":"把一个结果目标改写为过程目标。"},"answer":{"en":"Replace ''win the race'' with a controllable action such as ''hold planned first-lap pace and keep shoulders relaxed.''","zh":"把“赢得比赛”改为“首圈保持计划配速并放松肩部”等可控行动。"}},{"prompt":{"en":"What is the first duty when an athlete expresses imminent self-harm intent?","zh":"运动员表达即刻自伤意图时首要职责是什么？"},"answer":{"en":"Protect immediate safety, remain with the athlete, and activate the organization''s crisis or emergency protocol.","zh":"保障即时安全、陪伴运动员，并启动组织的危机或紧急流程。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-10', 'en', 'Basic Nutritional Factors Affecting Health', 'Explain energy balance, macronutrients, micronutrients, hydration, and scope of practice.', '{"n":10,"title":{"en":"Basic Nutritional Factors Affecting Health","zh":"影响健康的基础营养因素"},"domain":{"en":"Nutrition","zh":"营养"},"minutes":130,"source":"Essentials, 5th ed., Ch. 10 · DCO Nutrition A","objectives":[{"en":"Explain energy balance, macronutrients, micronutrients, hydration, and scope of practice.","zh":"解释能量平衡、宏量与微量营养素、补水和执业范围。"},{"en":"Calculate practical intake and sweat-loss estimates without diagnosing or prescribing medical nutrition therapy.","zh":"计算实用摄入和汗液损失，同时不越界进行诊断或医疗营养治疗。"}],"sections":[{"id":"scope-energy","title":{"en":"Scope of practice and energy balance","zh":"执业范围与能量平衡"},"explanation":["A strength coach can provide general evidence-based education, reinforce team nutrition plans, identify red flags, and refer. Individual medical nutrition therapy, eating-disorder treatment, and diagnosis belong to qualified dietitians and medical professionals.","Energy balance compares energy intake with expenditure. Body-mass change reflects the long-term balance, but daily scale change is heavily influenced by fluid, glycogen, gut content, and measurement conditions."],"details":["Energy expenditure includes resting metabolism, thermic effect of food, planned exercise, and nonexercise activity.","Low energy availability can impair endocrine, bone, immune, cardiovascular, reproductive, and performance function even before dramatic weight loss.","Weight goals should be gradual and aligned with performance, health, season timing, and athlete consent.","Refer unexplained weight change, restrictive behavior, recurrent stress injury, gastrointestinal disease, or complex medical conditions."],"decision":{"en":"Provide general plate, timing, and hydration education; refer individualized therapeutic diets or suspected pathology.","zh":"提供一般餐盘、时机和补水教育；个体治疗饮食或疑似病理应转介。"},"examCue":{"en":"Choose referral when the stem includes diagnosis, disease treatment, eating disorder, or persistent RED-S signs.","zh":"题干涉及诊断、疾病治疗、进食障碍或持续 RED-S 信号时选择转介。"}},{"id":"carbohydrate","title":{"en":"Carbohydrate and training fuel","zh":"碳水化合物与训练燃料"},"explanation":["Carbohydrate is stored mainly as muscle and liver glycogen and circulates as blood glucose. It supports high-intensity exercise because it can provide ATP rapidly, and adequate availability helps preserve training quality and skill under fatigue.","Needs scale with training volume, intensity, body size, and schedule. Athletes do not need the same intake every day; periodize carbohydrate upward around demanding sessions and downward when workload is lighter without creating chronic low energy availability."],"details":["Muscle glycogen serves the working muscle; liver glycogen helps maintain blood glucose.","Fiber supports health and satiety, but high fiber immediately before competition can increase gastrointestinal symptoms.","Glycemic index describes relative blood-glucose response under standardized conditions; mixed meals and timing change the response.","Very low carbohydrate availability can reduce high-intensity capacity and total training quality even when fat oxidation rises."],"decision":{"en":"Place familiar, digestible carbohydrate before and around high-output work; adjust total intake to the athlete''s actual workload.","zh":"在高输出训练前后安排熟悉、易消化的碳水，并按实际工作量调整总摄入。"},"examCue":{"en":"High-intensity work relies heavily on carbohydrate; greater fat use is not automatically better performance.","zh":"高强度运动高度依赖碳水；脂肪利用比例更高不自动等于表现更好。"}},{"id":"protein-fat","title":{"en":"Protein, fat, and tissue remodeling","zh":"蛋白质、脂肪与组织重塑"},"explanation":["Protein supplies amino acids for muscle, enzymes, transporters, immune proteins, and other tissue. Training and protein feeding stimulate remodeling; total daily intake, distribution, protein quality, and energy availability all matter.","Fat supplies essential fatty acids, supports cell membranes and steroid synthesis, aids absorption of vitamins A, D, E, and K, and provides dense energy. Chronically very low fat intake can compromise health and diet quality."],"details":["Protein should be distributed across meals with high-quality sources rather than concentrated in one feeding.","Leucine is an important signal, but complete essential amino-acid availability is required for building tissue.","Unsaturated fats should make up much of intake; trans-fat intake should be minimized.","Protein can contribute to energy during prolonged or low-glycogen exercise, but using it as a major fuel is not the goal."],"decision":{"en":"Set total energy first, then distribute sufficient protein across the day and retain adequate dietary fat.","zh":"先保证总能量，再把足量蛋白质分布到全天，并保留充足膳食脂肪。"},"examCue":{"en":"Protein supports remodeling but does not replace carbohydrate for high-intensity fuel or energy balance for mass gain.","zh":"蛋白质支持重塑，但不能代替高强度所需碳水，也不能代替增重所需能量平衡。"}},{"id":"micronutrients","title":{"en":"Vitamins, minerals, and high-risk deficiencies","zh":"维生素、矿物质与高风险缺乏"},"explanation":["Micronutrients regulate energy metabolism, oxygen transport, bone turnover, immune function, and tissue repair. More is not always better: supplements above requirements may have no benefit and can be toxic or interact with medication.","Athletes at higher risk include those with restricted energy intake, limited food variety, heavy menstrual losses, gastrointestinal conditions, low sun exposure, or high sweat losses."],"details":["Iron is essential for hemoglobin and oxidative enzymes; deficiency can impair endurance and cognition. Blood testing and treatment require medical oversight.","Calcium and vitamin D support bone health and muscle function; low energy availability increases bone risk.","Sodium is the major extracellular electrolyte and is lost in sweat; potassium is predominantly intracellular.","Antioxidant nutrients from food support health, while chronic megadoses may interfere with some training signaling and create risk."],"decision":{"en":"Use food-first variety and refer suspected deficiency for testing rather than guessing with high-dose supplements.","zh":"优先多样化食物；疑似缺乏应转介检测，而不是猜测性使用大剂量补剂。"},"examCue":{"en":"Iron-deficiency diagnosis and supplementation are not the strength coach''s role.","zh":"缺铁诊断和补充治疗不属于体能教练职责。"}},{"id":"hydration","title":{"en":"Fluid, electrolytes, and sweat-rate planning","zh":"液体、电解质与出汗率计划"},"explanation":["Fluid needs vary with body size, climate, clothing, acclimation, intensity, and individual sweat rate. Both dehydration and excessive hypotonic fluid intake can be dangerous. The goal is a practical plan that limits performance-reducing dehydration without causing net weight gain from overdrinking.","Pre/post body mass, fluid consumed, and urine produced can estimate sweat loss. Repeated measurements under similar conditions are more useful than one generic recommendation."],"details":["Heat and humidity increase thermoregulatory strain; acclimation improves plasma volume and sweating response.","Sodium replacement becomes more relevant with long sessions, high sweat rates, salty sweat, or repeated same-day exercise.","Urine color is a rough field indicator and is influenced by supplements, food, and first-morning concentration.","Hyponatremia risk rises when fluid intake exceeds losses, especially during long events without appropriate sodium strategy."],"decision":{"en":"Build an individualized sweat-rate range, practice it in training, and avoid both large deficits and weight gain during exercise.","zh":"建立个体出汗率范围，在训练中演练，并避免大幅脱水或运动中体重增加。"},"examCue":{"en":"Body-mass loss plus fluid consumed minus urine approximates sweat loss; keep units consistent.","zh":"体重下降加摄入液体再减尿量可近似汗液损失；注意统一单位。"}}],"terms":[{"term":"Energy availability","meaning":{"en":"Dietary energy remaining for physiological function after exercise expenditure.","zh":"扣除运动消耗后可供生理功能使用的膳食能量。"}},{"term":"Glycogen","meaning":{"en":"Stored carbohydrate in muscle and liver.","zh":"储存在肌肉和肝脏中的碳水。"}},{"term":"Essential amino acid","meaning":{"en":"An amino acid that must be supplied by the diet.","zh":"必须由膳食提供的氨基酸。"}},{"term":"Hyponatremia","meaning":{"en":"Abnormally low blood sodium concentration.","zh":"血钠浓度异常降低。"}}],"formulas":[{"name":"Sweat loss","expression":"pre mass − post mass + fluid intake − urine","use":{"en":"Estimate fluid lost during a session, treating 1 kg mass change as about 1 L water.","zh":"估算一次训练的液体损失，1 kg 体重变化约等于 1 L 水。"},"example":"80.0 − 78.8 kg + 0.5 L − 0 L ≈ 1.7 L"},{"name":"Sweat rate","expression":"sweat loss ÷ exercise hours","use":{"en":"Create an individualized hourly hydration plan.","zh":"制定个体化每小时补水计划。"},"example":"1.7 L ÷ 1.5 h ≈ 1.13 L/h"},{"name":"Protein target calculation","expression":"body mass × g·kg⁻¹·day⁻¹","use":{"en":"Translate a body-mass-relative target into daily grams.","zh":"把按体重目标换算为每日克数。"},"example":"70 kg × 1.6 g/kg = 112 g/day"}],"examChecklist":[{"en":"State what nutrition guidance is inside versus outside coaching scope.","zh":"说明哪些营养指导在教练职责内，哪些越界。"},{"en":"Explain carbohydrate, protein, and fat roles without replacing one with another.","zh":"解释碳水、蛋白质和脂肪角色，避免互相替代。"},{"en":"Calculate sweat loss, sweat rate, and body-mass-relative intake.","zh":"计算汗液损失、出汗率和按体重摄入。"}],"recall":[{"prompt":{"en":"Why can body mass change overnight without meaningful fat change?","zh":"为什么一夜体重变化不代表有意义的脂肪变化？"},"answer":{"en":"Fluid, glycogen and bound water, sodium, gut content, and measurement timing can shift rapidly.","zh":"液体、糖原及结合水、钠、肠内容物和测量时间都会快速变化。"}},{"prompt":{"en":"When does a nutrition question require referral?","zh":"营养问题何时需要转介？"},"answer":{"en":"When it involves diagnosis, disease treatment, eating disorder, persistent RED-S signs, complex supplementation, or individualized medical nutrition therapy.","zh":"涉及诊断、疾病治疗、进食障碍、持续 RED-S 信号、复杂补剂或个体医疗营养治疗时。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-11', 'en', 'Nutrition Strategies for Maximizing Performance', 'Plan pre-, during-, and postexercise fueling by event demand and gastrointestinal tolerance.', '{"n":11,"title":{"en":"Nutrition Strategies for Maximizing Performance","zh":"最大化表现的营养策略"},"domain":{"en":"Nutrition","zh":"营养"},"minutes":120,"source":"Essentials, 5th ed., Ch. 11 · DCO Nutrition A","objectives":[{"en":"Plan pre-, during-, and postexercise fueling by event demand and gastrointestinal tolerance.","zh":"根据项目需求和胃肠耐受安排赛前、赛中与赛后补给。"},{"en":"Manage body-composition goals while recognizing RED-S and eating-disorder risk.","zh":"管理身体成分目标，同时识别 RED-S 与进食障碍风险。"}],"sections":[{"id":"pre-event","title":{"en":"Preexercise fueling and hydration","zh":"运动前补给与补水"},"explanation":["The preevent meal aims to start with adequate glycogen, hydration, and comfort. Timing, amount, and food choice depend on time available, event duration and intensity, body size, and individual gastrointestinal history.","As the event approaches, meals generally become smaller, more carbohydrate-focused, and lower in fat and fiber. Novel foods, large meals, and untested supplement doses increase risk without guaranteed benefit."],"details":["A meal several hours before exercise can be more complete; a snack within an hour should be familiar and easily digested.","Prehydration should begin early enough to absorb fluid and permit urination rather than forcing a large bolus immediately before activity.","Caffeine strategy must account for habitual use, timing, sleep, anxiety, rules, and side effects.","High-intensity morning events may require carbohydrate planning the night before because there is little time for a large breakfast."],"decision":{"en":"Practice the exact competition meal and timing during a comparable training session.","zh":"在相似训练课中提前演练完全相同的比赛餐与时间安排。"},"examCue":{"en":"Close to competition, choose familiar, carbohydrate-rich, lower-fat and lower-fiber options when GI distress is a concern.","zh":"临近比赛且担心胃肠不适时，选择熟悉、富含碳水、较低脂和低纤维食物。"}},{"id":"during-event","title":{"en":"During-exercise carbohydrate, fluid, and sodium","zh":"运动中碳水、液体与钠"},"explanation":["During-event fueling matters most as duration, intensity, heat, and starting glycogen demands increase. Carbohydrate supports blood glucose and high rates of oxidation; fluids manage cardiovascular and thermal strain; sodium helps replace sweat losses and retain fluid.","The gut is trainable. Gradual practice with planned concentrations, volumes, and product combinations improves tolerance. More intake is not always better if absorption and gastric emptying cannot keep pace."],"details":["Short sessions may need only water or no intake; prolonged or repeated high-output work benefits more from carbohydrate and electrolyte planning.","Multiple transportable carbohydrates can support higher oxidation rates in long events, but they must be practiced.","Concentrated carbohydrate solutions, dehydration, heat, and high intensity can slow gastric emptying and increase symptoms.","Team-sport opportunities are intermittent, so use breaks, substitutions, and halftime strategically."],"decision":{"en":"Start with event demands and sweat rate, then choose a plan the athlete can actually tolerate and execute.","zh":"先看项目需求和出汗率，再选择运动员真正能耐受并执行的方案。"},"examCue":{"en":"A long hot event requires fluid and sodium context; a brief power event does not need aggressive during-event feeding.","zh":"长时间高温项目需要考虑液体和钠；短时功率项目不需要激进的运动中进食。"}},{"id":"recovery","title":{"en":"Postexercise recovery and repeated sessions","zh":"运动后恢复与重复训练"},"explanation":["Recovery nutrition restores glycogen and fluid, supplies amino acids for remodeling, and supports the next session. Urgency depends on the time until the next demanding bout. When recovery time is long, total daily intake matters most; when sessions are close, early intake becomes more important.","A mixed meal can meet carbohydrate, protein, micronutrient, and fluid goals. Supplements are convenient tools, not inherently superior to food."],"details":["Carbohydrate intake soon after depletion accelerates glycogen restoration when another session occurs within hours.","High-quality protein after training supports muscle-protein synthesis; distributing protein across the day adds repeated opportunities.","Rehydration often requires replacing more than the measured deficit because urine losses continue; sodium supports retention.","Alcohol can impair rehydration, sleep, judgment, and muscle recovery and adds energy without supporting performance."],"decision":{"en":"Prioritize fast recovery only when the schedule demands it; otherwise build a sustainable daily pattern.","zh":"只有训练日程要求时才强调快速恢复；否则建立可持续的全天饮食模式。"},"examCue":{"en":"Short turnaround elevates the importance of immediate carbohydrate, protein, fluid, and sodium.","zh":"恢复窗口很短时，即时碳水、蛋白质、液体和钠更重要。"}},{"id":"body-composition","title":{"en":"Body-composition change without sacrificing performance","zh":"不牺牲表现的身体成分调整"},"explanation":["Fat loss requires a sustained energy deficit; mass gain requires a surplus. The size and speed of change affect training quality, lean-mass retention or gain, mood, sleep, and adherence. Performance goals and competition schedule should determine timing.","Use trends from standardized measures rather than daily noise. Combine body mass with performance, circumference or composition measures, menstrual health, recovery, and athlete wellbeing."],"details":["Moderate deficits, adequate protein, and resistance training help preserve lean mass during fat loss.","A very large surplus accelerates mass gain but increases fat gain; muscle gain is limited by training status and adaptation rate.","Weight-class athletes need planned strategies with qualified professionals; severe dehydration and rapid weight loss create risk.","Fad diets may change short-term scale weight through glycogen and water before meaningful fat change occurs."],"decision":{"en":"Choose the slowest rate that meets the performance timeline, and stop or refer when health or performance deteriorates.","zh":"选择满足表现时间线的最慢变化速度；健康或表现恶化时停止并转介。"},"examCue":{"en":"Evidence-based body-composition change is gradual, monitored, and paired with adequate protein and resistance training.","zh":"循证身体成分调整应渐进、受监控，并配合充足蛋白质和抗阻训练。"}},{"id":"reds-eating","title":{"en":"RED-S, disordered eating, and referral","zh":"RED-S、饮食紊乱与转介"},"explanation":["Relative Energy Deficiency in Sport describes impaired physiological and performance function caused by problematic low energy availability. It can affect athletes of any sex and may involve bone, reproductive, endocrine, immune, cardiovascular, gastrointestinal, hematological, psychological, and performance consequences.","Disordered eating exists on a spectrum; an eating disorder is a clinical condition. Coaches should avoid moralizing food, public body comments, punitive exercise, and uncontrolled weigh-ins."],"details":["Warning signs include restrictive rules, rapid weight change, recurrent stress injury, menstrual dysfunction, low libido, fatigue, cold intolerance, mood change, and declining performance.","Body mass can remain stable despite low energy availability because the body adapts; absence of low weight does not rule out risk.","Screening, diagnosis, and treatment require an interdisciplinary team with medical and nutrition expertise.","Immediate medical instability or severe psychological risk requires urgent action under policy."],"decision":{"en":"Document objective observations, communicate privately, and refer through the established pathway.","zh":"记录客观观察，私下沟通，并通过既定流程转介。"},"examCue":{"en":"RED-S affects all sexes and many systems; it is not limited to the historical female-athlete triad.","zh":"RED-S 可影响所有性别和多系统，不限于传统女性运动员三联征。"}}],"terms":[{"term":"Glycogen restoration","meaning":{"en":"Replenishment of carbohydrate stored in muscle and liver after exercise.","zh":"运动后补充肌肉和肝脏糖原。"}},{"term":"Gut training","meaning":{"en":"Repeated practice of competition fueling to improve tolerance and absorption.","zh":"反复演练比赛补给以改善耐受和吸收。"}},{"term":"RED-S","meaning":{"en":"Multisystem health and performance impairment related to low energy availability.","zh":"与低能量可用性相关的多系统健康与表现损害。"}},{"term":"Disordered eating","meaning":{"en":"Problematic eating attitudes or behaviors that may not meet diagnostic criteria.","zh":"可能未达到诊断标准但存在问题的饮食态度或行为。"}}],"formulas":[{"name":"Percent body-mass change","expression":"(pre mass − post mass) ÷ pre mass × 100","use":{"en":"Estimate hydration-related mass loss during a session.","zh":"估算一次训练中与水合相关的体重损失。"},"example":"(80.0 − 78.8) ÷ 80.0 × 100 = 1.5%"},{"name":"Energy-balance direction","expression":"intake − expenditure","use":{"en":"Understand long-term direction while avoiding precise prediction from one day.","zh":"理解长期变化方向，避免用单日数据精确预测。"}}],"examChecklist":[{"en":"Build a pre/during/post plan for short power, team sport, and long endurance events.","zh":"为短时功率、团队运动和长耐力项目分别制定赛前中后方案。"},{"en":"Explain when immediate recovery intake matters most.","zh":"解释即时恢复摄入何时最重要。"},{"en":"Recognize RED-S and eating-disorder signals and use referral boundaries.","zh":"识别 RED-S 与进食障碍信号并遵守转介边界。"}],"recall":[{"prompt":{"en":"What changes when the next hard session is in four hours rather than tomorrow?","zh":"下一次高强度训练在四小时后而非明天时，策略如何变化？"},"answer":{"en":"Earlier carbohydrate, protein, fluid, and sodium replacement becomes more urgent because there is less time for total daily intake to restore readiness.","zh":"由于恢复时间更短，更需要尽早补充碳水、蛋白质、液体和钠。"}},{"prompt":{"en":"Why does stable body mass not rule out RED-S?","zh":"为什么体重稳定不能排除 RED-S？"},"answer":{"en":"The body can reduce physiological expenditure and function to defend mass while health and performance deteriorate.","zh":"身体可降低生理消耗和功能以维持体重，同时健康与表现仍在恶化。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-12', 'en', 'Performance-Enhancing Substances and Methods', 'Evaluate efficacy, safety, legality, product quality, and scope for common supplements and drugs.', '{"n":12,"title":{"en":"Performance-Enhancing Substances and Methods","zh":"提升表现的物质与方法"},"domain":{"en":"Nutrition","zh":"营养"},"minutes":115,"source":"Essentials, 5th ed., Ch. 12 · DCO Nutrition B","objectives":[{"en":"Evaluate efficacy, safety, legality, product quality, and scope for common supplements and drugs.","zh":"评估常见补剂与药物的有效性、安全性、合法性、产品质量和职责范围。"},{"en":"Use a repeatable decision framework rather than marketing claims.","zh":"使用可重复的决策框架，而非依据营销宣传。"}],"sections":[{"id":"framework","title":{"en":"Evidence, regulation, and third-party testing","zh":"证据、监管与第三方检测"},"explanation":["Dietary supplements are not evaluated like approved medicines before sale in many jurisdictions. Label accuracy, contamination, adulteration, and dose can vary. The athlete remains responsible for banned substances under strict-liability rules.","Evaluate five questions: Is the proposed mechanism plausible? Do controlled studies show a meaningful effect in a similar population and task? Is the effective dose known? What are the risks and interactions? Is the product independently tested and permitted by the governing body?"],"details":["A statistically significant effect may be too small to matter in practice; compare the effect with normal performance variability.","Proprietary blends hide ingredient doses and make evaluation difficult.","Third-party certification reduces, but cannot eliminate, contamination risk; it does not prove efficacy.","Natural, clinically tested, or research-backed are marketing phrases unless the exact product, dose, and study are verified."],"decision":{"en":"Food, sleep, training, and medical issues come first. Refer supplement decisions through the sport''s qualified medical/nutrition process.","zh":"先解决饮食、睡眠、训练和医疗问题；补剂决策应通过专项合格医疗/营养流程。"},"examCue":{"en":"Third-party testing addresses product quality and banned-substance risk; it does not guarantee performance benefit.","zh":"第三方检测解决产品质量和违禁风险，不保证表现收益。"}},{"id":"supported","title":{"en":"Common evidence-supported ergogenic aids","zh":"常见有证据支持的助力补剂"},"explanation":["Creatine monohydrate increases muscle creatine availability and can improve repeated high-intensity work, strength, training volume, and lean-mass gain over time. Caffeine can improve alertness, endurance, repeated sprint, and perceived effort, but response and side effects vary.","Beta-alanine increases muscle carnosine and can support high-intensity efforts where acid-base disturbance is important. Sodium bicarbonate buffers extracellular acidity but commonly causes gastrointestinal distress. Nitrate may improve economy or endurance in some contexts."],"details":["Creatine benefit accumulates through regular intake; loading accelerates saturation but is not the only approach. Early mass gain is often water within muscle.","Caffeine timing and dose must account for sleep, anxiety, habituation, medication, and competition time.","Beta-alanine can cause tingling; divided doses improve tolerance, and benefit requires chronic loading rather than a single acute dose.","Bicarbonate and nitrate responses depend on event demands and individual tolerance; training trials are essential."],"decision":{"en":"Match the supplement to a limiting mechanism and event, then test tolerability in training—not on competition day.","zh":"把补剂与限制机制和项目匹配，并在训练中测试耐受，而不是比赛当天首次使用。"},"examCue":{"en":"Creatine supports repeated high-intensity capacity; beta-alanine is chronic buffering support; caffeine is an acute stimulant.","zh":"肌酸支持重复高强度能力；β-丙氨酸提供长期缓冲支持；咖啡因是急性兴奋剂。"}},{"id":"weak-evidence","title":{"en":"Unsupported claims and practical evidence appraisal","zh":"不可靠宣传与证据评估"},"explanation":["Supplements often reach market before strong independent evidence exists. Testimonials, mechanistic reasoning, animal studies, and acute biomarker changes do not prove improved sport performance. Evidence should replicate in trained humans using relevant outcomes.","A product can be biologically active yet unhelpful because baseline intake is already adequate, the dose is too low, the event does not depend on the targeted mechanism, or side effects offset benefit."],"details":["Branched-chain amino acids add little when total high-quality protein and essential amino acids are sufficient.","Antioxidant megadoses may not improve performance and can create toxicity or alter adaptation.","Hormone boosters frequently rely on indirect markers or deficient populations rather than meaningful results in trained athletes.","Weight-loss products may contain stimulants, undeclared drugs, or doses that increase cardiovascular risk."],"decision":{"en":"Require direct evidence for the exact outcome, population, dose, and product category before recommending use.","zh":"推荐前要求针对确切结果、人群、剂量和产品类别的直接证据。"},"examCue":{"en":"Mechanism is necessary but not sufficient; choose controlled human performance evidence over a marketing pathway diagram.","zh":"机制是必要但不充分的证据；应优先选择受控人体表现研究，而非营销机制图。"}},{"id":"peds","title":{"en":"Performance-enhancing drugs and harmful methods","zh":"提升表现药物与有害方法"},"explanation":["Anabolic-androgenic steroids can increase muscle and strength but carry cardiovascular, endocrine, hepatic, psychiatric, reproductive, and legal or sport-sanction risks. Erythropoietin can increase oxygen-carrying capacity but raises blood viscosity and thrombotic risk. Stimulants, growth hormone misuse, insulin misuse, blood doping, and diuretics carry distinct dangers.","The strength coach does not prescribe, source, or manage illicit or medically inappropriate drug use. The coach follows policy, provides factual risk education within competence, protects confidentiality limits, and refers to medical and sport-integrity professionals."],"details":["Exogenous hormones suppress normal endocrine feedback and can produce prolonged recovery or infertility.","Diuretics reduce scale weight but impair hydration and electrolytes and may mask other substances.","Blood doping and EPO increase red-cell mass but also viscosity, blood pressure, and clot risk.","Needle sharing, counterfeit products, and unsupervised polypharmacy add infectious and toxicological risk."],"decision":{"en":"If use is suspected, avoid accusation; follow organizational policy and refer through designated medical and integrity channels.","zh":"怀疑使用时避免指控；按组织政策并通过指定医疗和诚信渠道转介。"},"examCue":{"en":"A performance benefit does not make a method safe or permitted. Evaluate efficacy, health risk, legality, and rules separately.","zh":"有表现收益不代表安全或允许；应分别评估有效性、健康风险、合法性和规则。"}}],"terms":[{"term":"Ergogenic aid","meaning":{"en":"A substance, method, or device intended to improve performance.","zh":"旨在提高表现的物质、方法或设备。"}},{"term":"Third-party testing","meaning":{"en":"Independent verification of product contents and selected contaminants.","zh":"对产品成分和特定污染物的独立验证。"}},{"term":"Strict liability","meaning":{"en":"The athlete is responsible for prohibited substances found in the body.","zh":"运动员对体内检出的违禁物质负责。"}},{"term":"Anabolic-androgenic steroid","meaning":{"en":"A testosterone-related drug with anabolic and androgenic effects.","zh":"具有合成代谢和雄激素作用的睾酮相关药物。"}}],"formulas":[],"examChecklist":[{"en":"Evaluate a supplement using efficacy, dose, safety, quality, legality, and scope.","zh":"按有效性、剂量、安全、质量、合法性和职责范围评估补剂。"},{"en":"Match creatine, caffeine, beta-alanine, bicarbonate, and nitrate to likely use cases.","zh":"把肌酸、咖啡因、β-丙氨酸、碳酸氢盐和硝酸盐与用途匹配。"},{"en":"Recognize major risks of anabolic steroids, EPO/blood doping, stimulants, and diuretics.","zh":"识别合成代谢类固醇、EPO/血液兴奋、兴奋剂和利尿剂的主要风险。"}],"recall":[{"prompt":{"en":"What does third-party certification prove—and not prove?","zh":"第三方认证能证明什么、不能证明什么？"},"answer":{"en":"It increases confidence in label accuracy and contaminant screening; it does not prove the product is effective, risk-free, or appropriate for the athlete.","zh":"它提高对标签准确和污染物筛查的信心；但不证明产品有效、零风险或适合该运动员。"}},{"prompt":{"en":"Why is a plausible mechanism insufficient evidence?","zh":"为什么合理机制仍不是充分证据？"},"answer":{"en":"The pathway may not create a meaningful performance effect at a practical dose in trained humans, and side effects or adequate baseline status may erase benefit.","zh":"该途径在实际剂量和训练人群中未必产生有意义表现收益，副作用或基线充足也可能抵消收益。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-13', 'en', 'Principles of Test Selection and Administration', 'Choose tests from needs analysis, validity, reliability, feasibility, and athlete characteristics.', '{"n":13,"title":{"en":"Principles of Test Selection and Administration","zh":"测试选择与实施原则"},"domain":{"en":"Program Implementation","zh":"计划实施"},"minutes":105,"source":"Essentials, 5th ed., Ch. 13 · DCO Program Design A · Program Implementation B-C · Exercise Science J","objectives":[{"en":"Choose tests from needs analysis, validity, reliability, feasibility, and athlete characteristics.","zh":"根据需求分析、效度、信度、可行性和运动员特征选择测试。"},{"en":"Standardize testing order, instructions, warm-up, trials, rest, and environment.","zh":"标准化测试顺序、指令、热身、试次、休息和环境。"}],"sections":[{"id":"purpose","title":{"en":"Why test and what decision follows?","zh":"为何测试以及测试后做什么决策"},"explanation":["Testing should answer a defined question: establish a baseline, profile strengths and weaknesses, guide programming, monitor readiness or adaptation, evaluate return-to-performance, or communicate progress. A test without a planned decision adds fatigue and data burden without improving practice.","Begin with the sport and athlete needs analysis. Identify the quality, movement, energy-system demand, injury context, and practical constraints before choosing the tool."],"details":["A test battery should be as small as possible while still covering the decisions that matter.","Benchmarking against norms can describe a group position, but the athlete''s own reliable change is usually more useful for monitoring.","Screening is not diagnosis and rarely predicts injury perfectly; it can identify current limitations or referral needs.","Testing frequency must match how quickly the quality can change and the cost of measurement."],"decision":{"en":"Write the action rule before collecting data: ''If result changes beyond X, we will adjust Y.''","zh":"采集数据前先写行动规则：“若结果变化超过 X，则调整 Y。”"},"examCue":{"en":"Select the test that measures the relevant quality and can change the program—not the most sophisticated device.","zh":"选择能测量相关能力并改变计划的测试，而不是最复杂的设备。"}},{"id":"quality","title":{"en":"Validity, reliability, objectivity, and sensitivity","zh":"效度、信度、客观性与敏感性"},"explanation":["Validity is the degree to which evidence supports the intended interpretation of scores. Reliability is consistency under repeated conditions. Objectivity or interrater reliability concerns agreement among testers. Sensitivity is the ability to detect meaningful change rather than measurement noise.","A test can be reliable but invalid: it may consistently measure the wrong construct. Poor reliability also limits validity because unstable scores cannot support confident interpretation."],"details":["Test-retest reliability examines stability across occasions; intrarater and interrater reliability examine scorer consistency.","Typical error, standard error of measurement, coefficient of variation, and intraclass correlation describe different aspects of reliability.","Minimal detectable change estimates a change unlikely to be measurement error; smallest worthwhile change estimates practical importance.","Learning effects require familiarization before a score is treated as a true baseline."],"decision":{"en":"Interpret a change only after comparing it with the test''s error, the athlete''s normal variability, and the practical importance of the difference.","zh":"只有将变化与测试误差、运动员正常波动和实际意义比较后，才进行解释。"},"examCue":{"en":"Reliability = consistency; validity = justified meaning; sensitivity = ability to detect useful change.","zh":"信度=一致性；效度=解释是否成立；敏感性=能否检测有用变化。"}},{"id":"selection","title":{"en":"Specificity, feasibility, and athlete fit","zh":"专项性、可行性与运动员匹配"},"explanation":["A test should resemble the targeted quality enough to be meaningful, while remaining standardized enough to compare. Movement pattern, velocity, force direction, energy system, duration, and decision demands all contribute to specificity.","Feasibility includes cost, time, equipment, staffing, space, risk, expertise, and athlete burden. A laboratory gold standard may be inferior to a reliable field test that can be repeated consistently."],"details":["Use population-appropriate protocols and norms. A test validated in adults may not transfer directly to youth or injured athletes.","Avoid redundant tests that measure the same construct unless confirmation is worth the cost.","High-skill tests may reflect technique more than the intended physical quality in novices.","Choose unilateral, bilateral, horizontal, vertical, or change-of-direction tests based on the actual question."],"decision":{"en":"Choose the most reliable practical test that represents the quality and population closely enough to guide a decision.","zh":"选择在实际环境中最可靠、又足够代表目标能力和人群的测试。"},"examCue":{"en":"Specific does not mean identical to sport. The test must isolate or represent a useful quality with acceptable control.","zh":"专项不等于完全复制比赛；测试应在可控条件下隔离或代表有用能力。"}},{"id":"administration","title":{"en":"Standardized administration and test order","zh":"标准化实施与测试顺序"},"explanation":["Standardization controls sleep, food, caffeine, prior exercise, time of day, equipment, calibration, surface, footwear, warm-up, instructions, technique criteria, trial number, rest, and encouragement. Record deviations so later comparisons are honest.","Within a battery, place nonfatiguing measures first, then tests requiring speed, skill, and maximal neural quality, and leave highly fatiguing anaerobic and aerobic capacity tests late. Exact order depends on the battery and priority."],"details":["A common sequence is nonfatiguing measurements → agility → maximal power/strength → sprint → muscular endurance → anaerobic capacity → aerobic capacity.","Allow familiarization and a standardized warm-up before maximal performance.","Use the same tester and equipment when possible, and calibrate devices according to procedure.","Terminate for pain, unsafe technique, concerning symptoms, or protocol-defined failure."],"decision":{"en":"Protect the highest-priority and most fatigue-sensitive test by placing it before tests that impair it.","zh":"把最高优先级且最易受疲劳影响的测试放在会干扰它的测试之前。"},"examCue":{"en":"Aerobic capacity is usually last because it creates broad fatigue; nonfatiguing measures are first.","zh":"有氧能力通常最后，因为其造成广泛疲劳；非疲劳测量最先。"}}],"terms":[{"term":"Validity","meaning":{"en":"Evidence supporting the intended interpretation of a test score.","zh":"支持测试分数预期解释的证据。"}},{"term":"Reliability","meaning":{"en":"Consistency of scores under repeated standardized conditions.","zh":"标准化重复条件下分数的一致性。"}},{"term":"Objectivity","meaning":{"en":"Agreement of results across different testers.","zh":"不同测试者之间结果的一致性。"}},{"term":"Minimal detectable change","meaning":{"en":"Change likely to exceed measurement error at a stated confidence.","zh":"在给定置信度下可能超过测量误差的变化。"}},{"term":"Smallest worthwhile change","meaning":{"en":"Smallest change judged practically meaningful.","zh":"被认为具有实际意义的最小变化。"}}],"formulas":[{"name":"Coefficient of variation","expression":"CV% = SD ÷ mean × 100","use":{"en":"Express variability relative to the mean when ratio scaling is appropriate.","zh":"在适合比例尺度时，用均值的百分比表示变异。"}},{"name":"Z-score","expression":"z = (score − mean) ÷ SD","use":{"en":"Describe how far a score is from a reference mean in standard deviations.","zh":"描述分数距参考均值多少个标准差。"}}],"examChecklist":[{"en":"Build a test battery from a sport needs analysis.","zh":"根据项目需求分析建立测试组合。"},{"en":"Explain reliable-but-invalid with an example.","zh":"用例子解释“可靠但无效”。"},{"en":"Recite a defensible test order and the fatigue logic behind it.","zh":"口述合理测试顺序及其疲劳逻辑。"}],"recall":[{"prompt":{"en":"Why is a new test score not automatically a true baseline?","zh":"为什么第一次测试分数不一定是真实基线？"},"answer":{"en":"Learning, unfamiliar technique, anxiety, inconsistent preparation, and measurement error may influence it; familiarization and standardization are needed.","zh":"学习效应、陌生技术、焦虑、准备不一致和测量误差都可能影响，需要熟悉化与标准化。"}},{"prompt":{"en":"What is wrong with using every available test?","zh":"使用所有可用测试有什么问题？"},"answer":{"en":"Redundancy, fatigue, time, false positives, data burden, and unclear decisions can outweigh any added information.","zh":"冗余、疲劳、时间、假阳性、数据负担和不明确决策可能超过新增信息价值。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-14', 'en', 'Administration, Scoring, and Interpretation of Selected Tests', 'Administer and interpret tests of body composition, strength, power, speed, agility, anaerobic and aerobic capacity.', '{"n":14,"title":{"en":"Administration, Scoring, and Interpretation of Selected Tests","zh":"测试的实施、评分与解读"},"domain":{"en":"Program Implementation","zh":"计划实施"},"minutes":165,"source":"Essentials, 5th ed., Ch. 14 · DCO Program Implementation B-C","objectives":[{"en":"Administer and interpret tests of body composition, strength, power, speed, agility, anaerobic and aerobic capacity.","zh":"实施并解读身体成分、力量、功率、速度、敏捷、无氧和有氧能力测试。"},{"en":"Use descriptive statistics and measurement error to communicate actionable results.","zh":"使用描述统计和测量误差沟通可行动结果。"}],"sections":[{"id":"body-composition","title":{"en":"Anthropometry and body composition","zh":"人体测量与身体成分"},"explanation":["Body mass, stature, girths, skinfolds, air displacement, hydrostatic weighing, and DXA each measure or estimate different constructs. No method is perfectly direct; hydration, technician skill, device algorithms, food intake, and recent exercise influence results.","Use the same method, conditions, and technician for monitoring. Body-composition data should support performance and health decisions, not become a public ranking or source of stigma."],"details":["BMI describes mass relative to height but does not distinguish fat from lean tissue and can misclassify muscular athletes.","Skinfold reliability depends strongly on landmarking, pinch technique, caliper use, and tester experience.","Bioelectrical impedance is sensitive to hydration, temperature, food, and recent exercise.","DXA estimates bone mineral content and regional tissue but still depends on device, software, positioning, and hydration."],"decision":{"en":"Choose the least invasive method that is reliable enough for the decision, and standardize before interpreting small change.","zh":"选择足够可靠且侵入性最低的方法，并在解释小变化前标准化条件。"},"examCue":{"en":"A precise-looking percentage is still an estimate. Compare trends within one method, not values across methods.","zh":"看似精确的百分比仍是估计；应在同一方法内看趋势，不要跨方法直接比较。"}},{"id":"strength-power","title":{"en":"Strength, isometric force, and power testing","zh":"力量、等长力与功率测试"},"explanation":["A 1RM test measures exercise-specific maximal dynamic strength. Standardize range, technique, attempt progression, rest, and success criteria. Multiple-RM prediction reduces maximal exposure but introduces equation and fatigue error.","Isometric tests such as the mid-thigh pull can quantify peak force and force-time variables with low movement skill when setup is standardized. Jump and throw tests estimate explosive performance, but calculation method and equipment affect reported power."],"details":["Allow adequate rest between maximal attempts and make load jumps smaller as the estimated maximum is approached.","Relative strength helps compare differently sized athletes, while absolute strength matters for moving fixed external loads.","Jump height can be derived from flight time or impulse; errors occur when takeoff and landing positions differ.","Peak power, mean power, peak force, impulse, and rate of force development answer different questions."],"decision":{"en":"Select the metric that represents the performance need, then keep calculation and device method constant.","zh":"选择代表表现需求的指标，并保持计算与设备方法一致。"},"examCue":{"en":"Do not call jump height ''power'' unless power was actually calculated with mass and time/force information.","zh":"除非结合质量和时间/力信息实际计算，否则不要把跳高直接称为功率。"}},{"id":"speed-agility","title":{"en":"Speed, change-of-direction, and agility testing","zh":"速度、变向与敏捷测试"},"explanation":["Sprint splits reveal acceleration and maximal-speed qualities. Timing-gate height, start distance, stance, surface, footwear, wind, and instructions must be standardized. Hand timing adds substantial reaction and tester error.","Change-of-direction tests use planned movement; agility includes a response to an external stimulus. A preplanned shuttle cannot independently measure perceptual decision skill."],"details":["Short splits emphasize acceleration; flying sprints isolate near-maximal speed after a buildup.","Total change-of-direction time includes linear speed; use segment times or a deficit concept when trying to isolate turning ability.","Repeated trials need sufficient recovery to avoid turning a speed test into a conditioning test.","Reactive agility stimulus should be representative and scored for both movement time and decision quality when possible."],"decision":{"en":"If the sport problem is perception and decision, include a reactive stimulus; if it is braking mechanics, use a controlled planned task.","zh":"若专项问题是感知与决策，应加入反应刺激；若是制动技术，则使用受控预设任务。"},"examCue":{"en":"Change of direction is preplanned; agility requires responding to a stimulus.","zh":"变向是预设动作；敏捷要求对刺激作出反应。"}},{"id":"capacity","title":{"en":"Anaerobic and aerobic capacity tests","zh":"无氧与有氧能力测试"},"explanation":["Anaerobic tests such as repeated sprints or cycle sprints measure peak power, mean power, fatigue, or work under specific protocols. Aerobic tests may directly measure gas exchange or estimate capacity from time, distance, stage, heart rate, or workload.","Protocol selection should match mode and population. Estimation equations inherit error and should not be treated as direct laboratory measurement."],"details":["The Wingate test is highly fatiguing and mode-specific; it should be late in a battery.","Yo-Yo and intermittent field tests reflect repeated high-intensity running and recovery better than continuous tests for some team sports.","30-15 Intermittent Fitness Test output can guide intermittent-running prescription but is not interchangeable with VO2max.","A submaximal heart-rate test assumes a predictable HR-workload relationship and is affected by heat, hydration, caffeine, medication, and fatigue."],"decision":{"en":"Use the protocol''s actual output for prescription only when the prescription method was validated for that protocol.","zh":"只有处方方法针对该测试方案得到验证时，才用其实际输出进行处方。"},"examCue":{"en":"A field-test speed is a protocol-specific result; do not label every final speed VO2max.","zh":"场地测试速度是方案特定结果；不要把所有最终速度都称为 VO2max。"}},{"id":"statistics","title":{"en":"Descriptive statistics and athlete communication","zh":"描述统计与运动员沟通"},"explanation":["The mean summarizes the arithmetic average, median the middle ordered value, and mode the most frequent value. Standard deviation describes spread around the mean. Percentile ranks locate a score within a reference group but do not measure change or causal effect.","Interpret the athlete''s change against measurement error, baseline trend, and program phase. Communicate uncertainty and practical action rather than presenting a dashboard without a decision."],"details":["Outliers may reflect true performance, error, protocol deviation, or data-entry problems; investigate before deletion.","Correlation describes association, not causation. A strong relationship does not prove one variable caused another.","Percent change can exaggerate differences when the baseline is small and should accompany raw values.","Protect privacy by sharing only necessary information with authorized stakeholders."],"decision":{"en":"Report the result, confidence or variability, likely meaning, and the next training action in plain language.","zh":"用清晰语言报告结果、置信或波动、可能含义和下一步训练行动。"},"examCue":{"en":"A team mean can hide individual responders. Program changes should consider individual trends and context.","zh":"团队均值会掩盖个体反应；计划调整应考虑个体趋势与情境。"}}],"terms":[{"term":"Mean","meaning":{"en":"Sum of scores divided by number of scores.","zh":"分数总和除以分数数量。"}},{"term":"Median","meaning":{"en":"Middle value after scores are ordered.","zh":"排序后的中间值。"}},{"term":"Standard deviation","meaning":{"en":"Typical spread of scores around the mean.","zh":"分数围绕均值的典型离散程度。"}},{"term":"Percentile","meaning":{"en":"Percentage of the reference distribution at or below a score.","zh":"参考分布中低于或等于该分数的百分比。"}},{"term":"Correlation","meaning":{"en":"Direction and strength of association between variables.","zh":"变量间关联的方向与强度。"}}],"formulas":[{"name":"Mean","expression":"Σx ÷ n","use":{"en":"Summarize the arithmetic center of scores.","zh":"汇总分数的算术中心。"}},{"name":"Percent change","expression":"(new − old) ÷ old × 100","use":{"en":"Express change relative to baseline while also reporting raw change.","zh":"相对基线表达变化，同时报告原始变化。"}},{"name":"Relative strength","expression":"1RM ÷ body mass","use":{"en":"Compare strength while scaling for body mass.","zh":"按体重标准化力量比较。"}},{"name":"Change-of-direction deficit","expression":"COD test time − equivalent linear sprint time","use":{"en":"Separate turning cost from linear speed contribution.","zh":"把转弯成本与直线速度贡献分开。"}}],"examChecklist":[{"en":"Choose and standardize one test for each major athletic quality.","zh":"为每项主要运动能力选择并标准化一个测试。"},{"en":"Separate score, metric, and interpretation: jump height is not automatically power.","zh":"区分分数、指标与解释：跳高不自动等于功率。"},{"en":"Calculate mean, percent change, z-score, relative strength, and COD deficit.","zh":"计算均值、百分比变化、z 分数、相对力量和变向缺失。"}],"recall":[{"prompt":{"en":"Why can different jump devices report different results?","zh":"为什么不同跳跃设备会报告不同结果？"},"answer":{"en":"They may use flight time, impulse, reach displacement, or different filtering and takeoff criteria; each method has distinct assumptions and error.","zh":"它们可能使用腾空时间、冲量、触高位移或不同滤波与起跳标准，各有不同假设和误差。"}},{"prompt":{"en":"What four elements belong in a result report?","zh":"结果报告应包含哪四项？"},"answer":{"en":"The result, its uncertainty or normal variability, the likely practical meaning, and the training or communication action.","zh":"结果、其不确定性或正常波动、可能的实际意义，以及训练或沟通行动。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-15', 'en', 'Performance Preparation, Mobility, and Flexibility', 'Build a progressive warm-up that raises readiness without creating fatigue.', '{"n":15,"title":{"en":"Performance Preparation, Mobility, and Flexibility","zh":"运动准备、灵活性与柔韧性"},"domain":{"en":"Exercise Technique","zh":"运动技术"},"minutes":95,"source":"Essentials, 5th ed., Ch. 15 · DCO Exercise Technique A, E","objectives":[{"en":"Build a progressive warm-up that raises readiness without creating fatigue.","zh":"建立提高准备度且不制造疲劳的渐进热身。"},{"en":"Choose static, dynamic, ballistic, and PNF methods by goal, timing, athlete, and risk.","zh":"按目标、时机、个体和风险选择静态、动态、弹震与 PNF。"}],"sections":[{"id":"ramp","title":{"en":"RAMP performance preparation","zh":"RAMP 运动准备"},"explanation":["A warm-up should raise body temperature and circulation, activate relevant muscles and control, mobilize the ranges needed, and potentiate the speed or force of the upcoming task. The RAMP sequence—Raise, Activate/Mobilize, Potentiate—progresses from general preparation to specific rehearsal.","A good warm-up is judged by readiness and performance, not by duration or sweat alone. It should reduce uncertainty, rehearse technique, and finish near the intensity of the first work set without excessive fatigue."],"details":["Raise: low-intensity movement that increases temperature, heart rate, and blood flow.","Activate and mobilize: targeted control and dynamic range for the session''s demands.","Potentiate: progressive accelerations, jumps, throws, or warm-up sets that approach target force and velocity.","Environmental conditions, athlete age, injury history, and time since the last activity change the required dose."],"decision":{"en":"Remove any warm-up drill that does not improve readiness, technique, confidence, or the next task.","zh":"删除不能改善准备度、技术、信心或下一任务的热身动作。"},"examCue":{"en":"The warm-up becomes more specific and intense as it approaches performance, while total fatigue stays low.","zh":"热身越接近正式表现越专项、强度越高，但总疲劳应保持低。"}},{"id":"mobility-flexibility","title":{"en":"Mobility, flexibility, and stability","zh":"灵活性、柔韧性与稳定性"},"explanation":["Flexibility is the available range around a joint or series of joints. Mobility includes the ability to actively access and control range in a task. Stability is the capacity to control position and motion under load. A range limitation can arise from tissue tolerance, joint structure, neural protection, pain, weakness, or motor control.","More range is not universally better. The athlete needs enough controllable range for the sport and exercise while retaining force, stiffness, and joint integrity."],"details":["Active range requires force and control; passive range can exceed what the athlete can use safely.","Acute range increases may reflect increased stretch tolerance and altered neural response, not immediate permanent tissue lengthening.","Pain, sudden asymmetry, neurological symptoms, or suspected joint pathology requires referral rather than aggressive stretching.","Strength training through a suitable full range can improve mobility while building control."],"decision":{"en":"Identify whether the limiter is range, control, strength, pain, or task setup before choosing a mobility drill.","zh":"先确定限制来自幅度、控制、力量、疼痛还是任务设置，再选择灵活性练习。"},"examCue":{"en":"Flexibility is range; mobility is usable controlled range. Do not prescribe stretching for every movement fault.","zh":"柔韧性是幅度；灵活性是可用且受控的幅度。不要对所有动作问题都开拉伸。"}},{"id":"stretching","title":{"en":"Static, dynamic, ballistic, and PNF stretching","zh":"静态、动态、弹震与 PNF 拉伸"},"explanation":["Static stretching holds a position; dynamic stretching moves actively through range; ballistic stretching uses faster bouncing or momentum; PNF combines stretching with muscle contraction. Each method can improve range when dosed appropriately, but the acute performance effect and skill requirement differ.","Long, intense static stretching immediately before maximal strength or power can transiently reduce output. Shorter static work may be acceptable when a range restriction matters and is followed by dynamic, specific potentiation."],"details":["Dynamic stretching fits warm-ups because it raises temperature and rehearses movement while accessing range.","Ballistic methods can be sport-relevant for trained athletes but require progression and control.","PNF hold-relax and contract-relax methods use contraction to alter tolerance and neural response; partner communication is essential.","Long-term flexibility work can be placed after training or in separate sessions when acute power is not the next priority."],"decision":{"en":"Use dynamic mobility before explosive work; place larger static-flexibility doses away from immediate maximal performance.","zh":"爆发训练前使用动态灵活性；较大静态柔韧性剂量应远离即时最大表现。"},"examCue":{"en":"Timing matters: static stretching is not ''bad,'' but a large acute dose can reduce immediate high-force or high-power output.","zh":"时机很重要：静态拉伸并非“坏”，但较大急性剂量可降低即时高力量或高功率输出。"}},{"id":"programming","title":{"en":"Programming range of motion and restoration","zh":"幅度训练与恢复安排"},"explanation":["Mobility adaptation requires repeated exposure at an effective intensity with adequate recovery, like other training. Combine positional breathing, active control, loaded range, and sport-specific speed according to the athlete''s need.","Restoration sessions may use low-intensity movement, breathing, and gentle range work to reduce arousal and support recovery, but they do not replace sleep, nutrition, or load management."],"details":["Progress from passive access to active control, then load and speed in the required range.","Measure the task that matters rather than chasing a generic flexibility score.","Do not force range through sharp pain or unstable joint positions.","Reassess after the intervention to confirm that movement or performance actually improved."],"decision":{"en":"Earn range, control it, load it, then express it at sport speed.","zh":"先获得幅度，再控制它、加载它，最后在专项速度下表达。"},"examCue":{"en":"Choose the least aggressive method that produces the required controllable range.","zh":"选择能产生所需可控幅度的最低必要强度方法。"}}],"terms":[{"term":"Flexibility","meaning":{"en":"Available joint range of motion.","zh":"可获得的关节活动范围。"}},{"term":"Mobility","meaning":{"en":"Ability to actively access and control range in a task.","zh":"在任务中主动获得并控制幅度的能力。"}},{"term":"Potentiation","meaning":{"en":"Acute enhancement of performance after an appropriate conditioning activity.","zh":"适当预备活动后表现的急性增强。"}},{"term":"PNF","meaning":{"en":"Stretching methods combining passive movement and muscle contraction.","zh":"结合被动活动与肌肉收缩的拉伸方法。"}}],"formulas":[],"examChecklist":[{"en":"Build a RAMP warm-up for strength, sprint, and team-sport sessions.","zh":"为力量、冲刺和团队运动课建立 RAMP 热身。"},{"en":"Select stretching method and timing from the performance goal.","zh":"依据表现目标选择拉伸方式与时机。"},{"en":"Differentiate a range limitation from a control or pain problem.","zh":"区分幅度限制、控制问题和疼痛问题。"}],"recall":[{"prompt":{"en":"What are the three RAMP phases?","zh":"RAMP 的三个阶段是什么？"},"answer":{"en":"Raise; Activate and Mobilize; Potentiate.","zh":"提高；激活与动员；增强。"}},{"prompt":{"en":"When can static stretching be useful before performance?","zh":"静态拉伸何时可在表现前使用？"},"answer":{"en":"When a specific range restriction limits safe performance, using a modest dose followed by dynamic and task-specific potentiation.","zh":"当特定幅度限制安全表现时，可用适量静态拉伸，随后加入动态和任务特定增强。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-16', 'en', 'Exercise Technique for Free Weight and Machine Training', 'Teach, observe, cue, and regress major free-weight and machine patterns.', '{"n":16,"title":{"en":"Exercise Technique for Free Weight and Machine Training","zh":"自由重量与器械训练技术"},"domain":{"en":"Exercise Technique","zh":"运动技术"},"minutes":210,"source":"Essentials, 5th ed., Ch. 16 · DCO Exercise Technique B","objectives":[{"en":"Teach, observe, cue, and regress major free-weight and machine patterns.","zh":"教授、观察、提示并回归主要自由重量和器械动作。"},{"en":"Apply setup, breathing, spotting, and failure procedures safely.","zh":"安全应用设置、呼吸、保护和失败处理流程。"}],"sections":[{"id":"fundamentals","title":{"en":"Setup, grip, breathing, and observation","zh":"设置、握法、呼吸与观察"},"explanation":["Technique begins before the first repetition: inspect equipment, set rack height and safeties, select collars and load, establish stance and grip, confirm the movement standard, and clear the area. The coach observes from an angle that reveals the relevant joints without interfering.","Breathing should support trunk stiffness and safety. In moderate work, exhale through the sticking region and inhale during the easier phase. Experienced healthy lifters may use a brief Valsalva for heavy attempts, but medical context and instruction matter."],"details":["Closed grips place the thumb around the bar and are generally safer than false grips.","Neutral spinal position means a controlled, task-appropriate posture—not identical geometry for every athlete.","Use collars when plate movement creates risk, except when a specific emergency-dumping protocol and environment dictates otherwise.","Give one high-priority cue, observe the next repetition, and avoid overloading working memory."],"decision":{"en":"Correct immediate safety first, then the error with the largest effect on force transfer or the training goal.","zh":"先纠正即时安全问题，再处理最影响力传递或训练目标的错误。"},"examCue":{"en":"Setup and safety are part of technique. The best answer often fixes rack, grip, spotter, or equipment before movement begins.","zh":"设置和安全属于技术的一部分；最佳答案常在动作前先修正架位、握法、保护者或设备。"}},{"id":"squat","title":{"en":"Squat and lower-body patterns","zh":"深蹲与下肢动作模式"},"explanation":["A squat coordinates hip, knee, and ankle flexion on descent and extension on ascent while the whole foot remains stable and the trunk resists unwanted motion. Stance, toe angle, depth, and torso angle vary with anatomy, bar position, footwear, and task.","The bar or load should remain balanced over the base of support. A forward torso is not automatically an error; loss of balance, uncontrolled spinal motion, painful range, or a path that no longer serves the exercise is more important."],"details":["High-bar and front squats usually allow a more upright torso than low-bar squats because load position changes the system center of mass.","Knees should track in a controlled direction compatible with the feet; rapid uncontrolled valgus under fatigue is a common correction target.","Depth should match the goal and the athlete''s controllable, pain-free range; partial range changes joint and muscle demand.","Regress with goblet squat, box target, reduced load, tempo, or range; progress load, depth, speed, unilateral demand, or complexity."],"decision":{"en":"Keep the load balanced, the feet organized, and the joints moving through a controlled range that matches the goal.","zh":"保持负荷平衡、足部稳定，关节在与目标匹配的受控幅度中运动。"},"examCue":{"en":"Do not choose a universal stance or forbid all forward knee travel; evaluate control, balance, anatomy, and task.","zh":"不要选择统一站距或禁止所有膝盖前移；应评估控制、平衡、解剖和任务。"}},{"id":"press-pull","title":{"en":"Bench press, overhead press, and rowing","zh":"卧推、过头推与划船"},"explanation":["The bench press requires stable contact, a controlled grip, organized scapular position, and a bar path that allows the forearms to transfer force efficiently. The overhead press stacks the system over the base while the shoulder blade upwardly rotates and the trunk resists excessive extension.","Rows and pulldowns train shoulder extension or adduction with elbow flexion and scapular motion. The goal is controlled movement rather than fixing the scapula rigidly in every phase."],"details":["In the bench press, wrists remain stacked over forearms, the bar descends under control, and the elbows do not lose the chosen stable path.","A liftoff should help position the bar without pulling the athlete out of the setup.","Overhead pressing requires sufficient shoulder motion and trunk control; a landmine or incline press can regress the demand.","Machine seat and axis should be adjusted to align the athlete and joint with the intended movement."],"decision":{"en":"Choose grip and path that allow stable joints, effective force transfer, and the intended muscle action without pain.","zh":"选择能保持关节稳定、有效传力并产生目标肌肉动作且无疼痛的握法与路径。"},"examCue":{"en":"For machines, alignment and seat setup are common first corrections; for bench press, spotting and handoff matter.","zh":"器械动作常先纠正轴线和座椅；卧推则要关注保护和起杠。"}},{"id":"hinge","title":{"en":"Deadlift, hinge, and pulling from the floor","zh":"硬拉、髋铰链与地面拉起"},"explanation":["The hip hinge loads hip extensors while the trunk remains braced and the load stays close. In a deadlift, the athlete creates whole-body tension before the bar leaves the floor, pushes through the ground, and extends hip and knee without allowing the bar to drift forward.","Conventional, sumo, trap-bar, Romanian, and block variations change stance, range, torso angle, moment arms, and technical demand. Select the variation from goal, anatomy, competency, and equipment."],"details":["The bar begins over the midfoot and close to the shins in common barbell deadlift setups.","The shoulders and hips should rise in a coordinated pattern; an early hip rise can turn the lift into a less favorable stiff-leg pull.","At lockout, finish with hip extension rather than excessive lumbar extension.","Use elevated starts, kettlebell hinges, dowel feedback, or reduced load to teach the pattern."],"decision":{"en":"Shorten the external moment arm by keeping the load close and build tension before acceleration.","zh":"保持负荷靠近身体以缩短外部力臂，并在加速前建立张力。"},"examCue":{"en":"''Bar close to body'' is a high-value cue because it directly controls external torque.","zh":"“杠铃贴近身体”是高价值提示，因为它直接控制外部力矩。"}},{"id":"weightlifting","title":{"en":"Weightlifting derivatives","zh":"举重衍生动作"},"explanation":["Weightlifting derivatives develop rapid force and whole-body power. Pulling phases coordinate force into the ground, extension, and upward bar momentum; receiving phases require rapid repositioning and stable force absorption. Not every program needs the full competitive lifts.","Teach from stable positions and simpler derivatives: jump-shrug or pull, hang variation, catch pattern, then more complex floor starts or jerk variations when justified."],"details":["The first pull establishes position; transition repositions the body; the second pull applies high force and velocity; turnover moves the athlete under the bar.","The bar remains close to reduce unwanted horizontal displacement and improve control.","A power catch is received above a full squat; the exact depth depends on bar height and athlete movement.","Weightlifting movements need clear bailout space, bumper plates, platforms, and no traditional spotters on the moving bar."],"decision":{"en":"Use the simplest derivative that trains the desired force-velocity quality and that staff can coach safely.","zh":"使用能训练目标力-速度能力且教练团队能安全指导的最简单衍生动作。"},"examCue":{"en":"Olympic-lift bars are not spotted through a failed repetition; athletes release safely in a prepared area.","zh":"举重动作失败时不由保护者跟杠；运动员应在准备好的区域安全弃杠。"}},{"id":"spotting","title":{"en":"Spotting and failed-repetition procedures","zh":"保护与失败重复流程"},"explanation":["Spotting reduces consequence when a free-weight repetition fails, but it does not replace correct rack setup, safeties, load selection, and communication. The lifter and spotter agree on handoff, repetition count, and intervention cue before the set.","Spotter number and position depend on the lift and load. Bench press commonly uses a head spotter; heavy squats may use side spotters and rack safeties. Dumbbell movements require control at the wrists or forearms rather than the elbows when assistance is necessary."],"details":["The spotter maintains a stable base and stays close without touching until assistance is needed.","Use an appropriate grip for the bar and coordinate multiple spotters with one clear leader.","Power exercises and Olympic lifts use safe release procedures rather than conventional spotting.","Machines still require pin, range, seat, cable, and emergency-stop checks."],"decision":{"en":"If a lift cannot be safely spotted or released in the current environment, change the exercise or setup.","zh":"若当前环境无法安全保护或弃杠，就必须改变动作或设置。"},"examCue":{"en":"Spot the implement where control can be maintained; do not grab a lifter''s joint or obstruct the bar path.","zh":"应在能保持控制的位置保护器械，不要抓运动员关节或阻挡杠铃路径。"}}],"terms":[{"term":"Closed grip","meaning":{"en":"Thumb wraps around the implement to secure the grip.","zh":"拇指环绕器械形成安全握法。"}},{"term":"Valsalva maneuver","meaning":{"en":"Brief breath hold against a closed glottis to increase trunk pressure and stiffness.","zh":"短暂闭合声门屏息以提高躯干压力和刚度。"}},{"term":"Sticking region","meaning":{"en":"Range where the lifter has greatest difficulty overcoming the load.","zh":"运动员最难克服负荷的动作区间。"}},{"term":"Weightlifting derivative","meaning":{"en":"A pull, catch, or drive variation derived from Olympic weightlifting.","zh":"源自奥林匹克举重的拉、接或驱动变式。"}}],"formulas":[],"examChecklist":[{"en":"Teach setup, execution, breathing, and safety for squat, bench, hinge, press, row, and weightlifting pull.","zh":"教授深蹲、卧推、髋铰链、推、拉和举重拉的设置、执行、呼吸与安全。"},{"en":"Choose spotter number and position for bench, squat, and dumbbell exercises.","zh":"为卧推、深蹲和哑铃动作选择保护者数量与位置。"},{"en":"Prioritize one correction from a described or visual technique fault.","zh":"从描述或视觉技术错误中选出最高优先级纠正。"}],"recall":[{"prompt":{"en":"What are the first three checks before a loaded set?","zh":"负重组开始前最先检查哪三项？"},"answer":{"en":"Equipment and load security, rack/safety setup, and athlete stance/grip plus the agreed movement and spotting procedure.","zh":"设备与负荷安全、架位/安全杆设置，以及运动员站位握法和约定动作/保护流程。"}},{"prompt":{"en":"Why does keeping the bar close help a deadlift?","zh":"为什么杠铃贴近身体有助于硬拉？"},"answer":{"en":"It shortens the external moment arm, reducing trunk and hip torque demand for the same load.","zh":"它缩短外部力臂，使相同负荷下躯干和髋部力矩需求降低。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-17', 'en', 'Exercise Technique for Alternative Modes and Nontraditional Implement Training', 'Select and coach bodyweight, core, unstable, variable-resistance, and nontraditional-implement training.', '{"n":17,"title":{"en":"Exercise Technique for Alternative Modes and Nontraditional Implement Training","zh":"替代与非传统器械训练技术"},"domain":{"en":"Exercise Technique","zh":"运动技术"},"minutes":110,"source":"Essentials, 5th ed., Ch. 17 · DCO Exercise Technique B3","objectives":[{"en":"Select and coach bodyweight, core, unstable, variable-resistance, and nontraditional-implement training.","zh":"选择并指导自重、核心、不稳定、变阻力和非传统器械训练。"},{"en":"Match novelty to a measurable adaptation rather than using complexity for its own sake.","zh":"让新颖性服务于可测适应，而不是为复杂而复杂。"}],"sections":[{"id":"bodyweight","title":{"en":"Bodyweight and suspension training","zh":"自重与悬吊训练"},"explanation":["Bodyweight resistance can be progressed through leverage, range, tempo, unilateral loading, instability, external load, or repetition density. It is not inherently low intensity; task mechanics determine relative demand.","Suspension systems change body angle and stability, allowing rapid scaling. Anchor integrity, floor traction, body-line control, and clearance are primary safety concerns."],"details":["Push-up load increases as the center of mass shifts toward the hands or feet are elevated.","Assistance can be changed through hand support, box height, counterbalance, or shortened range.","High repetitions train local endurance only if technique and range remain consistent.","Use objective progression rather than assuming a more unusual variation is better."],"decision":{"en":"Progress one mechanical variable while keeping the target movement and quality recognizable.","zh":"每次推进一个机械变量，同时保持目标动作和质量清晰。"},"examCue":{"en":"Bodyweight does not mean fixed load; leverage and supported body mass change resistance substantially.","zh":"自重不等于固定负荷；杠杆和被支撑体重比例会显著改变阻力。"}},{"id":"core-balance","title":{"en":"Core stability, balance, and unstable surfaces","zh":"核心稳定、平衡与不稳定表面"},"explanation":["Core training transfers force and controls trunk position across anti-extension, anti-flexion, anti-rotation, anti-lateral-flexion, and dynamic patterns. Balance training manipulates base of support, center of mass, sensory input, and task demand.","Instability increases stabilizing and attentional demand but usually reduces the external force and power that can be produced. It is useful when the goal is control or rehabilitation, not automatically when maximal strength or power is the priority."],"details":["Begin with breathing and bracing, then integrate limb motion, load, speed, and sport-relevant positions.","Removing vision or narrowing the base changes sensory and mechanical challenge; provide fall protection.","Stable surfaces are preferred for high-force barbell work because they permit greater output and safer load handling.","The trunk should be trained to transmit and produce force, not merely to remain rigid in all movement."],"decision":{"en":"Use instability only when the reduced force output is acceptable for the intended adaptation.","zh":"只有当降低力量输出不妨碍目标适应时才使用不稳定性。"},"examCue":{"en":"Unstable-surface training is not the best choice for maximal force or power development.","zh":"不稳定表面训练不是发展最大力量或功率的最佳选择。"}},{"id":"variable-resistance","title":{"en":"Bands, chains, and flywheel resistance","zh":"弹力带、链条与飞轮阻力"},"explanation":["Bands and chains can increase resistance as they stretch or lift from the floor, potentially matching an ascending strength curve and encouraging acceleration. They also change stability and bar behavior, so total load and setup must be controlled.","Flywheels store kinetic energy during the concentric phase and return it during the eccentric phase. Eccentric demand depends on how the athlete brakes the rotating mass rather than a fixed external weight."],"details":["Quantify band or chain contribution at relevant positions instead of reporting only bar weight.","Anchor bands securely and inspect for wear; a failed band can cause injury.","Flywheel familiarization is essential because timing determines eccentric overload.","Variable resistance is a tool for a specific profile, not a replacement for all constant-resistance training."],"decision":{"en":"Use variable resistance when its profile solves a force-velocity or range-specific problem and can be measured safely.","zh":"当变阻力曲线能解决力-速度或特定幅度问题且可安全测量时使用。"},"examCue":{"en":"Report total resistance across the range; ''50 kg plus bands'' is incomplete without band tension.","zh":"应报告全幅度总阻力；“50 kg 加弹力带”若无带张力信息并不完整。"}},{"id":"implements","title":{"en":"Sleds, ropes, tires, sandbags, kettlebells, and medicine balls","zh":"雪橇、战绳、轮胎、沙袋、壶铃与药球"},"explanation":["Nontraditional implements can provide horizontal force, carrying, throwing, grip, trunk, and conditioning options. Their value comes from the force direction and task, not novelty. Technique standards must reflect the implement''s moving center of mass and release path.","Sled work reduces eccentric loading during forward propulsion; medicine balls permit true release and high acceleration; sandbags and water-filled loads create shifting resistance; ropes create repeated upper-body and trunk power demands."],"details":["Sled load, surface friction, harness angle, and speed determine demand, so plate mass alone is not comparable across surfaces.","Medicine-ball throws need a clear impact and rebound area and a ball designed for the intended use.","Tire flips require hip and leg drive with close body position; avoid curling the tire with a rounded trunk.","Kettlebell swings are ballistic hinges, not slow squats or shoulder raises."],"decision":{"en":"Define the target—horizontal force, release power, work capacity, grip, or trunk control—then choose the simplest implement that delivers it.","zh":"先明确目标是水平力、释放功率、工作能力、握力还是躯干控制，再选最简单可实现的器械。"},"examCue":{"en":"Surface and friction are part of sled load; plate mass alone does not define intensity.","zh":"地面和摩擦属于雪橇负荷的一部分；仅看杠铃片重量不能定义强度。"}},{"id":"unilateral","title":{"en":"Unilateral training and asymmetry","zh":"单侧训练与不对称"},"explanation":["Unilateral training increases per-limb demand, balance, frontal- and transverse-plane control, and can train around equipment or injury constraints. It may expose asymmetry, but a difference is not automatically pathological or predictive of injury.","Bilateral training permits greater total external loading and remains important when the sport requires high bilateral force. Most programs use both according to the needs analysis."],"details":["Rear-foot-elevated split squats change support and hip position but are not universally superior to bilateral squats.","Single-arm loading creates trunk anti-rotation and lateral-flexion demand.","Compare sides with a reliable test and account for normal variability before labeling asymmetry.","Use the weaker or less skilled side first when fatigue could otherwise widen the difference, while keeping total dose appropriate."],"decision":{"en":"Use unilateral work to target per-limb force and control; use bilateral work when total force and sport transfer justify it.","zh":"单侧训练用于每侧力量与控制；双侧训练用于总力量和专项迁移。"},"examCue":{"en":"Asymmetry is information, not a diagnosis. Interpret magnitude, reliability, task, and history.","zh":"不对称是信息，不是诊断；应结合幅度、信度、任务和历史解释。"}}],"terms":[{"term":"Variable resistance","meaning":{"en":"Resistance that changes through the movement range.","zh":"随动作幅度变化的阻力。"}},{"term":"Eccentric overload","meaning":{"en":"Eccentric demand exceeds the concentric load or capacity used in the same repetition.","zh":"同一重复中离心需求超过向心负荷或能力。"}},{"term":"Anti-rotation","meaning":{"en":"Resisting unwanted rotation of the trunk.","zh":"抵抗躯干不必要旋转。"}},{"term":"Unilateral deficit","meaning":{"en":"Difference between bilateral output and the sum of separate unilateral outputs.","zh":"双侧输出与两侧单独输出之和的差异。"}}],"formulas":[{"name":"Asymmetry percentage","expression":"|right − left| ÷ larger side × 100","use":{"en":"Describe side-to-side difference while also considering test error and task relevance.","zh":"描述左右差异，同时考虑测试误差与任务相关性。"}}],"examChecklist":[{"en":"Progress a bodyweight pattern using leverage, range, tempo, and unilateral demand.","zh":"用杠杆、幅度、节奏和单侧需求进阶自重动作。"},{"en":"Explain when instability supports or conflicts with the goal.","zh":"解释不稳定性何时支持或冲突于目标。"},{"en":"Coach safe setup for bands, flywheel, sled, medicine ball, tire, and kettlebell.","zh":"指导弹力带、飞轮、雪橇、药球、轮胎和壶铃的安全设置。"}],"recall":[{"prompt":{"en":"Why can unstable training reduce power development?","zh":"为什么不稳定训练可能降低功率发展？"},"answer":{"en":"The athlete must allocate control to stabilization and usually cannot apply as much external force or velocity.","zh":"运动员必须分配控制资源用于稳定，通常无法施加同样大的外力或速度。"}},{"prompt":{"en":"Why is sled plate mass not a complete intensity measure?","zh":"为什么雪橇杠铃片重量不是完整强度指标？"},"answer":{"en":"Surface friction, sled design, attachment angle, athlete speed, and technique materially change the required force.","zh":"地面摩擦、雪橇设计、连接角度、运动员速度和技术都会显著改变所需力量。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-18', 'en', 'Program Design for Resistance Training', 'Convert a needs analysis into exercise, frequency, order, load, volume, rest, and progression decisions.', '{"n":18,"title":{"en":"Program Design for Resistance Training","zh":"抗阻训练计划设计"},"domain":{"en":"Program Design","zh":"计划设计"},"minutes":150,"source":"Essentials, 5th ed., Ch. 18 · DCO Program Design A-C, E-F","objectives":[{"en":"Convert a needs analysis into exercise, frequency, order, load, volume, rest, and progression decisions.","zh":"把需求分析转化为动作、频率、顺序、负荷、训练量、休息和进阶决策。"},{"en":"Manipulate training variables for strength, power, hypertrophy, endurance, and sport transfer.","zh":"针对力量、功率、肌肥大、耐力和专项迁移调整训练变量。"}],"sections":[{"id":"needs-analysis","title":{"en":"Step 1 — needs analysis","zh":"第一步——需求分析"},"explanation":["Program design begins with the sport, not with a favorite exercise. Analyze movement patterns, muscles and joints, force and velocity demands, energy systems, common injury mechanisms, schedule, and phase of the year. Then profile the athlete''s training status, test results, injury history, goals, age, and constraints.","The gap between sport demand and athlete capacity defines priorities. A priority is not merely a weakness: it is a trainable limitation that matters to performance and can be addressed without creating a larger conflict elsewhere."],"details":["Movement analysis asks what the athlete must produce, absorb, stabilize, and repeat.","Physiological analysis identifies force-time, velocity, duration, work-to-rest, and metabolic demands.","Injury analysis guides tissue preparation and exposure management; it does not authorize diagnosis.","Training status determines starting complexity, volume tolerance, and rate of progression.","Write measurable outcomes and rank primary, secondary, and maintenance qualities."],"decision":{"en":"Choose the smallest set of priorities that can receive a meaningful dose and still allow recovery.","zh":"选择最少但能获得有效刺激且可恢复的一组优先能力。"},"examCue":{"en":"When a scenario gives sport demands and athlete test results, solve the gap before choosing sets and reps.","zh":"题干同时给出专项需求和测试结果时，先解决差距，再选择组次。"}},{"id":"selection-order","title":{"en":"Exercise selection, frequency, and order","zh":"动作选择、频率与顺序"},"explanation":["Select exercises by training goal, movement relevance, muscle balance, technique competence, equipment, time, and medical constraints. Core exercises involve large muscle mass and multiple joints; assistance exercises target smaller areas or specific needs. Structural exercises load the spine directly or indirectly and require appropriate readiness.","Order preserves the quality that matters most. Power and technically demanding work generally precede heavy strength work; large-muscle, multijoint exercises precede smaller assistance work. Alternatives such as upper/lower alternation, push/pull alternation, supersets, and circuits trade local recovery for time efficiency or conditioning density."],"details":["Frequency depends on training status, total stress, split, season, practice and competition density, and recovery.","Beginners often use fewer whole-body sessions; advanced athletes may distribute higher volume across more sessions.","Do not train heavily through severe soreness, technique breakdown, or unresolved medical symptoms.","Exercise specificity matters, but exact sport imitation under load is not automatically superior.","Balance prime movers with stabilizers and repeated sport positions with complementary patterns."],"decision":{"en":"Place the highest-priority exercise early enough that fatigue does not change its intended stimulus.","zh":"把最高优先动作放在疲劳不会改变目标刺激的位置。"},"examCue":{"en":"Typical order: power → other core exercises → assistance, unless the stated goal justifies another sequence.","zh":"典型顺序：功率动作→其他核心动作→辅助动作，除非题干目标支持其他顺序。"}},{"id":"load-volume-rest","title":{"en":"Load, repetitions, volume, and rest","zh":"负荷、重复次数、训练量与休息"},"explanation":["Load and repetitions are linked but individual. A percentage of 1RM estimates relative intensity, while repetition maximum prescribes the heaviest load possible for a target repetition count. Neither replaces observation of velocity, effort, and technique. Volume can be described as repetitions, sets, volume-load, hard sets, or work performed; use the measure that supports the decision.","Strength emphasizes high force and longer recovery; hypertrophy requires sufficient challenging volume across a broad loading range; muscular endurance uses repeated submaximal contractions; power requires high intent, appropriate external load, and low enough fatigue to preserve velocity."],"details":["Strength: commonly heavy loads, low repetitions, multiple sets, and 2–5 minutes of rest for core work.","Hypertrophy: accumulate multiple challenging sets with adequate proximity to failure and roughly 30–90 seconds to several minutes of rest depending on exercise and load.","Endurance: lighter loads, higher repetitions, and shorter rest increase local fatigue tolerance.","Power: use explosive intent, modest repetitions, full recovery, and stop sets when velocity or technique falls materially.","Failure is a tool, not a requirement; frequent failure can raise fatigue more than useful stimulus."],"decision":{"en":"Select load and rest to preserve the intended quality, then add only as much volume as the athlete can adapt to.","zh":"先用负荷和休息保持目标能力，再加入运动员能适应的训练量。"},"examCue":{"en":"The same percentage does not create the same repetitions for every athlete or exercise.","zh":"同一百分比并不让所有运动员或动作完成相同重复次数。"}},{"id":"progression","title":{"en":"Progression, monitoring, and worked design","zh":"进阶、监控与设计实例"},"explanation":["Progressive overload increases the challenge as adaptation occurs. Progression may change load, volume, frequency, range, complexity, velocity, density, or exercise variation. Change one major variable at a time when possible so the response remains interpretable.","A common load rule is the 2-for-2 rule: if the athlete completes at least two repetitions beyond the target on the final set in two consecutive workouts, raise the load. It is a practical heuristic, not a substitute for judgment."],"details":["Example: a field-sport athlete needs lower-body strength and acceleration. Prioritize jumps or sprints, then squat/hinge strength, unilateral assistance, posterior chain, and trunk control.","If competition density rises, maintain intensity while reducing volume rather than chasing new overload.","Record load, repetitions, RPE/RIR, velocity when available, pain, and technique notes.","Plateaus require diagnosis: insufficient stimulus, excessive fatigue, poor specificity, weak technique, nutrition, sleep, or unrealistic expectations.","Deload by reducing stress deliberately; do not wait for performance collapse."],"decision":{"en":"Progress only when the athlete owns the current dose with repeatable technique and recoverable fatigue.","zh":"只有当运动员能以稳定技术完成当前剂量并可恢复时才进阶。"},"examCue":{"en":"For small, less trained muscles, increase load by about 2.5–5%; for large, trained muscle groups, about 5–10% is a common starting rule.","zh":"小肌群或训练程度较低者常增加约 2.5–5%；大肌群或训练充分者常以 5–10% 为起点。"}}],"terms":[{"term":"Core exercise","meaning":{"en":"A multijoint exercise using one or more large muscle areas.","zh":"使用一个或多个大肌群的多关节动作。"}},{"term":"RM","meaning":{"en":"The greatest load that can be completed for a specified number of repetitions.","zh":"能完成指定重复次数的最大负荷。"}},{"term":"Volume-load","meaning":{"en":"Sets × repetitions × external load; useful but incomplete measure of work.","zh":"组数×次数×外部负荷；有用但不完整的做功指标。"}},{"term":"Repetitions in reserve","meaning":{"en":"Estimated additional repetitions possible before task failure.","zh":"达到任务失败前估计还能完成的次数。"}}],"formulas":[{"name":"Volume-load","expression":"sets × repetitions × load","use":{"en":"Track external resistance work within the same exercise context.","zh":"在相同动作情境下追踪外部阻力训练量。"},"example":"4 × 6 × 100 kg = 2,400 kg"},{"name":"Relative intensity","expression":"training load ÷ 1RM × 100","use":{"en":"Express load relative to tested maximum.","zh":"表示相对于测试最大力量的负荷。"},"example":"80 kg ÷ 100 kg = 80% 1RM"}],"examChecklist":[{"en":"Complete sport and athlete needs analyses before selecting variables.","zh":"选择变量前完成专项与运动员需求分析。"},{"en":"Match order, load, volume, and rest to the primary goal.","zh":"使顺序、负荷、训练量与休息匹配主要目标。"},{"en":"Apply 2-for-2 and percentage load increases appropriately.","zh":"正确应用 2-for-2 和百分比加重规则。"},{"en":"Modify the plan around practice, competition, fatigue, pain, and readiness.","zh":"围绕训练、比赛、疲劳、疼痛和准备度调整计划。"}],"recall":[{"prompt":{"en":"Why should power exercises usually come first?","zh":"为什么功率动作通常最先？"},"answer":{"en":"They require high neural quality, velocity, coordination, and low fatigue; later placement can turn power practice into slow conditioning.","zh":"它们需要高神经质量、速度、协调和低疲劳；放得太后会把功率训练变成慢速体能训练。"}},{"prompt":{"en":"What triggers the 2-for-2 progression?","zh":"什么情况触发 2-for-2 进阶？"},"answer":{"en":"At least two extra repetitions on the final set in two consecutive sessions, assuming sound technique and recovery.","zh":"连续两次训练的最后一组至少多完成 2 次，同时技术和恢复良好。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-19', 'en', 'Program Design and Technique for Plyometric Training', 'Explain the stretch-shortening cycle and coach safe landing, jumping, and upper-body plyometric technique.', '{"n":19,"title":{"en":"Program Design and Technique for Plyometric Training","zh":"增强式训练的计划设计与技术"},"domain":{"en":"Program Design / Exercise Technique","zh":"计划设计 / 运动技术"},"minutes":110,"source":"Essentials, 5th ed., Ch. 19 · DCO Program Design C · Exercise Technique B","objectives":[{"en":"Explain the stretch-shortening cycle and coach safe landing, jumping, and upper-body plyometric technique.","zh":"解释牵张-缩短循环并指导安全落地、跳跃和上肢增强式技术。"},{"en":"Prescribe intensity, volume, frequency, recovery, and progression from athlete readiness.","zh":"根据准备度设定强度、训练量、频率、恢复和进阶。"}],"sections":[{"id":"ssc","title":{"en":"Stretch-shortening cycle","zh":"牵张-缩短循环"},"explanation":["The stretch-shortening cycle links a rapid eccentric preload to an explosive concentric action. The eccentric phase stores elastic energy and activates sensory mechanisms; the amortization phase is the transition; the concentric phase expresses the resulting force. A long transition dissipates elastic energy and reduces potentiation.","Plyometric benefit depends on intent, stiffness regulation, landing skill, and task specificity—not simply jumping repeatedly."],"details":["Eccentric phase: rapid preload and energy storage.","Amortization: transition between eccentric and concentric actions; keep it appropriately brief.","Concentric phase: release stored energy plus active muscle force.","The SSC can be fast or slow depending on ground-contact duration and movement demands.","Greater intensity increases eccentric loading and readiness requirements."],"decision":{"en":"Choose a drill whose contact time, direction, and force demand match the target—not the most dramatic jump.","zh":"选择接触时间、方向和用力需求匹配目标的练习，而不是最炫目的跳跃。"},"examCue":{"en":"The amortization phase is the transition; excessive duration reduces SSC effectiveness.","zh":"缓冲阶段是过渡期；持续过长会降低 SSC 效果。"}},{"id":"technique","title":{"en":"Landing and takeoff technique","zh":"落地与起跳技术"},"explanation":["A safe landing distributes force through the forefoot-to-whole-foot contact, flexes ankles, knees, and hips, maintains trunk control, and keeps the knees tracking with the feet. The desired stiffness changes with the drill: depth jumps demand a short transition, whereas landing-to-stick drills deliberately emphasize absorption and position.","Quality ends the set. Loud contact, valgus collapse, loss of balance, slow ground contact, or inability to reach the target signal fatigue or excessive complexity."],"details":["Start from an athletic stance with the trunk organized and eyes directed to the task.","Land with the base appropriate to the jump and control frontal/transverse-plane motion.","Use arms deliberately: countermovement arm swing for performance, restricted arms only when the drill goal requires it.","For upper-body throws, establish safe wall/partner distance and never use a rebounding ball unless intended.","Depth-jump box height is not a badge of ability; use the lowest height that produces the desired response."],"decision":{"en":"Regress height, speed, direction, or reactivity until every repetition is controlled.","zh":"降低高度、速度、方向复杂度或反应性，直到每次重复都可控。"},"examCue":{"en":"Do not confuse a depth drop (land and absorb) with a depth jump (rapid rebound).","zh":"不要混淆深度落地（吸收）和深跳（快速反弹）。"}},{"id":"dose","title":{"en":"Intensity, volume, frequency, and recovery","zh":"强度、训练量、频率与恢复"},"explanation":["Plyometric intensity reflects stress on muscles, connective tissues, and joints. It rises with higher speed, greater height, unilateral contacts, added load, reduced contact time, and more demanding direction. Lower-body volume is often counted as foot contacts; upper-body volume as throws or catches.","Because the goal is power and elastic skill, recovery must protect output. Beginners use low-intensity drills and modest contacts; advanced athletes can tolerate more intense contacts but may need lower volume."],"details":["Common frequency is roughly two or three sessions per week with 48–72 hours between demanding sessions.","A work-to-rest ratio around 1:5 to 1:10 is common for high-quality power efforts.","Place plyometrics after the warm-up and before heavy fatigue-producing work.","Surface, footwear, landing area, space, ceiling, boxes, and medicine balls require inspection.","Avoid high-intensity lower-body plyometrics when pain, swelling, severe fatigue, or landing incompetence is present."],"decision":{"en":"Progress one lever at a time: pattern → direction → speed/reactivity → height/load → complexity.","zh":"每次只进阶一个杠杆：动作模式→方向→速度/反应性→高度/负荷→复杂度。"},"examCue":{"en":"Count contacts, but interpret them with intensity; 40 depth jumps are not equivalent to 40 line hops.","zh":"要统计触地次数，也要结合强度；40 次深跳不等于 40 次线跳。"}},{"id":"program","title":{"en":"Progressions and integration","zh":"进阶与整合"},"explanation":["A useful sequence is landing mechanics, low-level bilateral jumps, multidirectional hops, repeated jumps, bounds, and high-intensity reactive drills. Readiness depends on strength, balance, technique, body mass, training age, and injury history; no single screening number guarantees safety.","Complex training pairs a heavy resistance exercise with a biomechanically similar explosive movement to use post-activation performance enhancement. It requires sufficient strength, recovery, and precise intent."],"details":["Youth can perform age-appropriate plyometrics when instruction, supervision, surfaces, and dose are appropriate.","In-season doses often maintain qualities with fewer contacts.","Combine with sprint or resistance training without stacking excessive eccentric stress.","Track jump height or distance, contact time, reactive strength, and technique when useful.","Stop when output drops beyond the session purpose."],"decision":{"en":"Earn reactivity through consistent landing control and exposure tolerance.","zh":"通过稳定落地控制和暴露耐受性逐步获得反应能力。"},"examCue":{"en":"Plyometric readiness is multidimensional; a strength guideline informs judgment but does not replace technique assessment.","zh":"增强式准备度是多维的；力量指南可辅助判断但不能替代技术评估。"}}],"terms":[{"term":"Amortization phase","meaning":{"en":"Transition between eccentric and concentric actions in the SSC.","zh":"SSC 中离心与向心动作之间的过渡。"}},{"term":"Foot contact","meaning":{"en":"One landing/contact used to quantify lower-body plyometric volume.","zh":"用于量化下肢增强式训练量的一次落地/接触。"}},{"term":"Reactive strength","meaning":{"en":"Ability to rapidly switch from eccentric braking to concentric propulsion.","zh":"快速从离心制动转为向心推进的能力。"}},{"term":"Complex training","meaning":{"en":"Pairing a heavy resistance action with a similar explosive action.","zh":"把大负荷抗阻动作与相似的爆发动作配对。"}}],"formulas":[{"name":"Reactive strength index","expression":"jump height ÷ ground contact time","use":{"en":"Describe rebound performance when both height and contact time matter.","zh":"在高度和接触时间都重要时描述反弹表现。"}},{"name":"Work-to-rest ratio","expression":"work duration : recovery duration","use":{"en":"Protect repeated power quality; often about 1:5–1:10.","zh":"保护重复功率质量；常约为 1:5–1:10。"}}],"examChecklist":[{"en":"Name all three SSC phases and their coaching meaning.","zh":"说出 SSC 三阶段及其指导意义。"},{"en":"Differentiate landing, jump, hop, bound, and depth-jump demands.","zh":"区分落地、跳、单脚跳、跨步跳和深跳需求。"},{"en":"Prescribe contacts, recovery, frequency, and progression from readiness.","zh":"根据准备度设定触地量、恢复、频率和进阶。"}],"recall":[{"prompt":{"en":"What happens when amortization is too long?","zh":"缓冲期过长会怎样？"},"answer":{"en":"Stored elastic energy dissipates and the potentiating contribution to the concentric action falls.","zh":"储存的弹性能量会散失，对向心动作的增强作用下降。"}},{"prompt":{"en":"What ends a plyometric set?","zh":"增强式训练一组何时结束？"},"answer":{"en":"Loss of target output or movement quality—not merely reaching an arbitrary fatigue point.","zh":"当目标输出或动作质量下降时，而不是达到任意疲劳点。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-20', 'en', 'Program Design and Technique for Speed and Agility Training', 'Coach acceleration, maximum velocity, deceleration, change of direction, and reactive agility.', '{"n":20,"title":{"en":"Program Design and Technique for Speed and Agility Training","zh":"速度与敏捷训练的计划设计与技术"},"domain":{"en":"Program Design / Exercise Technique","zh":"计划设计 / 运动技术"},"minutes":130,"source":"Essentials, 5th ed., Ch. 20 · DCO Program Design C · Exercise Technique B","objectives":[{"en":"Coach acceleration, maximum velocity, deceleration, change of direction, and reactive agility.","zh":"指导加速、最大速度、减速、变向和反应敏捷。"},{"en":"Design high-quality speed sessions with appropriate work, rest, feedback, and progression.","zh":"用适当训练、休息、反馈和进阶设计高质量速度课。"}],"sections":[{"id":"speed","title":{"en":"Acceleration and maximum velocity","zh":"加速与最大速度"},"explanation":["Acceleration requires net horizontal impulse: a forward body angle, forceful backward push, progressive rise, and coordinated arm action. Maximum velocity uses a taller posture, elastic vertical force, short ground contacts, front-side mechanics, and minimal braking relative to the center of mass.","Stride length and frequency are outcomes of force, timing, anatomy, and skill. Artificially reaching farther forward often increases braking rather than speed."],"details":["Start position depends on sport but must permit projection without losing balance.","Acceleration steps rise gradually; do not force an immediate upright posture.","At top speed, strike under or near the body rather than reaching ahead.","Relax the face and shoulders while the arms move aggressively from the shoulder.","Full-speed sprinting is highly neural and should occur early in a session with long recovery."],"decision":{"en":"Coach the constraint causing lost velocity—projection, force direction, posture, contact location, rhythm, or relaxation.","zh":"针对导致速度损失的限制因素指导：投射、用力方向、姿势、触地点、节奏或放松。"},"examCue":{"en":"Acceleration emphasizes horizontal impulse; maximum velocity depends more on vertical force and brief contact.","zh":"加速更强调水平冲量；最大速度更依赖垂直力和短触地。"}},{"id":"deceleration","title":{"en":"Deceleration and change of direction","zh":"减速与变向"},"explanation":["Change of direction is preplanned; agility adds perception and a response to a stimulus. Before redirecting, the athlete must lower the center of mass, widen or reposition the base as needed, apply braking forces over one or more steps, control trunk momentum, plant appropriately, and reaccelerate.","The fastest entry speed is not always the fastest total maneuver. Effective athletes regulate entry speed so braking capacity matches the angle and time available."],"details":["Sharper angles generally require greater braking and more preparatory steps.","A plant too far from the center of mass can increase braking time and joint load.","Foot orientation should support the intended push direction without uncontrolled knee collapse.","Curved running differs from a discrete cut and should be trained separately.","Deceleration capacity should be built before maximal reactive cutting."],"decision":{"en":"Train the braking solution before asking for faster reacceleration.","zh":"先训练制动解决方案，再要求更快的再加速。"},"examCue":{"en":"Agility is not synonymous with change of direction; it includes perception, decision, and action.","zh":"敏捷不等于变向；它包含感知、决策和动作。"}},{"id":"perception","title":{"en":"Perception-action and drill transfer","zh":"感知-动作与练习迁移"},"explanation":["Closed drills teach positions and force application under predictable conditions. Open drills require the athlete to read relevant cues and act under uncertainty. Transfer improves when the information source, timing pressure, space, opponent behavior, and available actions resemble competition.","Cone patterns can teach foot placement, but memorizing a route does not by itself improve sport agility. Reactive drills should preserve genuine choices rather than use a decorative signal with only one possible response."],"details":["Use video, coach, partner, or small-sided game cues according to the sport.","Progress from simple stimulus-response rules to multiple realistic options.","Feedback can be external and outcome-based, then reduced as skill stabilizes.","Avoid overcoaching every step; allow self-organization around a clear goal.","Measure response time and movement time separately when diagnosing performance."],"decision":{"en":"Use closed practice to build a missing tool and open practice to teach when and how to use it.","zh":"用封闭练习建立缺失工具，用开放练习教会何时以及如何使用。"},"examCue":{"en":"A reactive light may test general response, but a sport opponent often provides more representative information.","zh":"反应灯可测一般反应，但专项对手通常提供更具代表性的信息。"}},{"id":"design","title":{"en":"Session design, dose, and safety","zh":"课次设计、剂量与安全"},"explanation":["Speed is trained with near-maximal intent and sufficient recovery. Short acceleration reps may need roughly one minute or more between efforts; maximal-velocity sprints often need several minutes. Work-to-rest prescriptions depend on distance, phase, athlete, and goal, but visible velocity loss means the session is no longer training the same quality.","A logical order is dynamic warm-up, movement preparation, acceleration or max velocity, agility/COD, then secondary conditioning or strength as the plan requires."],"details":["Use timing gates or consistent split methods when possible.","Progress distance, intensity, number of reps, direction complexity, and decision demand gradually.","Inspect surface, footwear, runway, weather, walls, and athlete traffic.","Do not conduct maximal sprinting without adequate preparation after a long layoff.","Hamstring or tendon symptoms, dizziness, and acute pain require stopping and appropriate evaluation."],"decision":{"en":"End high-speed work while the athlete is still practicing speed, not merely surviving repetitions.","zh":"在运动员仍在练速度而不是勉强撑过重复时结束高速训练。"},"examCue":{"en":"Long recovery is part of speed training; shortening rest changes the stimulus toward conditioning.","zh":"长休息是速度训练的一部分；缩短休息会把刺激转向体能。"}}],"terms":[{"term":"Acceleration","meaning":{"en":"Rate of change in velocity.","zh":"速度随时间的变化率。"}},{"term":"Change of direction","meaning":{"en":"Preplanned redirection of movement.","zh":"预先计划的移动方向改变。"}},{"term":"Agility","meaning":{"en":"Rapid whole-body movement in response to a stimulus.","zh":"对刺激作出反应的快速全身动作。"}},{"term":"Braking impulse","meaning":{"en":"Force applied over time to reduce momentum.","zh":"在一段时间内施力以降低动量。"}}],"formulas":[{"name":"Average acceleration","expression":"(final velocity − initial velocity) ÷ time","use":{"en":"Quantify the rate of velocity change.","zh":"量化速度变化率。"}},{"name":"Momentum","expression":"mass × velocity","use":{"en":"Explain why faster or heavier athletes require greater braking impulse.","zh":"解释为何更快或更重的运动员需要更大制动冲量。"}}],"examChecklist":[{"en":"Differentiate acceleration and maximum-velocity mechanics.","zh":"区分加速与最大速度技术。"},{"en":"Differentiate COD and agility.","zh":"区分变向和敏捷。"},{"en":"Prescribe rest that preserves sprint quality.","zh":"设定能保持冲刺质量的休息。"},{"en":"Progress from braking skill to reactive sport tasks.","zh":"从制动技术进阶到反应性专项任务。"}],"recall":[{"prompt":{"en":"Why can reaching forward reduce sprint speed?","zh":"为什么向前跨得过远会降低冲刺速度？"},"answer":{"en":"It often places the foot ahead of the center of mass, increasing braking impulse and contact time.","zh":"它常使脚落在质心前方，增加制动冲量和触地时间。"}},{"prompt":{"en":"What separates agility from COD?","zh":"敏捷与变向的区别是什么？"},"answer":{"en":"Agility includes perception and a response to an external stimulus; COD is preplanned.","zh":"敏捷包含感知和对外部刺激的反应；变向是预先计划的。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-21', 'en', 'Program Design and Technique for Aerobic Endurance Training', 'Prescribe mode, frequency, duration, and intensity using heart rate, pace, power, RPE, and thresholds.', '{"n":21,"title":{"en":"Program Design and Technique for Aerobic Endurance Training","zh":"有氧耐力训练的计划设计与技术"},"domain":{"en":"Program Design / Exercise Technique","zh":"计划设计 / 运动技术"},"minutes":125,"source":"Essentials, 5th ed., Ch. 21 · DCO Program Design D · Exercise Technique B","objectives":[{"en":"Prescribe mode, frequency, duration, and intensity using heart rate, pace, power, RPE, and thresholds.","zh":"利用心率、配速、功率、RPE 和阈值设定方式、频率、时长与强度。"},{"en":"Program long slow distance, pace/tempo, interval, repetition, and fartlek training.","zh":"设计长距离慢速、配速/节奏、间歇、重复和法特莱克训练。"}],"sections":[{"id":"prescription","title":{"en":"Needs analysis and FITT-VP prescription","zh":"需求分析与 FITT-VP 处方"},"explanation":["Aerobic programming begins with event duration, movement mode, intensity distribution, terrain, environmental demands, work-to-rest pattern, and interference with strength/power. Athlete analysis includes training history, current volume, recent performance, threshold markers, injury risk, preferences, and schedule.","FITT-VP organizes frequency, intensity, time, type, volume, and progression. Mode should respect specificity but can use cross-training to manage impact or maintain fitness."],"details":["Frequency is constrained by session stress and recovery, not a universal weekly number.","Duration and intensity combine to determine internal and external load.","Use the least disruptive mode when aerobic work supports a strength/power sport.","Track acute responses and the rolling trend rather than reacting to one unusual day.","Increase load progressively; large sudden changes in running volume or intensity raise tissue stress."],"decision":{"en":"Prescribe the minimum endurance dose that develops the needed system without displacing higher-priority adaptations.","zh":"设定能发展目标系统且不挤占更高优先适应的最小耐力剂量。"},"examCue":{"en":"Mode is part of specificity: swimming fitness does not perfectly replace running economy and tissue tolerance.","zh":"方式是专项性的一部分：游泳体能不能完全替代跑步经济性和组织耐受性。"}},{"id":"intensity","title":{"en":"Intensity zones and monitoring","zh":"强度区间与监控"},"explanation":["Intensity can be prescribed with percentage of maximal heart rate, heart-rate reserve, oxygen uptake reserve, pace, power, blood-lactate landmarks, ventilatory thresholds, talk test, or RPE. Heart-rate reserve accounts for resting heart rate and usually maps more closely to oxygen uptake reserve than percent maximal heart rate.","Each method has error. Heat, dehydration, altitude, fatigue, medication, caffeine, and cardiac drift can change heart rate at the same external workload."],"details":["Low intensity supports volume and recovery; threshold work targets sustainable high fractional intensity; VO2-focused intervals stress central and peripheral oxygen delivery/use.","RPE and talk test are valuable when heart rate is distorted or devices are unavailable.","Pace and power show external output; heart rate and RPE show internal cost.","Use threshold testing definitions consistently; different protocols produce different landmarks.","Re-test only often enough that prescription remains accurate and the testing cost is justified."],"decision":{"en":"Triangulate external output, heart rate, and perceived effort rather than trusting one number blindly.","zh":"综合外部输出、心率和主观用力，不盲信单一数字。"},"examCue":{"en":"Karvonen uses heart-rate reserve, then adds resting heart rate back.","zh":"Karvonen 法使用心率储备，最后再加回静息心率。"}},{"id":"methods","title":{"en":"Training methods","zh":"训练方法"},"explanation":["Long slow distance develops aerobic base and fatigue resistance at an intensity below competition pace. Pace or tempo training uses continuous or interval work near the target sustainable intensity. Aerobic intervals alternate work and recovery to accumulate time at a high oxygen demand. Repetition training is typically faster with longer recovery and greater anaerobic contribution. Fartlek varies pace and terrain continuously.","The method is defined by intensity, duration, and recovery—not by the label alone."],"details":["Long slow distance: high duration, low-to-moderate intensity.","Tempo/threshold: controlled discomfort near a sustainable threshold region.","Aerobic intervals: repeated high-intensity bouts with incomplete but sufficient recovery.","Repetitions: fast work with more complete recovery to preserve speed.","Fartlek: unstructured or structured changes in pace, useful for variety and terrain specificity."],"decision":{"en":"Choose the method that accumulates high-quality time in the physiological and mechanical zone required by the event.","zh":"选择能在项目所需生理与机械区间积累高质量时间的方法。"},"examCue":{"en":"Shortening recovery or lengthening work changes the dominant demand even when the exercise stays the same.","zh":"即使动作不变，缩短恢复或延长工作也会改变主要需求。"}},{"id":"season","title":{"en":"Progression, taper, environment, and concurrent training","zh":"进阶、减量、环境与并行训练"},"explanation":["Build a base of tolerable volume, then introduce event-specific intensity, competition-pace practice, and strategic recovery. Taper reduces training load—usually volume more than intensity—to dissipate fatigue while retaining fitness. Abrupt cessation can reduce readiness.","Concurrent endurance and strength training can interfere when high volumes, similar muscle groups, poor sequencing, and inadequate recovery compete for adaptation. Separate demanding sessions when possible and prioritize the quality that matters most."],"details":["Acclimatize progressively to heat or altitude and adjust pace expectations.","Hydration and carbohydrate availability become more important with longer or hotter sessions.","In-season plans often maintain intensity with reduced volume around competition.","Return from interruption with conservative volume and impact exposure.","Monitor pain, unusual breathlessness, chest symptoms, heat illness signs, and excessive fatigue."],"decision":{"en":"Protect key sessions by spacing incompatible stressors and reducing low-priority volume.","zh":"通过错开不相容压力并减少低优先训练量来保护关键课。"},"examCue":{"en":"A taper is a planned load reduction, not complete rest; volume commonly falls while some intensity remains.","zh":"减量是计划性降低负荷，不是完全休息；训练量通常下降，但保留部分强度。"}}],"terms":[{"term":"Heart-rate reserve","meaning":{"en":"Maximal heart rate minus resting heart rate.","zh":"最大心率减静息心率。"}},{"term":"Cardiac drift","meaning":{"en":"Progressive heart-rate rise during prolonged steady work despite stable output.","zh":"长时间稳定输出中出现的心率逐渐上升。"}},{"term":"Threshold","meaning":{"en":"A physiological landmark associated with a nonlinear change in ventilation or lactate behavior.","zh":"与通气或乳酸行为非线性变化相关的生理标志。"}},{"term":"Taper","meaning":{"en":"Planned reduction in training load before important performance.","zh":"重大表现前计划性降低训练负荷。"}}],"formulas":[{"name":"Heart-rate reserve","expression":"HRmax − HRrest","use":{"en":"Calculate Karvonen target heart rate.","zh":"计算 Karvonen 目标心率。"}},{"name":"Target heart rate","expression":"(HRmax − HRrest) × intensity + HRrest","use":{"en":"Prescribe intensity from heart-rate reserve.","zh":"用心率储备设定强度。"},"example":"(190 − 60) × 0.70 + 60 = 151 bpm"},{"name":"Running pace","expression":"time ÷ distance","use":{"en":"Convert performance time to target split pace.","zh":"把表现时间换算为目标分段配速。"}}],"examChecklist":[{"en":"Use FITT-VP and a sport/athlete needs analysis.","zh":"使用 FITT-VP 和专项/运动员需求分析。"},{"en":"Calculate HRR target heart rate correctly.","zh":"正确计算 HRR 目标心率。"},{"en":"Differentiate endurance training methods by intensity and recovery.","zh":"按强度和恢复区分耐力训练方法。"},{"en":"Manage taper, environment, and concurrent interference.","zh":"管理减量、环境和并行训练干扰。"}],"recall":[{"prompt":{"en":"Why add resting heart rate back in Karvonen?","zh":"为什么 Karvonen 公式最后加回静息心率？"},"answer":{"en":"The target percentage is applied to the reserve above rest, then returned to the person''s absolute heart-rate scale.","zh":"目标百分比作用于静息以上的储备，然后回到个人绝对心率尺度。"}},{"prompt":{"en":"What usually changes most during a taper?","zh":"减量期通常哪个变量变化最大？"},"answer":{"en":"Training volume falls substantially while enough intensity and frequency are retained to preserve readiness.","zh":"训练量显著下降，同时保留足够强度和频率以维持准备度。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-22', 'en', 'Periodization', 'Build annual, mesocycle, and microcycle plans that sequence compatible adaptations and competition readiness.', '{"n":22,"title":{"en":"Periodization","zh":"周期化"},"domain":{"en":"Program Design","zh":"计划设计"},"minutes":140,"source":"Essentials, 5th ed., Ch. 22 · DCO Program Design E-F","objectives":[{"en":"Build annual, mesocycle, and microcycle plans that sequence compatible adaptations and competition readiness.","zh":"构建年度、中周期与微周期计划，排序相容适应与比赛准备。"},{"en":"Manipulate volume, intensity, specificity, and recovery across preparatory, competitive, and transition periods.","zh":"在准备期、比赛期和过渡期调整训练量、强度、专项性与恢复。"}],"sections":[{"id":"hierarchy","title":{"en":"Periodization hierarchy and phase logic","zh":"周期化层级与阶段逻辑"},"explanation":["Periodization is planned variation of training to manage fatigue and develop performance at the required time. The macrocycle covers the long plan, mesocycles organize multiweek emphases, and microcycles organize short repeating units, often a week. Individual sessions and exercise prescriptions live inside this hierarchy.","Traditional phase names are less important than their function. Preparatory periods build work capacity and foundational qualities; competitive periods express and maintain sport performance; transition periods provide physical and psychological recovery."],"details":["Begin with competition dates, schedule density, travel, testing, and athlete constraints.","Work backward from performance demands while preserving enough time to acquire each adaptation.","Accumulation emphasizes volume and general capacity; intensification raises specificity and intensity; realization reduces fatigue and expresses performance.","Maintenance dose is usually smaller than development dose.","No plan survives unchanged; monitoring informs adjustment without abandoning the long-term direction."],"decision":{"en":"Every phase must state what is developed, what is maintained, and what fatigue cost is acceptable.","zh":"每个阶段都要明确发展什么、维持什么以及可接受的疲劳成本。"},"examCue":{"en":"Macrocycle is longest; mesocycle is a multiweek block; microcycle is the short repeating unit.","zh":"大周期最长；中周期是数周训练块；微周期是短期重复单元。"}},{"id":"models","title":{"en":"Linear, undulating, and block models","zh":"线性、波动与模块模型"},"explanation":["Linear or traditional plans generally move from higher volume/lower intensity toward lower volume/higher intensity. Undulating plans vary volume and intensity more frequently—daily or weekly. Block plans concentrate compatible qualities in sequenced blocks. These are organizing strategies, not guarantees of superiority.","Choose a model from athlete level, competition frequency, number of qualities, time available, and response. Team sports with weekly games often require flexible microcycles; a single championship event may allow a longer build and taper."],"details":["Avoid changing so many variables that adaptation and monitoring become unclear.","Residual effects allow some qualities to be maintained after the main emphasis shifts, but decay rates differ.","Strength and power often coexist; excessive endurance volume may conflict with high-force goals.","Use planned variation to reduce monotony and manage fatigue, not novelty for its own sake.","A deload is a local reduction in stress; a taper prepares for peak performance."],"decision":{"en":"Use the simplest model that solves the calendar and adaptation problem.","zh":"使用能解决赛历与适应问题的最简单模型。"},"examCue":{"en":"Undulating periodization changes load/volume more frequently; linear plans change them more gradually across phases.","zh":"波动周期化更频繁改变负荷/训练量；线性计划跨阶段更逐步变化。"}},{"id":"annual","title":{"en":"Annual plan and competition microcycle","zh":"年度计划与比赛微周期"},"explanation":["Map competitions by priority, then place testing, general preparation, specific preparation, precompetition, competition, taper, and transition. Within each week, position high-neural and high-eccentric sessions far enough from competition to recover, and coordinate field, court, conditioning, and lifting stress.","Session RPE, wellness, jump/sprint measures, performance, and medical information can guide adjustment. A single low score is context; converging trends plus performance change deserve action."],"details":["High/low organization groups demanding stressors and preserves true recovery days.","During congested schedules, reduce volume and maintain selected intensity exposures.","Bench players may need top-up conditioning; starters may need recovery.","Travel, sleep disruption, exams, work, and climate change usable training capacity.","After the season, address injuries, restore variability, and retain enough activity to limit detraining."],"decision":{"en":"Plan total athlete stress, not just weight-room stress.","zh":"规划运动员总压力，而不仅是力量房压力。"},"examCue":{"en":"The correct in-season answer often maintains quality with lower volume rather than adding fatigue.","zh":"赛季中正确答案通常是降低训练量维持能力，而不是增加疲劳。"}},{"id":"taper","title":{"en":"Peaking, tapering, and plan adjustment","zh":"巅峰、减量与计划调整"},"explanation":["Peaking is the temporary expression of the highest performance at the priority time. A taper reduces accumulated fatigue while preserving the adaptations and technical feel required for competition. Volume usually falls substantially, while some intensity and sport-specific frequency remain.","Plans are hypotheses. Use performance, fatigue, schedule changes, athlete feedback, and medical information to adjust the next dose while preserving the phase objective."],"details":["Reduce volume by cutting sets, repetitions, or session duration before automatically eliminating intensity.","Maintain enough event-specific exposure that coordination and confidence remain sharp.","Athletes carrying more fatigue may need a longer or larger taper.","Avoid novel high-soreness exercises near the target event.","After the peak, use transition and re-entry periods to restore recovery and rebuild load tolerance."],"decision":{"en":"Remove fatigue while retaining the minimum dose needed for readiness and confidence.","zh":"消除疲劳，同时保留维持准备度与信心所需的最小剂量。"},"examCue":{"en":"A taper is not total rest: volume declines most, while selected intensity and specificity remain.","zh":"减量不是完全休息：训练量下降最多，同时保留部分强度与专项性。"}}],"terms":[{"term":"Macrocycle","meaning":{"en":"The longest planning period, often an annual or multimonth plan.","zh":"最长计划周期，常为年度或数月计划。"}},{"term":"Mesocycle","meaning":{"en":"A multiweek training block with a defined emphasis.","zh":"具有明确重点的数周训练块。"}},{"term":"Microcycle","meaning":{"en":"A short repeating planning unit, commonly about one week.","zh":"短期重复计划单元，通常约一周。"}},{"term":"Peaking","meaning":{"en":"Planned temporary maximization of performance for a priority event.","zh":"为重点赛事计划性暂时最大化表现。"}}],"formulas":[{"name":"Session training load","expression":"session RPE × session duration (min)","use":{"en":"Simple internal-load estimate for trend monitoring.","zh":"用于趋势监控的简易内部负荷估算。"},"example":"RPE 6 × 75 min = 450 AU"},{"name":"Acute change","expression":"(current − baseline) ÷ baseline × 100","use":{"en":"Describe change while avoiding a single metric as a clearance rule.","zh":"描述变化，但不能把单一指标当作回归许可规则。"}}],"examChecklist":[{"en":"Identify macro-, meso-, and microcycle decisions.","zh":"识别大、中、微周期决策。"},{"en":"Compare linear, undulating, and block organization.","zh":"比较线性、波动和模块组织。"},{"en":"Build a taper that reduces fatigue without erasing readiness.","zh":"建立降低疲劳但不损失准备度的减量。"},{"en":"Adjust in-season volume around competition while maintaining priority qualities.","zh":"围绕比赛调整赛季内训练量并维持优先能力。"}],"recall":[{"prompt":{"en":"What is the difference between a deload and taper?","zh":"减载与减量有什么区别？"},"answer":{"en":"A deload manages fatigue within training; a taper specifically reduces load before a priority performance while retaining fitness and readiness.","zh":"减载是在训练中管理疲劳；减量是在重要表现前专门降低负荷，同时保留体能和准备度。"}},{"prompt":{"en":"Why usually reduce volume more than intensity during a taper?","zh":"为什么减量期通常训练量下降多于强度？"},"answer":{"en":"Lower volume dissipates fatigue, while selected intensity preserves neural, technical, and event-specific readiness.","zh":"降低训练量可消除疲劳，而保留部分强度有助于维持神经、技术与专项准备度。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-23', 'en', 'Rehabilitation and Reconditioning', 'Explain tissue-healing stages and program training within the healthcare team''s restrictions.', '{"n":23,"title":{"en":"Rehabilitation and Reconditioning","zh":"康复与再训练"},"domain":{"en":"Program Design / Program Implementation","zh":"计划设计 / 计划实施"},"minutes":115,"source":"Essentials, 5th ed., Ch. 23 · DCO Program Design F · Program Implementation D","objectives":[{"en":"Explain tissue-healing stages and program training within the healthcare team''s restrictions.","zh":"解释组织愈合阶段，并在医疗团队限制内设计训练。"},{"en":"Progress from protected capacity to full sport exposure using criteria, load tolerance, and communication.","zh":"依据标准、负荷耐受和沟通，从保护性能力进阶到完整专项暴露。"}],"sections":[{"id":"team","title":{"en":"Scope, team roles, and communication","zh":"执业范围、团队角色与沟通"},"explanation":["Rehabilitation is an interdisciplinary process. Physicians and other qualified clinicians diagnose, treat, and provide medical restrictions or clearance. Athletic trainers and physical therapists manage clinical rehabilitation within their scope. The strength and conditioning professional communicates training demands, maintains safe fitness, and restores performance capacities after or alongside clinical care.","The athlete should not receive conflicting messages. Use shared terminology, document objective responses, and escalate changes in pain, swelling, neurologic status, wound condition, medication effects, or function."],"details":["Never diagnose an injury from a movement screen or strength test.","Obtain the current restriction, allowed range, loading limit, and progression criteria in writing when possible.","Report what was performed, dose, technique, symptoms during/after, and next-day response.","Protect health information and discuss only what is required for care and safety.","Emergency symptoms take priority over the workout and require the emergency action plan."],"decision":{"en":"When the restriction is unclear, pause the questionable exposure and contact the responsible clinician.","zh":"限制不清时，暂停有疑问的暴露并联系负责临床人员。"},"examCue":{"en":"The CSCS contributes performance expertise but does not independently diagnose, prescribe treatment, or give medical clearance.","zh":"CSCS 提供表现训练专长，但不独立诊断、治疗或给予医疗许可。"}},{"id":"healing","title":{"en":"Tissue healing and loading logic","zh":"组织愈合与负荷逻辑"},"explanation":["Healing is often described as inflammation, repair/proliferation, and remodeling. These stages overlap. Early protection limits additional damage while safe movement may preserve circulation and capacity. During repair, new tissue is immature and loading must be carefully dosed. Remodeling aligns and strengthens tissue over time in response to progressive stress.","Different tissues and injuries heal at different rates. Pain, calendar time, or imaging alone cannot describe readiness; combine medical guidance, function, symptoms, load response, and sport demands."],"details":["Inflammation includes vascular and cellular responses that begin repair; excessive swelling or worsening symptoms require review.","Repair forms new matrix and tissue that initially has limited tensile capacity.","Remodeling can continue for months as tissue responds to graded mechanical loading.","Muscle, tendon, ligament, bone, cartilage, and nerve have different vascularity and loading behavior.","Too little stress can underprepare tissue; too much, too soon can exceed capacity."],"decision":{"en":"Apply the highest safe dose that supports adaptation without causing an unacceptable symptom or function response.","zh":"使用能促进适应、又不会引起不可接受症状或功能反应的最高安全剂量。"},"examCue":{"en":"Healing phases overlap; progression is criteria- and response-based, not a rigid calendar alone.","zh":"愈合阶段相互重叠；进阶依据标准和反应，而非仅靠固定时间表。"}},{"id":"progression","title":{"en":"From capacity to sport performance","zh":"从基础能力到专项表现"},"explanation":["Reconditioning moves from tolerated range and isometric or slow control toward full range, strength, hypertrophy where needed, eccentric capacity, rate of force development, energy-system work, and sport-specific speed and decision demands. The exact order changes with tissue, athlete, and sport.","Progress exposure across multiple dimensions: volume, intensity, velocity, range, impact, direction, fatigue, unpredictability, opponent contact, and frequency. A drill may be easy in one dimension and demanding in another."],"details":["Maintain unaffected limbs and general conditioning when approved, including cross-education benefits from contralateral training.","Restore movement options before repeatedly testing the most provocative task.","Add running from submaximal linear exposure to higher speed, deceleration, change of direction, reactive work, and full practice.","Practice participation, competition minutes, and between-event recovery are separate progression steps.","Compare with preinjury and positional demands, not only an uninjured-side ratio."],"decision":{"en":"Progress when the current exposure is technically sound, meets criteria, and produces an acceptable immediate and delayed response.","zh":"当前暴露技术稳定、满足标准并产生可接受的即时与延迟反应时才进阶。"},"examCue":{"en":"Passing a strength test does not prove tolerance for repeated fatigue, chaos, contact, or competition volume.","zh":"通过力量测试并不证明能耐受重复疲劳、混乱、接触或比赛量。"}},{"id":"redflags","title":{"en":"Monitoring, setbacks, and red flags","zh":"监控、反复与危险信号"},"explanation":["Track symptoms, swelling, range, force, movement quality, confidence, workload, and next-day response. A small expected response may be acceptable under the clinician''s plan; a worsening pattern, loss of function, or systemic sign requires reassessment. Do not hide symptoms to meet a date.","Psychological readiness matters. Fear, low confidence, and threat interpretation can change movement and participation. Support graded success and refer mental-health concerns to appropriate professionals."],"details":["Stop immediately for chest pain, syncope, severe breathlessness, acute neurologic change, suspected fracture/dislocation, uncontrolled bleeding, or signs of heat stroke.","Persistent night pain, fever, unexplained systemic symptoms, or rapidly worsening swelling require medical review.","A setback is data: identify whether the dose, technique, recovery, or underlying condition changed.","Document decisions and communication after adverse responses.","Do not use analgesics or anti-inflammatory medication advice outside professional scope."],"decision":{"en":"Health and function override the planned session; refer whenever findings exceed your scope or the agreed response boundary.","zh":"健康和功能优先于计划课次；超出范围或约定反应界限时必须转诊。"},"examCue":{"en":"The first action in a dangerous presentation is safety/EAP activation, not completing an assessment battery.","zh":"出现危险表现时首先保障安全/启动 EAP，而不是继续完成测试。"}}],"terms":[{"term":"Reconditioning","meaning":{"en":"Restoration of physical capacities needed to return to full performance.","zh":"恢复回归完整表现所需的身体能力。"}},{"term":"Remodeling","meaning":{"en":"Long-term reorganization and strengthening of healing tissue under appropriate stress.","zh":"愈合组织在适当压力下长期重组和强化。"}},{"term":"Criteria-based progression","meaning":{"en":"Advancement based on defined function and response, not time alone.","zh":"依据明确功能与反应而非单靠时间进阶。"}},{"term":"Cross-education","meaning":{"en":"Strength gain in an untrained limb after training the opposite limb.","zh":"训练一侧肢体后未训练侧也出现力量提升。"}}],"formulas":[{"name":"Limb symmetry index","expression":"involved limb ÷ comparison limb × 100","use":{"en":"One descriptive measure; interpret with measurement error, dominance, preinjury data, and sport demands.","zh":"一种描述指标；需结合测量误差、优势侧、伤前数据和专项需求解释。"},"example":"90 N ÷ 100 N = 90%"}],"examChecklist":[{"en":"Separate medical and performance-team responsibilities.","zh":"区分医疗与表现团队职责。"},{"en":"Explain inflammation, repair, and remodeling without treating them as isolated dates.","zh":"解释炎症、修复和重塑且不把它们视为孤立日期。"},{"en":"Progress every exposure dimension deliberately.","zh":"有意识地进阶每个暴露维度。"},{"en":"Recognize stop-and-refer red flags.","zh":"识别必须停止并转诊的危险信号。"}],"recall":[{"prompt":{"en":"Why is 90% limb symmetry not automatic clearance?","zh":"为什么 90% 肢体对称性不等于自动许可？"},"answer":{"en":"The comparison limb may be detrained, the test has error, and symmetry does not measure fatigue, speed, chaos, confidence, or sport workload.","zh":"对侧也可能退化，测试存在误差，而且对称性不能测量疲劳、速度、混乱、信心或专项负荷。"}},{"prompt":{"en":"What determines progression after injury?","zh":"伤后进阶由什么决定？"},"answer":{"en":"Medical restrictions plus defined performance criteria and an acceptable immediate and next-day response to the current exposure.","zh":"医疗限制、明确的表现标准，以及对当前暴露可接受的即时和次日反应。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-24', 'en', 'Overreaching, Overtraining, and Recovery', 'Differentiate acute fatigue, functional and nonfunctional overreaching, the overtraining process, and overtraining syndrome.', '{"n":24,"title":{"en":"Overreaching, Overtraining, and Recovery","zh":"过度训练、过度负荷与恢复"},"domain":{"en":"Program Design / Program Implementation","zh":"计划设计 / 计划实施"},"minutes":120,"source":"Essentials, 5th ed., Ch. 24 · DCO Program Design E · Program Implementation A-D","objectives":[{"en":"Differentiate acute fatigue, functional and nonfunctional overreaching, the overtraining process, and overtraining syndrome.","zh":"区分急性疲劳、功能性与非功能性过度负荷、过度训练过程和过度训练综合征。"},{"en":"Identify contributors, monitor underperformance, and select evidence-based recovery strategies.","zh":"识别促成因素、监控表现下降并选择循证恢复策略。"}],"sections":[{"id":"continuum","title":{"en":"The fatigue-to-overtraining continuum","zh":"从疲劳到过度训练的连续谱"},"explanation":["Acute fatigue is an expected short-lived response to training. Functional overreaching is a planned, temporary performance reduction followed by recovery and supercompensation over days to a few weeks. Nonfunctional overreaching produces a longer decrement without the intended performance benefit. Overtraining is the excessive training process; overtraining syndrome is the prolonged maladaptive outcome and is diagnosed only after other causes are excluded.","Time course, performance outcome, and clinical exclusion distinguish these states more than a single biomarker. Terminology matters because calling every hard week ''overtraining'' hides the real problem."],"details":["Functional overreaching can be useful when recovery is deliberately programmed.","Nonfunctional overreaching can take weeks to months to resolve and disrupts the plan.","Overtraining syndrome may take months or longer and involves multiple systems.","The general adaptation syndrome is a model—alarm, resistance/adaptation, exhaustion—not an exact schedule.","The clearest common feature is persistent unexplained underperformance."],"decision":{"en":"Treat a planned short performance dip differently from a persistent decline that does not resolve with normal recovery.","zh":"区别对待计划内的短期下降和正常恢复后仍持续的表现下降。"},"examCue":{"en":"Overtraining is the process; overtraining syndrome is the prolonged outcome.","zh":"过度训练是过程；过度训练综合征是长期结果。"}},{"id":"causes","title":{"en":"Contributors and differential diagnosis","zh":"促成因素与鉴别"},"explanation":["Total stress includes training volume and intensity, competition, travel, sleep loss, low energy or carbohydrate availability, illness, heat, altitude, academic or work stress, and interpersonal strain. Monotonous loading and insufficient recovery can raise risk, but no single workload ratio diagnoses overtraining syndrome.","Underperformance has many alternatives: infection, anemia or iron deficiency, endocrine or cardiac disease, medication effects, injury, technical changes, mood disorder, inadequate nutrition, and unrealistic testing conditions. Persistent decline requires medical collaboration."],"details":["Rapid increases in training or competition density can exceed current recovery capacity.","Low energy availability can impair performance, hormones, bone, immunity, and recovery.","Psychological and social stress add to allostatic load even when the workout is unchanged.","Strength, sprint, power, coordination, and mood may change before resting clinical markers.","Rule out medical, nutritional, and psychological causes rather than assuming poor motivation."],"decision":{"en":"When underperformance persists or includes systemic symptoms, reduce stress and refer for appropriate evaluation.","zh":"表现下降持续或伴系统性症状时，降低压力并转诊评估。"},"examCue":{"en":"Not all underperformance is overtraining; exclusion of other causes is essential.","zh":"并非所有表现下降都是过度训练；排除其他原因至关重要。"}},{"id":"monitor","title":{"en":"Assessment and early warning","zh":"评估与早期预警"},"explanation":["Monitor performance with stable, low-cost measures related to the sport, then combine trends in wellness, sleep, soreness, mood, illness, resting physiology, and training load. No hormone, heart-rate, questionnaire, or workload metric is sufficiently sensitive and specific by itself.","The athlete''s own baseline is usually more informative than population cutoffs. Standardize timing and conditions and respond to converging signals rather than one noisy point."],"details":["Track the planned load and the load actually completed.","Use submaximal performance or neuromuscular tests that do not add excessive fatigue.","Record persistent mood disturbance, loss of vigor, sleep disruption, unusual soreness, and frequent illness.","Investigate performance decline across several sessions, especially when effort feels harder at the same output.","Maintain honest reporting by avoiding punishment for a low readiness score."],"decision":{"en":"Use a dashboard of independent signals and predefined action rules, not a magic number.","zh":"使用多个独立信号和预设行动规则，而不是寻找神奇数字。"},"examCue":{"en":"Performance plus subjective measures is often more useful than isolated biochemical testing.","zh":"表现加主观指标通常比孤立生化检测更实用。"}},{"id":"recovery","title":{"en":"Recovery and return to productive training","zh":"恢复与回归有效训练"},"explanation":["Recovery begins with matching stress to capacity: periodized loading, deloads, adequate sleep, sufficient energy and carbohydrate, hydration, rest days, and management of nontraining stress. Passive modalities may improve comfort but cannot compensate for chronic overload or inadequate sleep and nutrition.","If nonfunctional overreaching or overtraining syndrome is suspected, substantially reduce or stop the offending load, involve healthcare professionals, treat contributing problems, and return gradually only after symptoms and performance improve."],"details":["Sleep opportunity and consistency are foundational.","Refuel carbohydrate and protein according to workload; correct low energy availability.","Active recovery should be genuinely easy and not become another conditioning session.","Massage, compression, water immersion, and temperature strategies may have context-specific effects.","Rebuild frequency, volume, then demanding intensity while monitoring relapse."],"decision":{"en":"Fix the load-recovery mismatch before adding recovery gadgets.","zh":"先解决负荷与恢复失配，再考虑恢复工具。"},"examCue":{"en":"The first-line prevention is appropriate program design plus sleep and nutrition, not a single modality or supplement.","zh":"首要预防是合理计划加睡眠营养，而非单一恢复方式或补剂。"}}],"terms":[{"term":"Functional overreaching","meaning":{"en":"Planned short performance decrement followed by recovery and improved performance.","zh":"计划性短期表现下降，恢复后表现提升。"}},{"term":"Nonfunctional overreaching","meaning":{"en":"Prolonged maladaptation without the intended performance benefit.","zh":"无预期表现收益的长期不良适应。"}},{"term":"Overtraining syndrome","meaning":{"en":"Prolonged underperformance and maladaptation after excessive stress, diagnosed after excluding other causes.","zh":"过度压力后的长期表现下降与不良适应，需排除其他原因后诊断。"}},{"term":"Allostatic load","meaning":{"en":"Cumulative cost of adapting to training and nontraining stressors.","zh":"适应训练与非训练压力的累积代价。"}}],"formulas":[{"name":"Monotony","expression":"mean daily load ÷ standard deviation of daily load","use":{"en":"Describe lack of day-to-day load variation; interpret cautiously with other data.","zh":"描述每日负荷缺乏变化；需结合其他数据谨慎解释。"}},{"name":"Strain","expression":"weekly load × monotony","use":{"en":"Historical workload summary, not a standalone injury predictor.","zh":"历史工作负荷汇总，并非独立伤病预测器。"}}],"examChecklist":[{"en":"Differentiate fatigue, functional OR, nonfunctional OR, OT, and OTS.","zh":"区分疲劳、功能性 OR、非功能性 OR、OT 与 OTS。"},{"en":"List training and nontraining contributors to allostatic load.","zh":"列出增加累积压力的训练与非训练因素。"},{"en":"Explain why no single marker diagnoses OTS.","zh":"解释为何没有单一指标可诊断 OTS。"},{"en":"Prioritize load correction, sleep, nutrition, and referral.","zh":"优先纠正负荷、睡眠、营养并适时转诊。"}],"recall":[{"prompt":{"en":"How does functional overreaching differ from nonfunctional overreaching?","zh":"功能性与非功能性过度负荷有何区别？"},"answer":{"en":"Functional OR resolves relatively quickly and can produce supercompensation; nonfunctional OR causes a longer decrement without the planned benefit.","zh":"功能性 OR 较快恢复并可能超量补偿；非功能性 OR 造成更长下降且无计划收益。"}},{"prompt":{"en":"Why can no single marker diagnose overtraining syndrome?","zh":"为什么单一指标不能诊断过度训练综合征？"},"answer":{"en":"Responses are individual and nonspecific; OTS is identified from persistent underperformance, multiple signs, time course, and exclusion of other causes.","zh":"反应具有个体性且非特异；OTS 需结合持续表现下降、多种信号、时间过程并排除其他原因。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-25', 'en', 'Facility Design, Layout, and Organization', 'Plan a safe strength and conditioning facility from program needs, traffic, equipment, space, and access.', '{"n":25,"title":{"en":"Facility Design, Layout, and Organization","zh":"设施设计、布局与组织"},"domain":{"en":"Organization and Administration","zh":"组织与管理"},"minutes":110,"source":"Essentials, 5th ed., Ch. 25 · DCO Organization and Administration A-B","objectives":[{"en":"Plan a safe strength and conditioning facility from program needs, traffic, equipment, space, and access.","zh":"根据计划需求、人流、设备、空间和通行设计安全体能设施。"},{"en":"Inspect, maintain, clean, document, and replace equipment using defensible procedures.","zh":"用可追溯程序检查、维护、清洁、记录并更换设备。"}],"sections":[{"id":"planning","title":{"en":"From program mission to floor plan","zh":"从项目使命到平面图"},"explanation":["Facility design starts with users and programming: number and type of athletes, supervision ratios, exercise selection, peak traffic, accessibility, staffing, budget, and future growth. A visually impressive room that cannot support scheduled groups is a failed design.","Consult architects, engineers, risk management, accessibility specialists, coaches, and equipment manufacturers. Building codes and manufacturer clearance requirements take precedence over generic rules."],"details":["Estimate simultaneous users and stations from the busiest training block.","Separate high-speed lanes, free weights, platforms, machines, storage, offices, rehabilitation, and circulation as needed.","Plan ceiling height, floor load, ventilation, lighting, noise, power, water, drainage, and technology.","Provide accessible entry, routes, equipment options, restrooms, and emergency access.","Design for sight lines so staff can supervise without blind zones."],"decision":{"en":"Make the training program and safe traffic flow drive the room, not equipment catalog photos.","zh":"让训练计划和安全人流决定房间，而不是设备目录图片。"},"examCue":{"en":"Needs analysis precedes equipment selection and floor-plan finalization.","zh":"需求分析先于设备选择和平面图定稿。"}},{"id":"layout","title":{"en":"Layout, spacing, and traffic","zh":"布局、间距与人流"},"explanation":["Organize equipment by function and risk while maintaining clear walkways and emergency routes. Platforms require space for the lifter, bar, plates, spotters, and missed lifts. Sprint and agility lanes should not cross lifting traffic. Machines need manufacturer-specific operating and access clearances.","Mirrors can provide feedback but must be positioned and protected so they do not encourage unsafe head position or sit in the path of dropped equipment."],"details":["Anchor equipment when specified and confirm floor load capacity.","Keep exits, fire equipment, AED, first-aid supplies, and phones visible and unobstructed.","Store plates, bars, bands, collars, boxes, and implements off walkways.","Use suitable flooring for impact absorption, traction, cleaning, and the equipment zone.","Control entry so only authorized, oriented users access high-risk areas."],"decision":{"en":"Trace athletes, coaches, equipment, and emergency responders through the proposed plan before construction.","zh":"施工前模拟运动员、教练、设备和急救人员在方案中的路径。"},"examCue":{"en":"Exact spacing questions should defer to current codes and manufacturer specifications when those are provided.","zh":"若题目提供现行规范或厂家要求，精确间距应以其为准。"}},{"id":"equipment","title":{"en":"Selection, inspection, and lifecycle","zh":"设备选择、检查与生命周期"},"explanation":["Select commercial equipment rated for the expected user load and environment. Evaluate biomechanics, adjustability, accessibility, durability, warranty, service, parts, cleaning, and total lifecycle cost. A lower purchase price can be more expensive when downtime and replacement are included.","Inspection must be scheduled and documented. Users perform quick pre-use checks; staff conduct more detailed routine inspections; qualified technicians handle manufacturer-required service."],"details":["Remove damaged equipment from service immediately and label or secure it against use.","Check cables, belts, welds, bolts, upholstery, pins, collars, fasteners, anchors, bars, plates, bands, and electronics as relevant.","Follow manufacturer maintenance intervals and retain service records.","Do not improvise structural repairs or use incompatible replacement parts.","Create replacement thresholds based on condition, risk, serviceability, and program demand."],"decision":{"en":"If equipment integrity is uncertain, take it out of service until a qualified determination is made.","zh":"设备完整性不确定时，停止使用直到获得合格判断。"},"examCue":{"en":"Documentation demonstrates that inspection and corrective action actually occurred.","zh":"记录证明检查和纠正行动确实发生。"}},{"id":"operations","title":{"en":"Cleaning, environment, and daily operations","zh":"清洁、环境与日常运营"},"explanation":["Operational safety includes environmental monitoring, cleaning, hydration access, occupancy control, and opening/closing procedures. Cleaning removes soil; disinfection uses an appropriate product and contact time against pathogens. Follow product labels and equipment compatibility.","Heat, humidity, ventilation, lighting, and noise affect performance and risk. Staff should have authority to modify or stop training when conditions exceed policy."],"details":["Publish responsibility and frequency for high-touch surfaces, mats, benches, and shared implements.","Never mix cleaning chemicals unless the label explicitly permits it.","Use signs and barriers for wet floors, maintenance areas, and closed stations.","Record temperature/environmental checks where policy requires them.","Review incidents and near misses to improve layout and procedures."],"decision":{"en":"Treat housekeeping and environmental control as safety systems, not cosmetic tasks.","zh":"把卫生和环境控制当作安全系统，而不是外观工作。"},"examCue":{"en":"Disinfection requires the correct product concentration and wet contact time; a quick wipe may be insufficient.","zh":"消毒需要正确浓度和湿润接触时间；快速擦拭可能不够。"}}],"terms":[{"term":"Sight line","meaning":{"en":"Unobstructed visual path used for supervision.","zh":"用于监督的无障碍视线。"}},{"term":"Lifecycle cost","meaning":{"en":"Purchase plus maintenance, downtime, repair, and replacement costs.","zh":"购买、维护、停机、维修和更换的总成本。"}},{"term":"Preventive maintenance","meaning":{"en":"Scheduled service intended to reduce failure and unsafe deterioration.","zh":"旨在减少故障和不安全老化的计划维护。"}},{"term":"Contact time","meaning":{"en":"Time a surface must remain wet with disinfectant for labeled effectiveness.","zh":"表面必须保持消毒剂湿润以达到标签效果的时间。"}}],"formulas":[{"name":"Area per station","expression":"usable training area ÷ planned simultaneous stations","use":{"en":"Early capacity estimate only; final clearances come from codes and manufacturers.","zh":"仅用于早期容量估算；最终间距以规范和厂家为准。"}},{"name":"Total lifecycle cost","expression":"purchase + installation + maintenance + downtime + disposal/replacement","use":{"en":"Compare equipment beyond sticker price.","zh":"超越标价比较设备成本。"}}],"examChecklist":[{"en":"Perform facility and user needs analysis before purchasing.","zh":"采购前完成设施与用户需求分析。"},{"en":"Protect sight lines, walkways, lifting zones, and emergency access.","zh":"保护视线、通道、举重区和急救通行。"},{"en":"Remove and document damaged equipment.","zh":"停用并记录损坏设备。"},{"en":"Apply label-directed cleaning and disinfection procedures.","zh":"按标签执行清洁消毒程序。"}],"recall":[{"prompt":{"en":"What should determine facility layout first?","zh":"什么应首先决定设施布局？"},"answer":{"en":"Program needs, simultaneous users, supervision, safe movement/traffic, access, and emergency requirements.","zh":"计划需求、同时使用人数、监督、安全移动/人流、无障碍和急救要求。"}},{"prompt":{"en":"What is the action for uncertain equipment integrity?","zh":"设备完整性不确定时怎么办？"},"answer":{"en":"Remove it from service, prevent use, document it, and obtain qualified inspection or repair.","zh":"停止使用、防止他人使用、记录并获得合格检查或维修。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now()),
  ('nsca-cscs-5', 'course-chapter-26', 'en', 'Policies, Procedures, Legal Duties, and Staff', 'Apply duty, standard of care, negligence, documentation, informed consent, privacy, and risk-management principles.', '{"n":26,"title":{"en":"Policies, Procedures, Legal Duties, and Staff","zh":"政策、程序、法律责任与人员管理"},"domain":{"en":"Organization and Administration","zh":"组织与管理"},"minutes":135,"source":"Essentials, 5th ed., Ch. 26 · DCO Organization and Administration A-C","objectives":[{"en":"Apply duty, standard of care, negligence, documentation, informed consent, privacy, and risk-management principles.","zh":"应用注意义务、照护标准、疏忽、记录、知情同意、隐私和风险管理原则。"},{"en":"Build defensible screening, supervision, EAP, staffing, orientation, and incident procedures.","zh":"建立可辩护的筛查、监督、EAP、人员、培训和事件程序。"}],"sections":[{"id":"legal","title":{"en":"Duty, standard of care, and negligence","zh":"注意义务、照护标准与疏忽"},"explanation":["Legal duties arise from the professional relationship and applicable law. Standard of care is the conduct expected of a reasonably prudent professional in similar circumstances, informed by credentials, policies, evidence, codes, and context. Negligence generally requires duty, breach, causation, and damages.","Risk cannot be eliminated, but foreseeable hazards can be reduced through competent staff, screening, appropriate programming, instruction, supervision, maintenance, emergency readiness, and documentation."],"details":["Stay within certification scope and refer medical or nutrition problems appropriately.","Follow current law, facility policy, governing-body rules, and manufacturer instructions.","Waivers may address assumed risk but do not excuse reckless conduct or all negligence.","Informed consent explains material risks, benefits, alternatives, and voluntary participation.","Records should be timely, objective, legible, secure, and retained according to policy/law."],"decision":{"en":"Ask what a prudent professional could foresee, prevent, document, and escalate in this setting.","zh":"询问在此情境下，谨慎专业人员能预见、预防、记录和上报什么。"},"examCue":{"en":"The four negligence elements are duty, breach, causation, and damages.","zh":"疏忽四要素：义务、违背、因果关系和损害。"}},{"id":"screening","title":{"en":"Screening, orientation, and supervision","zh":"筛查、培训与监督"},"explanation":["Before participation, establish identity, consent, health and medical status, emergency contact, and referral/clearance needs using the organization''s current process. Orientation covers rules, equipment, spotting, attire, hygiene, reporting symptoms, and emergency expectations.","Supervision quality depends on athlete age, experience, exercise risk, group size, facility layout, and staff competence. A numerical ratio does not replace positioning, active observation, and control of simultaneous hazards."],"details":["Document clearance restrictions and ensure relevant staff can access them.","Minors require appropriate guardian consent and safeguarding procedures.","Teach new high-risk exercises before loading or group density increases.","Prevent horseplay, unauthorized equipment use, and unsupervised maximal attempts.","Protect privacy when discussing health information or displaying athlete data."],"decision":{"en":"Increase supervision and reduce complexity when users are young, inexperienced, medically restricted, or performing high-risk tasks.","zh":"参与者年幼、经验不足、有医疗限制或执行高风险任务时，加强监督并降低复杂度。"},"examCue":{"en":"Screening identifies need for referral or modification; it is not a medical diagnosis.","zh":"筛查识别转诊或调整需求，并非医疗诊断。"}},{"id":"eap","title":{"en":"Emergency action plan and incident response","zh":"紧急行动计划与事件应对"},"explanation":["An emergency action plan is venue-specific, written, practiced, and accessible. It defines emergency communication, personnel roles, equipment, venue directions and access, response procedures, and documentation. Coordinate with local emergency services and rehearse realistic scenarios.","When an emergency occurs: recognize danger, protect the scene, activate the plan, provide care within training, direct EMS, retrieve equipment, control bystanders, contact required parties, and document after care is transferred."],"details":["AED, first aid, communication, and emergency information must be quickly accessible and checked.","Post exact venue address, access gate, floor/room, and responder route.","Assign primary and backup roles; absence of one employee cannot collapse the plan.","For suspected heat stroke, rapid cooling is time-critical while EMS is activated according to protocol.","After an incident, preserve facts, inspect involved equipment, notify risk management, and debrief without blame."],"decision":{"en":"Rehearse the EAP until each person can perform their role under pressure.","zh":"演练 EAP，直到每个人在压力下都能履行角色。"},"examCue":{"en":"An EAP must be specific to each venue and practiced—not copied and stored unread.","zh":"EAP 必须针对每个场地并经过演练，而不是复制后束之高阁。"}},{"id":"staff","title":{"en":"Staffing, quality assurance, and ethics","zh":"人员、质量保证与伦理"},"explanation":["Hire qualified personnel, verify credentials and background requirements, define scope and job duties, orient them to policies, observe performance, provide continuing education, and document competency. Volunteers and interns require supervision and may not perform duties beyond their preparation.","Ethical practice places athlete welfare first, avoids conflicts of interest, respects dignity and confidentiality, represents credentials accurately, uses evidence honestly, and reports unsafe or abusive conduct through required channels."],"details":["Use written job descriptions, chains of command, and performance standards.","Train staff on safeguarding, harassment, discrimination, privacy, infection control, and emergency procedures.","Audit records, facility inspections, incident trends, and adherence to programming policy.","Maintain professional boundaries and avoid dual relationships that impair judgment.","Update policies after legal, organizational, equipment, or evidence changes."],"decision":{"en":"Build systems that make safe professional behavior observable, teachable, and auditable.","zh":"建立让安全专业行为可观察、可教学、可审核的系统。"},"examCue":{"en":"A credential does not authorize work outside scope; job title and employer pressure do not expand it.","zh":"证书不授权超范围工作；职位名称和雇主压力也不会扩大范围。"}}],"terms":[{"term":"Standard of care","meaning":{"en":"Conduct expected of a reasonably prudent professional in similar circumstances.","zh":"类似情境下合理谨慎专业人员应有的行为。"}},{"term":"Negligence","meaning":{"en":"Failure of a duty that causes compensable harm; analyzed through duty, breach, causation, and damages.","zh":"违反义务并造成可赔偿伤害；按义务、违背、因果和损害分析。"}},{"term":"Informed consent","meaning":{"en":"Voluntary agreement after material information about risks, benefits, and alternatives.","zh":"了解重大风险、收益和替代方案后的自愿同意。"}},{"term":"Emergency action plan","meaning":{"en":"Venue-specific written and rehearsed system for emergency response.","zh":"针对场地、书面并经过演练的紧急响应系统。"}}],"formulas":[{"name":"Risk priority","expression":"likelihood × consequence","use":{"en":"Simple planning matrix to prioritize controls; not a legal formula.","zh":"用于确定控制优先级的简单矩阵；并非法律公式。"}},{"name":"Incident rate","expression":"incidents ÷ exposure units × chosen multiplier","use":{"en":"Track trends consistently across comparable periods.","zh":"在可比时期一致追踪事件趋势。"}}],"examChecklist":[{"en":"Recall all four negligence elements.","zh":"记住疏忽四要素。"},{"en":"Differentiate informed consent, waiver, screening, and medical clearance.","zh":"区分知情同意、免责、筛查和医疗许可。"},{"en":"Name essential EAP components and rehearsal duties.","zh":"说出 EAP 核心组成和演练职责。"},{"en":"Apply scope, privacy, safeguarding, and documentation rules.","zh":"应用执业范围、隐私、保护和记录规则。"}],"recall":[{"prompt":{"en":"What are the four elements of negligence?","zh":"疏忽的四个要素是什么？"},"answer":{"en":"Duty, breach of that duty, causation, and damages.","zh":"义务、违背义务、因果关系和损害。"}},{"prompt":{"en":"What makes an EAP operational rather than merely written?","zh":"什么让 EAP 不只是纸面文件而能真正运行？"},"answer":{"en":"Venue-specific roles, communication, equipment, access directions, regular rehearsal, updates, and post-incident review.","zh":"场地特定的角色、通信、设备、进入路线、定期演练、更新和事件后复盘。"}}]}'::jsonb, '["nsca-essentials-5","nsca-cscs-dco"]'::jsonb, 1, 'published', now())
